INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37085, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "重い箱を二人で運ぶだ。", "corrected_sentence": "重い箱を二人で運んだ。", "error_description": "活用の誤り：過去形は「運んだ」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "はこぶ", "is_correct": true, "explanation": "「ため」の前は辞書形。"}, {"text": "はこんで", "is_correct": false, "explanation": "て形は「ため」に続かない。"}, {"text": "はこぼう", "is_correct": false, "explanation": "意向形は「ため」に続かない。"}, {"text": "はこべ", "is_correct": false, "explanation": "命令形は「ため」に続かない。"}], "correct_form": "はこぶ", "base_form": "運ぶ", "form_label": "活用", "sentence_index": 1, "explanations": {"はこぶ": "「ため」の前は辞書形。", "はこんで": "て形は「ため」に続かない。", "はこぼう": "意向形は「ため」に続かない。", "はこべ": "命令形は「ため」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97dbef9f-d21a-483e-a767-e6ed239a2667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37085, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「足を運ぶ」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "主格になり「足が運ぶ」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "着点を示し、目的語にならない。"}, {"text": "で", "is_correct": false, "explanation": "手段を示し、この位置では非文。"}], "correct_answer": "を", "explanations": {"を": "「足を運ぶ」の目的語を示す。", "が": "主格になり「足が運ぶ」は不自然。", "に": "着点を示し、目的語にならない。", "で": "手段を示し、この位置では非文。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97dbef9f-d21a-483e-a767-e6ed239a2667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37085, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "運ぶ", "is_correct": true, "explanation": "はこぶ。正解。"}, {"text": "箱舟", "is_correct": false, "explanation": "はこぶね：最後に「ね」が加わる一モーラ差。"}, {"text": "ハブ", "is_correct": false, "explanation": "はぶ：「こ」がない一モーラ差。"}, {"text": "瘤", "is_correct": false, "explanation": "こぶ：最初の「は」がない一モーラ差。"}], "explanations": {"運ぶ": "はこぶ。正解。", "箱舟": "はこぶね：最後に「ね」が加わる一モーラ差。", "ハブ": "はぶ：「こ」がない一モーラ差。", "瘤": "こぶ：最初の「は」がない一モーラ差。"}, "sentence_index": null, "correct_answer": "運ぶ"}, "level_3": {"options": [{"text": "運ば", "is_correct": true, "explanation": "病院へ移されたという意味で自然。"}, {"text": "書か", "is_correct": false, "explanation": "意味：けが人は書かれない。"}, {"text": "読ま", "is_correct": false, "explanation": "意味：けが人を読むことはない。"}, {"text": "笑わ", "is_correct": false, "explanation": "連語：「病院に笑われた」は文意に合わない。"}], "explanations": {"運ば": "病院へ移されたという意味で自然。", "書か": "意味：けが人は書かれない。", "読ま": "意味：けが人を読むことはない。", "笑わ": "連語：「病院に笑われた」は文意に合わない。"}, "sentence_index": 6, "correct_answer": "運ば"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼はお皿が台所へ運んでいる。", "explanation": "助詞の混同：目的語は「を」。"}, {"text": "彼はお皿を三人台所へ運んでいる。", "explanation": "助数詞の誤り：皿は「枚」で数える。"}, {"text": "彼は昨日お皿を台所へ運んでいる。", "explanation": "アスペクトの誤り：「昨日」なら「運んだ」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97dbef9f-d21a-483e-a767-e6ed239a2667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37085, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "いすを運ぶのを手伝った。明日も運びました。", "corrected_sentence": "いすを運ぶのを手伝った。明日も運びます。", "error_description": "活用の誤り：「明日」には未来の「運びます」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "運べ", "is_correct": true, "explanation": "可能形「運べる」で、運ぶ力があることを表す。"}, {"text": "運ば", "is_correct": false, "explanation": "「運ばる」という形はない。「運ばれる」なら受身。"}, {"text": "運び", "is_correct": false, "explanation": "「運びる」という形はない。"}, {"text": "運ぼ", "is_correct": false, "explanation": "「運ぼる」という形はない。"}], "correct_form": "運べ", "base_form": "運ぶ", "form_label": "活用", "sentence_index": 7, "explanations": {"運べ": "可能形「運べる」で、運ぶ力があることを表す。", "運ば": "「運ばる」という形はない。「運ばれる」なら受身。", "運び": "「運びる」という形はない。", "運ぼ": "「運ぼる」という形はない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97dbef9f-d21a-483e-a767-e6ed239a2667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37085, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「多く」と「人」をつないで修飾する。"}, {"text": "を", "is_correct": false, "explanation": "目的語が二重になり非文。"}, {"text": "に", "is_correct": false, "explanation": "「多くに人を」は非文。"}, {"text": "で", "is_correct": false, "explanation": "「多くで人を」は不自然。"}], "correct_answer": "の", "explanations": {"の": "「多く」と「人」をつないで修飾する。", "を": "目的語が二重になり非文。", "に": "「多くに人を」は非文。", "で": "「多くで人を」は不自然。"}, "error_tags": {"を": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97dbef9f-d21a-483e-a767-e6ed239a2667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52244, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "唯一", "is_correct": true, "explanation": "ゆいいつ。正解。"}, {"text": "唯物", "is_correct": false, "explanation": "ゆいぶつ：三つ目の「い」が「ぶ」に変わる一モーラ差。"}, {"text": "由緒", "is_correct": false, "explanation": "ゆいしょ：後半「いつ」が「しょ」に変わる近い音。"}, {"text": "結納", "is_correct": false, "explanation": "ゆいのう：後半「いつ」が「のう」に変わる近い音。"}], "explanations": {"唯一": "ゆいいつ。正解。", "唯物": "ゆいぶつ：三つ目の「い」が「ぶ」に変わる一モーラ差。", "由緒": "ゆいしょ：後半「いつ」が「しょ」に変わる近い音。", "結納": "ゆいのう：後半「いつ」が「のう」に変わる近い音。"}, "sentence_index": null, "correct_answer": "唯一"}, "level_3": {"options": [{"text": "唯一", "is_correct": true, "explanation": "「唯一無二」で一つしかないこと。"}, {"text": "最初", "is_correct": false, "explanation": "連語：「最初無二」という語はない。"}, {"text": "全部", "is_correct": false, "explanation": "意味：すべてで、一つだけの意味にならない。"}, {"text": "普通", "is_correct": false, "explanation": "意味：ありふれた意味で文意と逆。"}], "explanations": {"唯一": "「唯一無二」で一つしかないこと。", "最初": "連語：「最初無二」という語はない。", "全部": "意味：すべてで、一つだけの意味にならない。", "普通": "意味：ありふれた意味で文意と逆。"}, "sentence_index": 0, "correct_answer": "唯一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "それが唯一な方法だと思う。", "explanation": "活用の誤り：「唯一」は「の」で名詞を修飾する。"}, {"text": "唯一の方法が三つある。", "explanation": "意味の誤り：一つだけなのに三つあるは矛盾。"}, {"text": "それが唯一が方法だと思う。", "explanation": "助詞の誤り：名詞を修飾するときは「唯一の」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97dbef9f-d21a-483e-a767-e6ed239a2667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
