INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36509, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "前", "is_correct": true, "explanation": "まえ。正解。"}, {"text": "豆", "is_correct": false, "explanation": "まめ：「え」が「め」に変わる一モーラ差。"}, {"text": "上", "is_correct": false, "explanation": "うえ：「ま」が「う」に変わる一モーラ差。"}, {"text": "家", "is_correct": false, "explanation": "いえ：「ま」が「い」に変わる一モーラ差。"}, {"text": "孫", "is_correct": false, "explanation": "まご：「え」が「ご」に変わる一モーラ差。"}], "explanations": {"前": "まえ。正解。", "豆": "まめ：「え」が「め」に変わる一モーラ差。", "上": "うえ：「ま」が「う」に変わる一モーラ差。", "家": "いえ：「ま」が「い」に変わる一モーラ差。", "孫": "まご：「え」が「ご」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "前"}, "level_3": {"options": [{"text": "前", "is_correct": true, "explanation": "検証に向き合う場面を表す。"}, {"text": "横", "is_correct": false, "explanation": "意味：横では向き合う関係にならない。"}, {"text": "外", "is_correct": false, "explanation": "意味：検証の外では無力化されない。"}, {"text": "隣", "is_correct": false, "explanation": "意味：隣は並ぶ位置で文意に合わない。"}], "explanations": {"前": "検証に向き合う場面を表す。", "横": "意味：横では向き合う関係にならない。", "外": "意味：検証の外では無力化されない。", "隣": "意味：隣は並ぶ位置で文意に合わない。"}, "sentence_index": 0, "correct_answer": "前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寝る前で歯をみがきます。", "explanation": "助詞の混同：時は「前に」。"}, {"text": "寝た前に歯をみがきます。", "explanation": "活用の誤り：「前」の前は辞書形「寝る」。"}, {"text": "前に寝る歯をみがきます。", "explanation": "語順の誤り：「寝る前に」の順が正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97dbef9f-d21a-483e-a767-e6ed239a2667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
