INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36509, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「夜明け前」が「空気」を修飾する。"}, {"text": "を", "is_correct": false, "explanation": "目的語の標示で修飾にならない。"}, {"text": "で", "is_correct": false, "explanation": "「夜明け前で空気」は非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示し、この位置では非文。"}], "correct_answer": "の", "explanations": {"の": "「夜明け前」が「空気」を修飾する。", "を": "目的語の標示で修飾にならない。", "で": "「夜明け前で空気」は非文。", "へ": "方向を示し、この位置では非文。"}, "error_tags": {"を": "object_marking", "で": "instrument", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "後", "is_correct": true, "explanation": "時間で前の反対は後。"}, {"text": "横", "is_correct": false, "explanation": "位置を表すが前の対義語ではない。"}, {"text": "中", "is_correct": false, "explanation": "内側を表し対義語ではない。"}, {"text": "上", "is_correct": false, "explanation": "高い位置で対義語ではない。"}], "correct_answer": "後", "explanations": {"後": "時間で前の反対は後。", "横": "位置を表すが前の対義語ではない。", "中": "内側を表し対義語ではない。", "上": "高い位置で対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97dbef9f-d21a-483e-a767-e6ed239a2667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
