INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35645, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ほかのものと区別して、はっきりと決めること。また、はっきり決まっていること。", "primary_collocate": null, "pronunciation": "とくてい", "ipa": "tokɯteː", "syllable_count": 4, "sentences": [{"text": "犯行の客観的裏付けという目的のため、この緻密な照合作業を経て、初めて不可謬な身元特定が達成されるのである。", "target_word": "特定", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "色は単なる装飾ではなく、記号論の観点から特定のメッセージを伝える記号として機能するのだ。", "target_word": "特定", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "犯人をすぐに特定した。", "target_word": "特定", "complexity_tier": "T3", "furigana": "はんにん とくてい", "sentence_source": "generated"}, {"text": "原因の特定は難しい。", "target_word": "特定", "complexity_tier": "T3", "furigana": "げんいん とくてい むずか", "sentence_source": "generated"}, {"text": "特定の人だけが入れる。", "target_word": "特定", "complexity_tier": "T3", "furigana": "とくてい ひと はい", "sentence_source": "generated"}, {"text": "場所を特定できなかった。", "target_word": "特定", "complexity_tier": "T3", "furigana": "ばしょ とくてい", "sentence_source": "generated"}, {"text": "特定の日に会いたい。", "target_word": "特定", "complexity_tier": "T3", "furigana": "とくてい ひ あ", "sentence_source": "generated"}, {"text": "名前から相手を特定する。", "target_word": "特定", "complexity_tier": "T3", "furigana": "なまえ あいて とくてい", "sentence_source": "generated"}, {"text": "問題を特定してから直す。", "target_word": "特定", "complexity_tier": "T3", "furigana": "もんだい とくてい なお", "sentence_source": "generated"}, {"text": "特定の色が好きだ。", "target_word": "特定", "complexity_tier": "T3", "furigana": "とくてい いろ す", "sentence_source": "generated"}], "morphological_forms": [{"form": "特定する", "label": "派生"}, {"form": "特定の", "label": "派生"}, {"form": "特定した", "label": "活用"}, {"form": "特定できる", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | ほかと区別してはっきり決めること", "collocate_grounding": {"stat