INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35019, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある物事についての知らせや、知識、データ。", "primary_collocate": null, "pronunciation": "じょうほう", "ipa": "dʑoːhoː", "syllable_count": 4, "sentences": [{"text": "犯罪現場という苛烈な情報の奔流の中から、科学捜査の担い手は微細な痕跡を拾い上げる。", "target_word": "情報", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "なぜならば、無数の主体が限られた情報に基づき絶えず適応を繰り返す過程で、意図せぬイノベーションやシステミック・リスクが突発的に顕現するからに他ならない。", "target_word": "情報", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "ネットで情報を集めた。", "target_word": "情報", "complexity_tier": "T3", "furigana": "じょうほう あつ", "sentence_source": "generated"}, {"text": "新しい情報が入った。", "target_word": "情報", "complexity_tier": "T3", "furigana": "あたら じょうほう はい", "sentence_source": "generated"}, {"text": "その情報は正しくない。", "target_word": "情報", "complexity_tier": "T3", "furigana": "じょうほう ただ", "sentence_source": "generated"}, {"text": "天気の情報を見る。", "target_word": "情報", "complexity_tier": "T3", "furigana": "てんき じょうほう み", "sentence_source": "generated"}, {"text": "情報が多すぎて困る。", "target_word": "情報", "complexity_tier": "T3", "furigana": "じょうほう おお こま", "sentence_source": "generated"}, {"text": "友達に情報を伝えた。", "target_word": "情報", "complexity_tier": "T3", "furigana": "ともだち じょうほう つた", "sentence_source": "generated"}, {"text": "正しい情報を選ぼう。", "target_word": "情報", "complexity_tier": "T3", "furigana": "ただ じょうほう えら", "sentence_source": "generated"}, {"text": "駅で旅行の情報をもらった。", "target_word": "情報", "complexity_tier": "T3", "furigana": "えき りょこう じょうほう", "sentence_source": "generated"}], "morphological_forms": [{"form": "情報化", "label": "派生"}, {"form": "情報源", "label": "派生"}, {"form": "個人情報", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物事についての知らせやデータ", "collocate_grounding": {"status": "no_source", "reason": "no