INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52180, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "その次に。続いて。順序を表すときに使う。", "primary_collocate": null, "pronunciation": "ついで", "ipa": "tsɯide", "syllable_count": 3, "sentences": [{"text": "次いで、分岐や終点といった特徴点の配列を精密に分析する。", "target_word": "次いで", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "次いで、ラズベリー等のジャムを対になる片割れ、あるいは同一の切片上に重ね合わせる。\n\n甘味と塩気、滑らかさと顆粒感が口腔内で織りなす対照的なハーモニーは、単なる栄養補給の域を超え、短時間での認知機能回復をもたらし、合理性と美学が融合した食の営みとして完成する。", "target_word": "次いで", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "まず手を洗い、次いで顔を洗う。", "target_word": "次いで", "complexity_tier": "T3", "furigana": "て あら つ かお あら", "sentence_source": "generated"}, {"text": "まず駅に行き、次いで店に行く。", "target_word": "次いで", "complexity_tier": "T3", "furigana": "えき い つ みせ い", "sentence_source": "generated"}, {"text": "次いで、野菜を切ります。", "target_word": "次いで", "complexity_tier": "T3", "furigana": "つ やさい き", "sentence_source": "generated"}, {"text": "社長が話し、次いで部長が話した。", "target_word": "次いで", "complexity_tier": "T3", "furigana": "しゃちょう はな つ ぶちょう はな", "sentence_source": "generated"}, {"text": "一位は兄、次いで弟だった。", "target_word": "次いで", "complexity_tier": "T3", "furigana": "いちい あに つ おとうと", "sentence_source": "generated"}, {"text": "次いで、皿に料理を並べる。", "target_word": "次いで", "complexity_tier": "T3", "furigana": "つ さら りょうり なら", "sentence_source": "generated"}, {"text": "雨が降り、次いで雪になった。", "target_word": "次いで", "complexity_tier": "T3", "furigana": "あめ ふ つ ゆき", "sentence_source": "generated"}, {"text": "次いで、二つ目の問題に進む。", "target_word": "次いで", "complexity_tier": "T3", "furigana": "つ ふた め もんだい すす", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "副詞 | 前の事柄に続いて次に", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: contains vocabulary far above tier T3: 切片 (Zipf 1.86)']::text[], '1e30e7d5-6549-4cf5-8de4-d85428661a40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52182, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある事が正しいことを示す証拠や根拠。また、それで支えること。", "primary_collocate": null, "pronunciation": "うらづけ", "ipa": "ɯɾadzɯke", "syllable_count": 4, "sentences": [{"text": "犯行の客観的裏付けという目的のため、この緻密な照合作業を経て、初めて不可謬な身元特定が達成されるのである。", "target_word": "裏付け", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "この際、脂質の膜がジャムの水分浸透を防ぐバリアーとして機能するという科学的裏付けも無視できない。", "target_word": "裏付け", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "その話には裏付けがない。", "target_word": "裏付け", "complexity_tier": "T3", "furigana": "はなし うらづ", "sentence_source": "generated"}, {"text": "データが説の裏付けになった。", "target_word": "裏付け", "complexity_tier": "T3", "furigana": "せつ うらづ", "sentence_source": "generated"}, {"text": "裏付けのある意見を言おう。", "target_word": "裏付け", "complexity_tier": "T3", "furigana": "うらづ いけん い", "sentence_source": "generated"}, {"text": "証言の裏付けを取る。", "target_word": "裏付け", "complexity_tier": "T3", "furigana": "しょうげん うらづ と", "sentence_source": "generated"}, {"text": "実験が考えの裏付けになっている。", "target_word": "裏付け", "complexity_tier": "T3", "furigana": "じっけん かんが うらづ", "sentence_source": "generated"}, {"text": "裏付けとなる資料を探す。", "target_word": "裏付け", "complexity_tier": "T3", "furigana": "うらづ しりょう さが", "sentence_source": "generated"}, {"text": "彼の自信には裏付けがある。", "target_word": "裏付け", "complexity_tier": "T3", "furigana": "かれ じしん うらづ", "sentence_source": "generated"}, {"text": "記者は記事の裏付けを集めた。", "target_word": "裏付け", "complexity_tier": "T3", "furigana": "きしゃ きじ うらづ あつ", "sentence_source": "generated"}], "morphological_forms": [{"form": "裏付ける", "label": "派生"}, {"form": "裏付けた", "label": "活用"}, {"form": "裏付けられる", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | 正しさを示す証拠や根拠", "collocate_grounding": {"status": "no_sourc