INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38629, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "生きている生物のからだ。また、生きている生物そのもの。", "primary_collocate": null, "pronunciation": "せいたい", "ipa": "seːtai", "syllable_count": 4, "sentences": [{"text": "それは、誰しもが生涯唯一無二の隆線パターンを有するという生体認証の絶対性に拠る。", "target_word": "生体", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "例えば、穀物や豆類を主食として摂取する際、その細胞壁に阻まれた栄養は、生体利用率が低いという宿命を背負っている。", "target_word": "生体", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "生体の中で薬が働く。", "target_word": "生体", "complexity_tier": "T3", "furigana": "せいたい なか くすり はたら", "sentence_source": "generated"}, {"text": "この機械は生体を調べる。", "target_word": "生体", "complexity_tier": "T3", "furigana": "きかい せいたい しら", "sentence_source": "generated"}, {"text": "生体の反応を調べる。", "target_word": "生体", "complexity_tier": "T3", "furigana": "せいたい はんのう しら", "sentence_source": "generated"}, {"text": "生体は温度の変化に弱い。", "target_word": "生体", "complexity_tier": "T3", "furigana": "せいたい おんど へんか よわ", "sentence_source": "generated"}, {"text": "生体の仕組みを学んでいる。", "target_word": "生体", "complexity_tier": "T3", "furigana": "せいたい しく まな", "sentence_source": "generated"}, {"text": "水は生体にとって大切だ。", "target_word": "生体", "complexity_tier": "T3", "furigana": "みず せいたい たいせつ", "sentence_source": "generated"}, {"text": "生体から細胞を取り出す。", "target_word": "生体", "complexity_tier": "T3", "furigana": "せいたい さいぼう と だ", "sentence_source": "generated"}, {"text": "指紋は生体の特徴の一つだ。", "target_word": "生体", "complexity_tier": "T3", "furigana": "しもん せいたい とくちょう ひと", "sentence_source": "generated"}], "morphological_forms": [{"form": "生体認証", "label": "派生"}, {"form": "生体反応", "label": "派生"}, {"form": "生体組織", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 生きている生物のからだ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e30e7d5-6549-4cf5-8de4-d85428661a40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
