INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53440, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "捉える", "is_correct": true, "explanation": "とらえる。"}, {"text": "堪える", "is_correct": false, "explanation": "こらえる：一モーラ目「と」が「こ」に変わる。"}, {"text": "唱える", "is_correct": false, "explanation": "となえる：二モーラ目「ら」が「な」に変わる。"}, {"text": "途絶える", "is_correct": false, "explanation": "とだえる：二モーラ目「ら」が「だ」に変わる。"}], "explanations": {"捉える": "とらえる。", "堪える": "こらえる：一モーラ目「と」が「こ」に変わる。", "唱える": "となえる：二モーラ目「ら」が「な」に変わる。", "途絶える": "とだえる：二モーラ目「ら」が「だ」に変わる。"}, "sentence_index": null, "correct_answer": "捉える"}, "level_3": {"options": [{"text": "捉え", "is_correct": true, "explanation": "正解：文脈に合う語。"}, {"text": "捨て", "is_correct": false, "explanation": "意味：見えない指紋を「捨てられぬ」は文脈に合わない。"}, {"text": "植え", "is_correct": false, "explanation": "意味：指紋は植えるものではない。"}, {"text": "教え", "is_correct": false, "explanation": "項構造：指紋を「教える」相手がいない。"}], "explanations": {"捉え": "正解：文脈に合う語。", "捨て": "意味：見えない指紋を「捨てられぬ」は文脈に合わない。", "植え": "意味：指紋は植えるものではない。", "教え": "項構造：指紋を「教える」相手がいない。"}, "sentence_index": 0, "correct_answer": "捉え"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "問題が正しく捉えてほしい。", "explanation": "助詞の混同：目的語は「を」で示す。"}, {"text": "昨日、問題を正しく捉えている。", "explanation": "アスペクトの誤り：「捉えた」が合う。"}, {"text": "問題を正しくほしい捉えて。", "explanation": "語順の誤り：「捉えてほしい」の順が逆になっている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5b10ec-372c-49bd-8824-00915fab2743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
