INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52182, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "裏付け", "is_correct": true, "explanation": "うらづけ。"}, {"text": "裏書き", "is_correct": false, "explanation": "うらがき：「づけ」の部分が「がき」に変わる。"}, {"text": "片付け", "is_correct": false, "explanation": "かたづけ：前半「うら」が「かた」に変わる。"}, {"text": "浅漬け", "is_correct": false, "explanation": "あさづけ：前半「うら」が「あさ」に変わる。"}], "explanations": {"裏付け": "うらづけ。", "裏書き": "うらがき：「づけ」の部分が「がき」に変わる。", "片付け": "かたづけ：前半「うら」が「かた」に変わる。", "浅漬け": "あさづけ：前半「うら」が「あさ」に変わる。"}, "sentence_index": null, "correct_answer": "裏付け"}, "level_3": {"options": [{"text": "裏付け", "is_correct": true, "explanation": "正解：文脈に合う語。"}, {"text": "冗談", "is_correct": false, "explanation": "意味：冗談は照合作業の目的にならない。"}, {"text": "休憩", "is_correct": false, "explanation": "意味：犯行の「休憩」は文脈に合わない。"}, {"text": "遠慮", "is_correct": false, "explanation": "連語：「客観的遠慮」とは言わない。"}], "explanations": {"裏付け": "正解：文脈に合う語。", "冗談": "意味：冗談は照合作業の目的にならない。", "休憩": "意味：犯行の「休憩」は文脈に合わない。", "遠慮": "連語：「客観的遠慮」とは言わない。"}, "sentence_index": 0, "correct_answer": "裏付け"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "データが説の裏付けがなった。", "explanation": "助詞の混同：「〜になる」の「に」が正しい。"}, {"text": "データが説の裏付けに一匹なった。", "explanation": "助数詞の誤り：裏付けは「匹」で数えない。"}, {"text": "明日、データが説の裏付けになった。", "explanation": "時制の誤り：「明日」と過去形が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5b10ec-372c-49bd-8824-00915fab2743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
