INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52458, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "苛烈", "is_correct": true, "explanation": "「かれつ」。程度が非常に激しいさま。"}, {"text": "華麗", "is_correct": false, "explanation": "「かれい」。美しく華やかなこと。"}, {"text": "枯れ木", "is_correct": false, "explanation": "「かれき」。枯れた木。"}, {"text": "破裂", "is_correct": false, "explanation": "「はれつ」。勢いよく破れること。"}, {"text": "仮説", "is_correct": false, "explanation": "「かせつ」。仮に立てた説。"}], "explanations": {"苛烈": "「かれつ」。程度が非常に激しいさま。", "華麗": "「かれい」。美しく華やかなこと。", "枯れ木": "「かれき」。枯れた木。", "破裂": "「はれつ」。勢いよく破れること。", "仮説": "「かせつ」。仮に立てた説。"}, "sentence_index": null, "correct_answer": "苛烈"}, "level_3": {"options": [{"text": "苛烈", "is_correct": true, "explanation": "激しい情報の流れを表す。"}, {"text": "穏和", "is_correct": false, "explanation": "「穏和な情報の奔流」は意味が合わない。"}, {"text": "平凡", "is_correct": false, "explanation": "奔流の激しさに合わない。"}, {"text": "清潔", "is_correct": false, "explanation": "情報の様子を表す語ではない。"}], "explanations": {"苛烈": "激しい情報の流れを表す。", "穏和": "「穏和な情報の奔流」は意味が合わない。", "平凡": "奔流の激しさに合わない。", "清潔": "情報の様子を表す語ではない。"}, "sentence_index": 0, "correct_answer": "苛烈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の性格は苛烈で、いつもにこにこしている。", "explanation": "にこにこする様子と矛盾する。"}, {"text": "苛烈なそよ風が気持ちよい。", "explanation": "そよ風は弱い風で、苛烈とは合わない。"}, {"text": "この料理は苛烈においしい。", "explanation": "おいしさの程度には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '189b8605-8f53-4079-9c03-27dd2cfed871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
