INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52458, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "苛烈", "is_correct": true, "explanation": "「かれつ」と読む。"}, {"text": "加熱", "is_correct": false, "explanation": "「かねつ」。熱を加えること。"}, {"text": "下劣", "is_correct": false, "explanation": "「げれつ」。品性がいやしいこと。"}, {"text": "可決", "is_correct": false, "explanation": "「かけつ」。議案を認めて決めること。"}, {"text": "歌劇", "is_correct": false, "explanation": "「かげき」。オペラ。"}], "explanations": {"苛烈": "「かれつ」と読む。", "加熱": "「かねつ」。熱を加えること。", "下劣": "「げれつ」。品性がいやしいこと。", "可決": "「かけつ」。議案を認めて決めること。", "歌劇": "「かげき」。オペラ。"}, "sentence_index": null, "correct_answer": "苛烈"}, "level_3": {"options": [{"text": "苛烈", "is_correct": true, "explanation": "戦場の激しく厳しい様子を表す。"}, {"text": "温厚", "is_correct": false, "explanation": "人の性格に使う語。"}, {"text": "上品", "is_correct": false, "explanation": "「戦場の様子は上品だった」は意味が通らない。"}, {"text": "新鮮", "is_correct": false, "explanation": "戦場の様子に合わない。"}], "explanations": {"苛烈": "戦場の激しく厳しい様子を表す。", "温厚": "人の性格に使う語。", "上品": "「戦場の様子は上品だった」は意味が通らない。", "新鮮": "戦場の様子に合わない。"}, "sentence_index": 6, "correct_answer": "苛烈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "苛烈な笑顔で赤ちゃんをあやした。", "explanation": "優しい笑顔に苛烈は合わない。"}, {"text": "このお茶は苛烈にぬるい。", "explanation": "ぬるさの強調には使わない。"}, {"text": "彼女は苛烈に小さな声で話した。", "explanation": "小さな声の様子に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '189b8605-8f53-4079-9c03-27dd2cfed871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
