INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52598, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "絶対", "is_correct": true, "explanation": "「ぜったい」。"}, {"text": "接待", "is_correct": false, "explanation": "「せったい」。客をもてなすこと。"}, {"text": "全体", "is_correct": false, "explanation": "「ぜんたい」。すべての部分。"}, {"text": "絶景", "is_correct": false, "explanation": "「ぜっけい」。すばらしい景色。"}], "explanations": {"絶対": "「ぜったい」。", "接待": "「せったい」。客をもてなすこと。", "全体": "「ぜんたい」。すべての部分。", "絶景": "「ぜっけい」。すばらしい景色。"}, "sentence_index": null, "correct_answer": "絶対"}, "level_3": {"options": [{"text": "絶対", "is_correct": true, "explanation": "「絶対性」で、疑いようもなく確かな性質。"}, {"text": "相対", "is_correct": false, "explanation": "「相対性」では確かさの根拠にならない。"}, {"text": "一時", "is_correct": false, "explanation": "「一時性」は唯一無二と合わない。"}, {"text": "偶然", "is_correct": false, "explanation": "「偶然性」は認証の確かさと逆。"}], "explanations": {"絶対": "「絶対性」で、疑いようもなく確かな性質。", "相対": "「相対性」では確かさの根拠にならない。", "一時": "「一時性」は唯一無二と合わない。", "偶然": "「偶然性」は認証の確かさと逆。"}, "sentence_index": 0, "correct_answer": "絶対"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店は絶対に少し安い。", "explanation": "「少し」とあいまいな程度に絶対は合わない。"}, {"text": "たぶん絶対に雨だと思う。", "explanation": "「たぶん」と「絶対」が矛盾する。"}, {"text": "絶対のケーキを三つ買った。", "explanation": "物の種類を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '189b8605-8f53-4079-9c03-27dd2cfed871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
