INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52598, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "この位置に入る正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「を」では述語「機能している」の主題にならない。"}, {"text": "に", "is_correct": false, "explanation": "主題を示せない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所の意味になる。"}], "correct_answer": "は", "explanations": {"は": "この位置に入る正しい助詞。", "を": "「を」では述語「機能している」の主題にならない。", "に": "主題を示せない。", "で": "手段や場所の意味になる。"}, "error_tags": {"を": "object", "に": "target", "で": "location"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "相対", "is_correct": true, "explanation": "他との関係で決まること。絶対の反対。"}, {"text": "確実", "is_correct": false, "explanation": "確かさを表す類義の語。"}, {"text": "必然", "is_correct": false, "explanation": "確かさを表し反対ではない。"}, {"text": "完全", "is_correct": false, "explanation": "欠けがないことで反対ではない。"}], "correct_answer": "相対", "explanations": {"相対": "他との関係で決まること。絶対の反対。", "確実": "確かさを表す類義の語。", "必然": "確かさを表し反対ではない。", "完全": "欠けがないことで反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '189b8605-8f53-4079-9c03-27dd2cfed871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52598, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "絶対", "is_correct": true, "explanation": "「ぜったい」と読む。"}, {"text": "絶大", "is_correct": false, "explanation": "「ぜつだい」。非常に大きいこと。"}, {"text": "設定", "is_correct": false, "explanation": "「せってい」。決めて設けること。"}, {"text": "前代", "is_correct": false, "explanation": "「ぜんだい」。前の時代。"}, {"text": "絶交", "is_correct": false, "explanation": "「ぜっこう」。付き合いをやめること。"}], "explanations": {"絶対": "「ぜったい」と読む。", "絶大": "「ぜつだい」。非常に大きいこと。", "設定": "「せってい」。決めて設けること。", "前代": "「ぜんだい」。前の時代。", "絶交": "「ぜっこう」。付き合いをやめること。"}, "sentence_index": null, "correct_answer": "絶対"}, "level_3": {"options": [{"text": "絶対", "is_correct": true, "explanation": "「絶対に守る」で、必ず守ること。"}, {"text": "相対", "is_correct": false, "explanation": "「相対に守る」とは言わない。"}, {"text": "全然", "is_correct": false, "explanation": "後ろに否定が必要。"}, {"text": "多少", "is_correct": false, "explanation": "約束を守る強い決意に合わない。"}], "explanations": {"絶対": "「絶対に守る」で、必ず守ること。", "相対": "「相対に守る」とは言わない。", "全然": "後ろに否定が必要。", "多少": "約束を守る強い決意に合わない。"}, "sentence_index": 6, "correct_answer": "絶対"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は絶対な人で、背が高い。", "explanation": "人の性質として「絶対な」とは言わない。"}, {"text": "絶対を一杯飲んだ。", "explanation": "飲み物ではない。"}, {"text": "駅まで絶対分かかる。", "explanation": "時間の量を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '189b8605-8f53-4079-9c03-27dd2cfed871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
