INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37639, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "作用", "is_correct": true, "explanation": "「さよう」。他に与える働き。"}, {"text": "左右", "is_correct": false, "explanation": "「さゆう」。左と右。"}, {"text": "火曜", "is_correct": false, "explanation": "「かよう」。週の曜日。"}, {"text": "使用", "is_correct": false, "explanation": "「しよう」。使うこと。"}, {"text": "多様", "is_correct": false, "explanation": "「たよう」。いろいろあること。"}], "explanations": {"作用": "「さよう」。他に与える働き。", "左右": "「さゆう」。左と右。", "火曜": "「かよう」。週の曜日。", "使用": "「しよう」。使うこと。", "多様": "「たよう」。いろいろあること。"}, "sentence_index": null, "correct_answer": "作用"}, "level_3": {"options": [{"text": "作用", "is_correct": true, "explanation": "「相互作用」で、互いに影響し合うこと。"}, {"text": "相互理解", "is_correct": false, "explanation": "「相互」と重なり語が成り立たない形になる。"}, {"text": "散歩", "is_correct": false, "explanation": "意味が通らない。"}, {"text": "記念", "is_correct": false, "explanation": "意味が通らない。"}], "explanations": {"作用": "「相互作用」で、互いに影響し合うこと。", "相互理解": "「相互」と重なり語が成り立たない形になる。", "散歩": "意味が通らない。", "記念": "意味が通らない。"}, "sentence_index": 0, "correct_answer": "作用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "作用を三つ買ってきた。", "explanation": "物ではない。"}, {"text": "作用が公園で遊んでいる。", "explanation": "人や動物ではない。"}, {"text": "作用な服を着る。", "explanation": "形容の語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '189b8605-8f53-4079-9c03-27dd2cfed871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
