INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35214, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物がどこかに存在する。", "primary_collocate": null, "pronunciation": "ある", "ipa": "aɾɯ", "syllable_count": 2, "sentences": [{"text": "机の上に本が有る。", "target_word": "有る", "complexity_tier": "T3", "furigana": "つくえ うえ ほん あ", "sentence_source": "generated"}, {"text": "この町には古い寺が有る。", "target_word": "有る", "complexity_tier": "T3", "furigana": "まち ふる てら あ", "sentence_source": "generated"}, {"text": "箱の中に何が有るか見た。", "target_word": "有る", "complexity_tier": "T3", "furigana": "はこ なか なに あ み", "sentence_source": "generated"}, {"text": "駅の近くに店が有ります。", "target_word": "有り", "complexity_tier": "T3", "furigana": "えき ちか みせ あ", "sentence_source": "generated"}, {"text": "昔ここに池が有った。", "target_word": "有った", "complexity_tier": "T3", "furigana": "むかし いけ あ", "sentence_source": "generated"}, {"text": "時間が有れば行きたい。", "target_word": "有れば", "complexity_tier": "T3", "furigana": "じかん あ い", "sentence_source": "generated"}, {"text": "部屋に有る物を全部数えた。", "target_word": "有る", "complexity_tier": "T3", "furigana": "へや あ もの ぜんぶ かぞ", "sentence_source": "generated"}, {"text": "冷蔵庫に牛乳が有って安心した。", "target_word": "有って", "complexity_tier": "T3", "furigana": "れいぞうこ ぎゅうにゅう あ あんしん", "sentence_source": "generated"}, {"text": "家の裏に小さな畑が有る。", "target_word": "有る", "complexity_tier": "T3", "furigana": "いえ うら ちい はたけ あ", "sentence_source": "generated"}, {"text": "お金が有る人は少ない。", "target_word": "有る", "complexity_tier": "T3", "furigana": "かね あ ひと すく", "sentence_source": "generated"}], "morphological_forms": [{"form": "有った", "label": "活用"}, {"form": "有って", "label": "活用"}, {"form": "有れば", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 物がある場所に存在すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-se