INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35222, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "機械を使わず、手で字を書くこと。", "primary_collocate": null, "pronunciation": "てがき", "ipa": "tegaki", "syllable_count": 3, "sentences": [{"text": "母に手書きの手紙を送った。", "target_word": "手書き", "complexity_tier": "T3", "furigana": "はは てが てがみ おく", "sentence_source": "generated"}, {"text": "この地図は手書きだ。", "target_word": "手書き", "complexity_tier": "T3", "furigana": "ちず てが", "sentence_source": "generated"}, {"text": "手書きで名前を書いてください。", "target_word": "手書き", "complexity_tier": "T3", "furigana": "てが なまえ か", "sentence_source": "generated"}, {"text": "手書きの字はあたたかい。", "target_word": "手書き", "complexity_tier": "T3", "furigana": "てが じ", "sentence_source": "generated"}, {"text": "最近は手書きが少なくなった。", "target_word": "手書き", "complexity_tier": "T3", "furigana": "さいきん てが すく", "sentence_source": "generated"}, {"text": "先生は手書きでメモを作った。", "target_word": "手書き", "complexity_tier": "T3", "furigana": "せんせい てが つく", "sentence_source": "generated"}, {"text": "手書きのカードをもらってうれしい。", "target_word": "手書き", "complexity_tier": "T3", "furigana": "てが", "sentence_source": "generated"}, {"text": "年賀状を手書きしている。", "target_word": "手書き", "complexity_tier": "T3", "furigana": "ねんがじょう てが", "sentence_source": "generated"}, {"text": "手書きは時間がかかる。", "target_word": "手書き", "complexity_tier": "T3", "furigana": "てが じかん", "sentence_source": "generated"}, {"text": "彼の手書きの字は読みにくい。", "target_word": "手書き", "complexity_tier": "T3", "furigana": "かれ てが じ よ", "sentence_source": "generated"}], "morphological_forms": [{"form": "手書きする", "label": "派生"}, {"form": "手書き文字", "label": "派生"}, {"form": "手書き風", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 手で字を書くこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1'