INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35223, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ペンなどを使い、機械でなく人の手で文字を書くこと。", "primary_collocate": null, "pronunciation": "てがき", "ipa": "tegaki", "syllable_count": 3, "sentences": [{"text": "レポートは手書きで出した。", "target_word": "手書き", "complexity_tier": "T3", "furigana": "てが だ", "sentence_source": "generated"}, {"text": "祖母の手書きのレシピがある。", "target_word": "手書き", "complexity_tier": "T3", "furigana": "そぼ てが", "sentence_source": "generated"}, {"text": "手書きの看板が店の前にある。", "target_word": "手書き", "complexity_tier": "T3", "furigana": "てが かんばん みせ まえ", "sentence_source": "generated"}, {"text": "パソコンより手書きが好きだ。", "target_word": "手書き", "complexity_tier": "T3", "furigana": "てが す", "sentence_source": "generated"}, {"text": "手書きでノートを取っている。", "target_word": "手書き", "complexity_tier": "T3", "furigana": "てが と", "sentence_source": "generated"}, {"text": "この本は全部手書きだった。", "target_word": "手書き", "complexity_tier": "T3", "furigana": "ほん ぜんぶ てが", "sentence_source": "generated"}, {"text": "手書きの文字は人によって違う。", "target_word": "手書き", "complexity_tier": "T3", "furigana": "てが もじ ひと ちが", "sentence_source": "generated"}, {"text": "友達に手書きのメッセージを書いた。", "target_word": "手書き", "complexity_tier": "T3", "furigana": "ともだち てが か", "sentence_source": "generated"}, {"text": "手書きは心が伝わる。", "target_word": "手書き", "complexity_tier": "T3", "furigana": "てが こころ つた", "sentence_source": "generated"}, {"text": "招待状を手書きで作った。", "target_word": "手書き", "complexity_tier": "T3", "furigana": "しょうたいじょう てが つく", "sentence_source": "generated"}], "morphological_forms": [{"form": "手書きする", "label": "派生"}, {"form": "手書き文字", "label": "派生"}, {"form": "手書き風", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 機械でなく手で文字を書くこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'c