INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35228, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "工場や畑などで物をたくさん作ること。", "primary_collocate": null, "pronunciation": "せいさん", "ipa": "seːsaɴ", "syllable_count": 4, "sentences": [{"text": "この工場は車を生産する。", "target_word": "生産", "complexity_tier": "T3", "furigana": "こうじょう くるま せいさん", "sentence_source": "generated"}, {"text": "米の生産が去年より増えた。", "target_word": "生産", "complexity_tier": "T3", "furigana": "こめ せいさん きょねん ふ", "sentence_source": "generated"}, {"text": "新しい機械で生産を始めた。", "target_word": "生産", "complexity_tier": "T3", "furigana": "あたら きかい せいさん はじ", "sentence_source": "generated"}, {"text": "この村は野菜の生産で有名だ。", "target_word": "生産", "complexity_tier": "T3", "furigana": "むら やさい せいさん ゆうめい", "sentence_source": "generated"}, {"text": "生産が止まって困っている。", "target_word": "生産", "complexity_tier": "T3", "furigana": "せいさん と こま", "sentence_source": "generated"}, {"text": "日本で生産された時計を買った。", "target_word": "生産", "complexity_tier": "T3", "furigana": "にほん せいさん とけい か", "sentence_source": "generated"}, {"text": "工場の生産は毎日続く。", "target_word": "生産", "complexity_tier": "T3", "furigana": "こうじょう せいさん まいにち つづ", "sentence_source": "generated"}, {"text": "お茶を生産している町だ。", "target_word": "生産", "complexity_tier": "T3", "furigana": "ちゃ せいさん まち", "sentence_source": "generated"}, {"text": "生産の量を少し減らした。", "target_word": "生産", "complexity_tier": "T3", "furigana": "せいさん りょう すこ へ", "sentence_source": "generated"}, {"text": "牛乳の生産には時間がかかる。", "target_word": "生産", "complexity_tier": "T3", "furigana": "ぎゅうにゅう せいさん じかん", "sentence_source": "generated"}], "morphological_forms": [{"form": "生産する", "label": "派生"}, {"form": "生産者", "label": "派生"}, {"form": "生産量", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物を作り出すこと・作る量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b808c550-4054-4fa6-ba75-cfa22e934864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35230, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "急に大きく進歩したり、よくなったりすること。", "primary_collocate": null, "pronunciation": "ひやく", "ipa": "çijakɯ", "syllable_count": 3, "sentences": [{"text": "彼は今年大きく飛躍した。", "target_word": "飛躍", "complexity_tier": "T3", "furigana": "かれ ことし おお ひやく", "sentence_source": "generated"}, {"text": "このチームの飛躍に驚いた。", "target_word": "飛躍", "complexity_tier": "T3", "furigana": "ひやく おどろ", "sentence_source": "generated"}, {"text": "新しい技術で会社が飛躍する。", "target_word": "飛躍", "complexity_tier": "T3", "furigana": "あたら ぎじゅつ かいしゃ ひやく", "sentence_source": "generated"}, {"text": "飛躍のチャンスが来た。", "target_word": "飛躍", "complexity_tier": "T3", "furigana": "ひやく き", "sentence_source": "generated"}, {"text": "練習を続けて飛躍を目指す。", "target_word": "飛躍", "complexity_tier": "T3", "furigana": "れんしゅう つづ ひやく めざ", "sentence_source": "generated"}, {"text": "彼女の飛躍は努力の結果だ。", "target_word": "飛躍", "complexity_tier": "T3", "furigana": "かのじょ ひやく どりょく けっか", "sentence_source": "generated"}, {"text": "来年こそ飛躍したいと思う。", "target_word": "飛躍", "complexity_tier": "T3", "furigana": "らいねん ひやく おも", "sentence_source": "generated"}, {"text": "町が観光で飛躍している。", "target_word": "飛躍", "complexity_tier": "T3", "furigana": "まち かんこう ひやく", "sentence_source": "generated"}, {"text": "飛躍の年にしたい。", "target_word": "飛躍", "complexity_tier": "T3", "furigana": "ひやく とし", "sentence_source": "generated"}, {"text": "その選手は海外で飛躍した。", "target_word": "飛躍", "complexity_tier": "T3", "furigana": "せんしゅ かいがい ひやく", "sentence_source": "generated"}], "morphological_forms": [{"form": "飛躍する", "label": "派生"}, {"form": "飛躍的", "label": "派生"}, {"form": "大飛躍", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 急に大きく進歩すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b808c550-4054-4fa6-ba75-cfa22e934864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35214, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有る", "is_correct": true, "explanation": "正解：「ある」と読む対象語。"}, {"text": "会う", "is_correct": false, "explanation": "あう：「る」が「う」に変わった一モーラ差。意味は人と顔を合わせること。"}, {"text": "開く", "is_correct": false, "explanation": "あく：「る」が「く」に変わった一モーラ差。意味は閉じていたものがひらくこと。"}, {"text": "売る", "is_correct": false, "explanation": "うる：「あ」が「う」に変わった一モーラ差。意味はお金と引き換えに物を渡すこと。"}, {"text": "編む", "is_correct": false, "explanation": "あむ：「る」が「む」に変わった一モーラ差。意味は糸などを組んで作ること。"}], "explanations": {"有る": "正解：「ある」と読む対象語。", "会う": "あう：「る」が「う」に変わった一モーラ差。意味は人と顔を合わせること。", "開く": "あく：「る」が「く」に変わった一モーラ差。意味は閉じていたものがひらくこと。", "売る": "うる：「あ」が「う」に変わった一モーラ差。意味はお金と引き換えに物を渡すこと。", "編む": "あむ：「る」が「む」に変わった一モーラ差。意味は糸などを組んで作ること。"}, "sentence_index": null, "correct_answer": "有る"}, "level_3": {"options": [{"text": "有る", "is_correct": true, "explanation": "物の存在を表すので「本が有る」が正しい。"}, {"text": "居る", "is_correct": false, "explanation": "項構造：「居る」は人や動物に使い、本には使わない。"}, {"text": "走る", "is_correct": false, "explanation": "意味：本は走らない。"}, {"text": "泣く", "is_correct": false, "explanation": "意味：本は泣かない。"}], "explanations": {"有る": "物の存在を表すので「本が有る」が正しい。", "居る": "項構造：「居る」は人や動物に使い、本には使わない。", "走る": "意味：本は走らない。", "泣く": "意味：本は泣かない。"}, "sentence_index": 0, "correct_answer": "有る"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "本が三匹有ります。", "explanation": "助数詞の誤り：本は「冊」で数える。"}, {"text": "駅の近くを店が有ります。", "explanation": "助詞の混同：存在の場所は「に」で表す。"}, {"text": "駅の近くに店が居ます。", "explanation": "語の選択の誤り：店のような物の存在には「居る」ではなく「有る」を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2cae3af-c784-4dab-8c11-24726ad7b345') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35214, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "机の上で本が有る。", "corrected_sentence": "机の上に本が有る。", "error_description": "助詞の混同：物の存在する場所は「で」ではなく「に」で表す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "有る", "is_correct": true, "explanation": "文末の言い切りなので辞書形「有る」が入る。"}, {"text": "有って", "is_correct": false, "explanation": "て形は文末で言い切れない。"}, {"text": "有れば", "is_correct": false, "explanation": "条件形は後に続く文が必要。"}, {"text": "有ったら", "is_correct": false, "explanation": "条件形は後に続く文が必要。"}], "correct_form": "有る", "base_form": "有る", "form_label": "活用", "sentence_index": 1, "explanations": {"有る": "文末の言い切りなので辞書形「有る」が入る。", "有って": "て形は文末で言い切れない。", "有れば": "条件形は後に続く文が必要。", "有ったら": "条件形は後に続く文が必要。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2cae3af-c784-4dab-8c11-24726ad7b345') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35214, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "存在の場所を表す「に」に「は」がついて「には」になる。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を表し、「は」と結びつかず存在の場所にもならない。"}, {"text": "が", "is_correct": false, "explanation": "「がは」という形はない。"}, {"text": "へ", "is_correct": false, "explanation": "「へは」は方向を表し、存在の場所には使えない。"}], "correct_answer": "に", "explanations": {"に": "存在の場所を表す「に」に「は」がついて「には」になる。", "を": "「を」は目的語を表し、「は」と結びつかず存在の場所にもならない。", "が": "「がは」という形はない。", "へ": "「へは」は方向を表し、存在の場所には使えない。"}, "error_tags": {"を": "object_marking", "が": "topic_vs_subject", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無い", "is_correct": true, "explanation": "物が存在しないことで「有る」の反対。"}, {"text": "居る", "is_correct": false, "explanation": "人や動物の存在を表し、反対の意味ではない。"}, {"text": "置く", "is_correct": false, "explanation": "物をある場所に置く動作で、対義ではない。"}, {"text": "残る", "is_correct": false, "explanation": "なくならずにあることで、対義ではない。"}], "correct_answer": "無い", "explanations": {"無い": "物が存在しないことで「有る」の反対。", "居る": "人や動物の存在を表し、反対の意味ではない。", "置く": "物をある場所に置く動作で、対義ではない。", "残る": "なくならずにあることで、対義ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2cae3af-c784-4dab-8c11-24726ad7b345') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35214, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "有る", "is_correct": true, "explanation": "正解：「ある」と読む対象語。"}, {"text": "朝", "is_correct": false, "explanation": "あさ：「る」が「さ」に変わった一モーラ差。意味は一日の始まりの時間。"}, {"text": "網", "is_correct": false, "explanation": "あみ：「る」が「み」に変わった一モーラ差。意味は魚などをとる道具。"}, {"text": "蟻", "is_correct": false, "explanation": "あり：「る」が「り」に変わった一モーラ差。意味は小さな虫。"}, {"text": "雨", "is_correct": false, "explanation": "あめ：「る」が「め」に変わった一モーラ差。意味は空から降る水。"}], "explanations": {"有る": "正解：「ある」と読む対象語。", "朝": "あさ：「る」が「さ」に変わった一モーラ差。意味は一日の始まりの時間。", "網": "あみ：「る」が「み」に変わった一モーラ差。意味は魚などをとる道具。", "蟻": "あり：「る」が「り」に変わった一モーラ差。意味は小さな虫。", "雨": "あめ：「る」が「め」に変わった一モーラ差。意味は空から降る水。"}, "sentence_index": null, "correct_answer": "有る"}, "level_3": {"options": [{"text": "有る", "is_correct": true, "explanation": "部屋の中に存在する物を表す。"}, {"text": "泳ぐ", "is_correct": false, "explanation": "意味：物は部屋で泳がない。"}, {"text": "笑う", "is_correct": false, "explanation": "意味：物は笑わない。"}, {"text": "走る", "is_correct": false, "explanation": "意味：物は走らない。"}], "explanations": {"有る": "部屋の中に存在する物を表す。", "泳ぐ": "意味：物は部屋で泳がない。", "笑う": "意味：物は笑わない。", "走る": "意味：物は走らない。"}, "sentence_index": 6, "correct_answer": "有る"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お金が有る人を少ない。", "explanation": "助詞の混同：「少ない」の主語は「は」か「が」で示す。"}, {"text": "お金が一本有る人は少ない。", "explanation": "助数詞の誤り：お金を「本」では数えない。"}, {"text": "お金が居る人は少ない。", "explanation": "語の選択の誤り：お金のような物の存在には「居る」ではなく「有る」を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2cae3af-c784-4dab-8c11-24726ad7b345') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35214, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "お金が有っている人は少ない。", "corrected_sentence": "お金が有る人は少ない。", "error_description": "活用の誤り：状態を表す「有る」は「ている」にしない。正しくは「有る」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "有って", "is_correct": true, "explanation": "後に「安心した」が続くので理由を表すて形が入る。"}, {"text": "有る", "is_correct": false, "explanation": "辞書形のままでは後の動詞とつながらない。"}, {"text": "有れば", "is_correct": false, "explanation": "条件形は過去の「安心した」と合わない。"}, {"text": "有った", "is_correct": false, "explanation": "た形のままでは後の動詞とつながらない。"}], "correct_form": "有って", "base_form": "有る", "form_label": "活用", "sentence_index": 7, "explanations": {"有って": "後に「安心した」が続くので理由を表すて形が入る。", "有る": "辞書形のままでは後の動詞とつながらない。", "有れば": "条件形は過去の「安心した」と合わない。", "有った": "た形のままでは後の動詞とつながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2cae3af-c784-4dab-8c11-24726ad7b345') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35214, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "存在する物「牛乳」を主語として示す。"}, {"text": "を", "is_correct": false, "explanation": "「有る」は自動詞なので目的語の「を」はとれない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、存在する物を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表し、この文では非文になる。"}], "correct_answer": "が", "explanations": {"が": "存在する物「牛乳」を主語として示す。", "を": "「有る」は自動詞なので目的語の「を」はとれない。", "へ": "「へ」は方向を表し、存在する物を示せない。", "から": "「から」は起点を表し、この文では非文になる。"}, "error_tags": {"を": "object_marking", "へ": "direction", "から": "source_vs_goal"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無い", "is_correct": true, "explanation": "存在しないことで「有る」の反対。"}, {"text": "持つ", "is_correct": false, "explanation": "手に持つ・所有する動作で、対義ではない。"}, {"text": "見える", "is_correct": false, "explanation": "目に入ることで、対義ではない。"}, {"text": "続く", "is_correct": false, "explanation": "途切れずに進むことで、対義ではない。"}], "correct_answer": "無い", "explanations": {"無い": "存在しないことで「有る」の反対。", "持つ": "手に持つ・所有する動作で、対義ではない。", "見える": "目に入ることで、対義ではない。", "続く": "途切れずに進むことで、対義ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2cae3af-c784-4dab-8c11-24726ad7b345') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35220, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "職人", "is_correct": true, "explanation": "正解：「しょくにん」と読む対象語。"}, {"text": "職員", "is_correct": false, "explanation": "しょくいん：「に」が「い」に変わった一モーラ差。意味は役所や会社で働く人。"}, {"text": "商人", "is_correct": false, "explanation": "しょうにん：「く」が「う」に変わった一モーラ差。意味は物を売る商売の人。"}, {"text": "食品", "is_correct": false, "explanation": "しょくひん：「に」が「ひ」に変わった一モーラ差。意味は食べ物。"}], "explanations": {"職人": "正解：「しょくにん」と読む対象語。", "職員": "しょくいん：「に」が「い」に変わった一モーラ差。意味は役所や会社で働く人。", "商人": "しょうにん：「く」が「う」に変わった一モーラ差。意味は物を売る商売の人。", "食品": "しょくひん：「に」が「ひ」に変わった一モーラ差。意味は食べ物。"}, "sentence_index": null, "correct_answer": "職人"}, "level_3": {"options": [{"text": "職人", "is_correct": true, "explanation": "家具を手で作る仕事の人なので「職人」。"}, {"text": "医者", "is_correct": false, "explanation": "意味：医者は家具を作る仕事ではない。"}, {"text": "選手", "is_correct": false, "explanation": "連語：「家具の選手」とは言わない。"}, {"text": "客", "is_correct": false, "explanation": "意味：客は家具を作る人ではない。"}], "explanations": {"職人": "家具を手で作る仕事の人なので「職人」。", "医者": "意味：医者は家具を作る仕事ではない。", "選手": "連語：「家具の選手」とは言わない。", "客": "意味：客は家具を作る人ではない。"}, "sentence_index": 0, "correct_answer": "職人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は将来、職人をなりたい。", "explanation": "助詞の混同：「なる」は「に」をとる。"}, {"text": "私は職人に将来、なっていた。", "explanation": "アスペクトの誤り：将来の希望に「ていた」は合わない。"}, {"text": "私は将来、一枚の職人になりたい。", "explanation": "助数詞の誤り：人は「枚」で数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2cae3af-c784-4dab-8c11-24726ad7b345') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
