INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35220, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「手で」は手段を表す。"}, {"text": "に", "is_correct": false, "explanation": "「手に作る」とは言えず、手段を表さない。"}, {"text": "が", "is_correct": false, "explanation": "主語の「職人が」があり、「手が作る」は非文。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、手段にならない。"}], "correct_answer": "で", "explanations": {"で": "「手で」は手段を表す。", "に": "「手に作る」とは言えず、手段を表さない。", "が": "主語の「職人が」があり、「手が作る」は非文。", "へ": "「へ」は方向を表し、手段にならない。"}, "error_tags": {"に": "location_vs_target", "が": "topic_vs_subject", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2cae3af-c784-4dab-8c11-24726ad7b345') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35220, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "職人", "is_correct": true, "explanation": "正解：「しょくにん」と読む対象語。"}, {"text": "承認", "is_correct": false, "explanation": "しょうにん：「く」が「う」に変わった一モーラ差。意味はよいと認めること。"}, {"text": "証人", "is_correct": false, "explanation": "しょうにん：「く」が「う」に変わった一モーラ差。意味は事実を証明する人。"}, {"text": "植林", "is_correct": false, "explanation": "しょくりん：「に」が「り」に変わった一モーラ差。意味は木を植えること。"}], "explanations": {"職人": "正解：「しょくにん」と読む対象語。", "承認": "しょうにん：「く」が「う」に変わった一モーラ差。意味はよいと認めること。", "証人": "しょうにん：「く」が「う」に変わった一モーラ差。意味は事実を証明する人。", "植林": "しょくりん：「に」が「り」に変わった一モーラ差。意味は木を植えること。"}, "sentence_index": null, "correct_answer": "職人"}, "level_3": {"options": [{"text": "職人", "is_correct": true, "explanation": "靴を直す技術を持つ人なので「職人」。"}, {"text": "赤ちゃん", "is_correct": false, "explanation": "意味：赤ちゃんは靴を直せない。"}, {"text": "生徒", "is_correct": false, "explanation": "意味：靴を直す仕事の人ではない。"}, {"text": "猫", "is_correct": false, "explanation": "意味：猫に靴を直してもらうことはできない。"}], "explanations": {"職人": "靴を直す技術を持つ人なので「職人」。", "赤ちゃん": "意味：赤ちゃんは靴を直せない。", "生徒": "意味：靴を直す仕事の人ではない。", "猫": "意味：猫に靴を直してもらうことはできない。"}, "sentence_index": 6, "correct_answer": "職人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "若い職人が育てている。", "explanation": "助詞の混同：育てられる相手は「を」で示す。"}, {"text": "若い職人を三本育てている。", "explanation": "助数詞の誤り：人は「本」で数えない。"}, {"text": "職人を若い育てている。", "explanation": "語順の誤り：「若い」は「職人」の前に置く。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2cae3af-c784-4dab-8c11-24726ad7b345') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
