INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35222, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "手書き", "is_correct": true, "explanation": "正解：「てがき」と読む対象語。"}, {"text": "手紙", "is_correct": false, "explanation": "てがみ：「き」が「み」に変わった一モーラ差。意味は人に送る文。"}, {"text": "手柄", "is_correct": false, "explanation": "てがら：「き」が「ら」に変わった一モーラ差。意味はほめられるよい働き。"}, {"text": "手つき", "is_correct": false, "explanation": "てつき：「が」が「つ」に変わった一モーラ差。意味は手の動かし方。"}], "explanations": {"手書き": "正解：「てがき」と読む対象語。", "手紙": "てがみ：「き」が「み」に変わった一モーラ差。意味は人に送る文。", "手柄": "てがら：「き」が「ら」に変わった一モーラ差。意味はほめられるよい働き。", "手つき": "てつき：「が」が「つ」に変わった一モーラ差。意味は手の動かし方。"}, "sentence_index": null, "correct_answer": "手書き"}, "level_3": {"options": [{"text": "手書き", "is_correct": true, "explanation": "手で書いた手紙を表す。"}, {"text": "手術", "is_correct": false, "explanation": "意味：手術は手紙の種類ではない。"}, {"text": "手袋", "is_correct": false, "explanation": "意味：手袋は手紙の種類ではない。"}, {"text": "手首", "is_correct": false, "explanation": "意味：体の部分で、手紙を修飾しない。"}], "explanations": {"手書き": "手で書いた手紙を表す。", "手術": "意味：手術は手紙の種類ではない。", "手袋": "意味：手袋は手紙の種類ではない。", "手首": "意味：体の部分で、手紙を修飾しない。"}, "sentence_index": 0, "correct_answer": "手書き"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "手書きの字を三匹書いた。", "explanation": "助数詞の誤り：字は「匹」で数えない。"}, {"text": "手書きの字があたたかいでした。", "explanation": "活用の誤り：「あたたかかったです」が正しい。"}, {"text": "手書きな字はあたたかい。", "explanation": "連体の誤り：名詞「手書き」が名詞を修飾するときは「な」ではなく「の」を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2cae3af-c784-4dab-8c11-24726ad7b345') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
