INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35222, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「送る」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「手紙が送った」は主語になり非文。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、送る物を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表し、ここでは非文。"}], "correct_answer": "を", "explanations": {"を": "他動詞「送る」の目的語を示す。", "が": "「手紙が送った」は主語になり非文。", "へ": "「へ」は方向を表し、送る物を示せない。", "から": "「から」は起点を表し、ここでは非文。"}, "error_tags": {"が": "topic_vs_subject", "へ": "direction", "から": "source_vs_goal"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "印刷", "is_correct": true, "explanation": "機械で文字を刷ることで、手で書く「手書き」の反対。"}, {"text": "下書き", "is_correct": false, "explanation": "清書の前に書くもので、対義ではない。"}, {"text": "清書", "is_correct": false, "explanation": "きれいに書き直すことで、対義ではない。"}, {"text": "手作り", "is_correct": false, "explanation": "手で作ることで、反対ではない。"}], "correct_answer": "印刷", "explanations": {"印刷": "機械で文字を刷ることで、手で書く「手書き」の反対。", "下書き": "清書の前に書くもので、対義ではない。", "清書": "きれいに書き直すことで、対義ではない。", "手作り": "手で作ることで、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2cae3af-c784-4dab-8c11-24726ad7b345') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
