INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35228, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "生産", "is_correct": true, "explanation": "正解：「せいさん」と読む対象語。"}, {"text": "生還", "is_correct": false, "explanation": "せいかん：「さ」が「か」に変わった一モーラ差。意味は生きて帰ること。"}, {"text": "生誕", "is_correct": false, "explanation": "せいたん：「さ」が「た」に変わった一モーラ差。意味は生まれること。"}, {"text": "制作", "is_correct": false, "explanation": "せいさく：「ん」が「く」に変わった一モーラ差。意味は作品を作ること。"}, {"text": "制裁", "is_correct": false, "explanation": "せいさい：「ん」が「い」に変わった一モーラ差。意味は罰を与えること。"}], "explanations": {"生産": "正解：「せいさん」と読む対象語。", "生還": "せいかん：「さ」が「か」に変わった一モーラ差。意味は生きて帰ること。", "生誕": "せいたん：「さ」が「た」に変わった一モーラ差。意味は生まれること。", "制作": "せいさく：「ん」が「く」に変わった一モーラ差。意味は作品を作ること。", "制裁": "せいさい：「ん」が「い」に変わった一モーラ差。意味は罰を与えること。"}, "sentence_index": null, "correct_answer": "生産"}, "level_3": {"options": [{"text": "生産", "is_correct": true, "explanation": "工場が車を作り出すことなので「生産する」。"}, {"text": "運転", "is_correct": false, "explanation": "項構造：工場は車を運転しない。"}, {"text": "洗濯", "is_correct": false, "explanation": "意味：車を洗濯するとは言わない。"}, {"text": "料理", "is_correct": false, "explanation": "意味：車は料理しない。"}], "explanations": {"生産": "工場が車を作り出すことなので「生産する」。", "運転": "項構造：工場は車を運転しない。", "洗濯": "意味：車を洗濯するとは言わない。", "料理": "意味：車は料理しない。"}, "sentence_index": 0, "correct_answer": "生産"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この村は野菜を生産で有名だ。", "explanation": "助詞の混同：「野菜の生産」と名詞をつなぐ。"}, {"text": "この村は野菜の生産に有名だ。", "explanation": "助詞の混同：有名である理由は「に」ではなく「で」で示す。"}, {"text": "この村は野菜を一匹生産する。", "explanation": "助数詞の誤り：野菜を「匹」で数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2cae3af-c784-4dab-8c11-24726ad7b345') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validat