INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35228, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "自動詞「増えた」の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「増える」は自動詞で目的語をとらない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は着点を表し、主語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、ここでは非文。"}], "correct_answer": "が", "explanations": {"が": "自動詞「増えた」の主語を示す。", "を": "「増える」は自動詞で目的語をとらない。", "に": "「に」は着点を表し、主語にならない。", "へ": "「へ」は方向を表し、ここでは非文。"}, "error_tags": {"を": "object_marking", "に": "location_vs_target", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "消費", "is_correct": true, "explanation": "作った物を使ってなくすことで、「生産」の反対。"}, {"text": "製造", "is_correct": false, "explanation": "物を作ることで、反対ではない。"}, {"text": "輸出", "is_correct": false, "explanation": "外国に売ることで、対義ではない。"}, {"text": "販売", "is_correct": false, "explanation": "売ることで、対義ではない。"}], "correct_answer": "消費", "explanations": {"消費": "作った物を使ってなくすことで、「生産」の反対。", "製造": "物を作ることで、反対ではない。", "輸出": "外国に売ることで、対義ではない。", "販売": "売ることで、対義ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2cae3af-c784-4dab-8c11-24726ad7b345') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
