INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35234, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "お金のこと。ものと交換するときに使うもの。", "primary_collocate": null, "pronunciation": "かね", "ipa": "kane", "syllable_count": 2, "sentences": [{"text": "旅行には多くの金がかかる。", "target_word": "金", "complexity_tier": "T3", "furigana": "りょこう おお かね", "sentence_source": "generated"}, {"text": "彼は金に困っている。", "target_word": "金", "complexity_tier": "T3", "furigana": "かれ かね こま", "sentence_source": "generated"}, {"text": "金で買えない物もある。", "target_word": "金", "complexity_tier": "T3", "furigana": "かね か もの", "sentence_source": "generated"}, {"text": "金の使い方を考えよう。", "target_word": "金", "complexity_tier": "T3", "furigana": "かね つか かた かんが", "sentence_source": "generated"}, {"text": "兄は金をためている。", "target_word": "金", "complexity_tier": "T3", "furigana": "あに かね", "sentence_source": "generated"}, {"text": "金は大切に使いなさい。", "target_word": "金", "complexity_tier": "T3", "furigana": "かね たいせつ つか", "sentence_source": "generated"}, {"text": "その町は金が足りない。", "target_word": "金", "complexity_tier": "T3", "furigana": "まち かね た", "sentence_source": "generated"}, {"text": "金より友達が大事だ。", "target_word": "金", "complexity_tier": "T3", "furigana": "かね ともだち だいじ", "sentence_source": "generated"}, {"text": "金を貸してほしいと言われた。", "target_word": "金", "complexity_tier": "T3", "furigana": "かね か い", "sentence_source": "generated"}, {"text": "祖父は金の話をしない。", "target_word": "金", "complexity_tier": "T3", "furigana": "そふ かね はなし", "sentence_source": "generated"}], "morphological_forms": [{"form": "金額", "label": "派生"}, {"form": "資金", "label": "派生"}, {"form": "現金", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | ものと交換するために使うお金", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83af9f7