INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35240, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かの上に物をのせて、おおうことです。", "primary_collocate": null, "pronunciation": "かける", "ipa": "kakeɾɯ", "syllable_count": 3, "sentences": [{"text": "寝ている子に毛布を掛ける。", "target_word": "掛ける", "complexity_tier": "T3", "furigana": "ね こ もうふ か", "sentence_source": "generated"}, {"text": "机に布を掛けた。", "target_word": "掛け", "complexity_tier": "T3", "furigana": "つくえ ぬの か", "sentence_source": "generated"}, {"text": "母はソファにカバーを掛けている。", "target_word": "掛け", "complexity_tier": "T3", "furigana": "はは か", "sentence_source": "generated"}, {"text": "寒いので足に毛布を掛けた。", "target_word": "掛け", "complexity_tier": "T3", "furigana": "さむ あし もうふ か", "sentence_source": "generated"}, {"text": "鳥かごに布を掛けて暗くする。", "target_word": "掛け", "complexity_tier": "T3", "furigana": "とり ぬの か くら", "sentence_source": "generated"}, {"text": "ピアノに布を掛けておこう。", "target_word": "掛け", "complexity_tier": "T3", "furigana": "ぬの か", "sentence_source": "generated"}, {"text": "車にシートを掛けられる？", "target_word": "掛け", "complexity_tier": "T3", "furigana": "くるま か", "sentence_source": "generated"}, {"text": "料理に布巾を掛けて置いた。", "target_word": "掛け", "complexity_tier": "T3", "furigana": "りょうり ふきん か お", "sentence_source": "generated"}, {"text": "毛布を掛けない夜は寒い。", "target_word": "掛け", "complexity_tier": "T3", "furigana": "もうふ か よる さむ", "sentence_source": "generated"}, {"text": "父の肩に上着を掛けた。", "target_word": "掛け", "complexity_tier": "T3", "furigana": "ちち かた うわぎ か", "sentence_source": "generated"}], "morphological_forms": [{"form": "掛けた", "label": "活用"}, {"form": "掛けて", "label": "活用"}, {"form": "掛けない", "label": "活用"}, {"form": "掛け布団", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 物の上に布などをのせておおう", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jso