INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35246, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "あるものの形を、べつのところにうつすこと。", "primary_collocate": null, "pronunciation": "てんしゃ", "ipa": "teɴɕa", "syllable_count": 3, "sentences": [{"text": "絵の転写に失敗した。", "target_word": "転写", "complexity_tier": "T3", "furigana": "え てんしゃ しっぱい", "sentence_source": "generated"}, {"text": "模様を布に転写する。", "target_word": "転写", "complexity_tier": "T3", "furigana": "もよう ぬの てんしゃ", "sentence_source": "generated"}, {"text": "転写には特別な紙を使う。", "target_word": "転写", "complexity_tier": "T3", "furigana": "てんしゃ とくべつ かみ つか", "sentence_source": "generated"}, {"text": "地図を紙に転写している。", "target_word": "転写", "complexity_tier": "T3", "furigana": "ちず かみ てんしゃ", "sentence_source": "generated"}, {"text": "転写した絵がきれいだ。", "target_word": "転写", "complexity_tier": "T3", "furigana": "てんしゃ え", "sentence_source": "generated"}, {"text": "この機械で転写ができる。", "target_word": "転写", "complexity_tier": "T3", "furigana": "きかい てんしゃ", "sentence_source": "generated"}, {"text": "転写の作業は時間がかかる。", "target_word": "転写", "complexity_tier": "T3", "furigana": "てんしゃ さぎょう じかん", "sentence_source": "generated"}, {"text": "シャツに写真を転写した。", "target_word": "転写", "complexity_tier": "T3", "furigana": "しゃしん てんしゃ", "sentence_source": "generated"}, {"text": "文字の転写がずれてしまった。", "target_word": "転写", "complexity_tier": "T3", "furigana": "もじ てんしゃ", "sentence_source": "generated"}, {"text": "石の形を転写して調べる。", "target_word": "転写", "complexity_tier": "T3", "furigana": "いし かたち てんしゃ しら", "sentence_source": "generated"}], "morphological_forms": [{"form": "転写する", "label": "派生"}, {"form": "転写した", "label": "活用"}, {"form": "転写紙", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 形や絵を別の所に写しとること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:f