INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35234, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "金", "is_correct": true, "explanation": "正解。「かね」と読む。"}, {"text": "亀", "is_correct": false, "explanation": "「かめ」と読む。二つ目のモーラ「ね」が「め」に変わる一モーラ差。"}, {"text": "風", "is_correct": false, "explanation": "「かぜ」と読む。二つ目のモーラ「ね」が「ぜ」に変わる一モーラ差。"}, {"text": "羽", "is_correct": false, "explanation": "「はね」と読む。最初のモーラ「か」が「は」に変わる一モーラ差。"}, {"text": "種", "is_correct": false, "explanation": "「たね」と読む。最初のモーラ「か」が「た」に変わる一モーラ差。"}], "explanations": {"金": "正解。「かね」と読む。", "亀": "「かめ」と読む。二つ目のモーラ「ね」が「め」に変わる一モーラ差。", "風": "「かぜ」と読む。二つ目のモーラ「ね」が「ぜ」に変わる一モーラ差。", "羽": "「はね」と読む。最初のモーラ「か」が「は」に変わる一モーラ差。", "種": "「たね」と読む。最初のモーラ「か」が「た」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "金"}, "level_3": {"options": [{"text": "金", "is_correct": true, "explanation": "この文脈に自然に合う。"}, {"text": "雲", "is_correct": false, "explanation": "意味：旅行に雲がかかるとは言えない。"}, {"text": "声", "is_correct": false, "explanation": "連語：「声がかかる」は誘われる意味で、「多くの」と合わない。"}, {"text": "歌", "is_correct": false, "explanation": "意味：旅行に歌がかかるは意味をなさない。"}], "explanations": {"金": "この文脈に自然に合う。", "雲": "意味：旅行に雲がかかるとは言えない。", "声": "連語：「声がかかる」は誘われる意味で、「多くの」と合わない。", "歌": "意味：旅行に歌がかかるは意味をなさない。"}, "sentence_index": 0, "correct_answer": "金"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "金を一匹もらった。", "explanation": "助数詞の誤り：お金を「匹」で数えることはない。"}, {"text": "金が使い方を考えよう。", "explanation": "助詞の混同：「金の使い方」とすべきところに「が」を使っている。"}, {"text": "明日金を払った。", "explanation": "活用の誤り：「明日」と過去の「た」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7d8f505-44d1-4c26-a7b9-636ede622ea1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35234, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "旅行には多くの金をかかる。", "corrected_sentence": "旅行には多くの金がかかる。", "error_description": "「かかる」は自動詞なので、金には「を」ではなく「が」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7d8f505-44d1-4c26-a7b9-636ede622ea1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35234, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「金に困る」で、困っている原因・対象を表す。"}, {"text": "を", "is_correct": false, "explanation": "「困る」は目的語を取らないので「を」は使えない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」はこの文に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「金と困る」は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「金に困る」で、困っている原因・対象を表す。", "を": "「困る」は目的語を取らないので「を」は使えない。", "へ": "方向を表す「へ」はこの文に合わない。", "と": "「金と困る」は意味が通らない。"}, "error_tags": {"を": "object_marking", "へ": "direction", "と": "other"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7d8f505-44d1-4c26-a7b9-636ede622ea1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35234, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "金", "is_correct": true, "explanation": "正解。「かね」と読む。"}, {"text": "壁", "is_correct": false, "explanation": "「かべ」と読む。二つ目のモーラ「ね」が「べ」に変わる。"}, {"text": "蟹", "is_correct": false, "explanation": "「かに」と読む。二つ目のモーラ「ね」が「に」に変わる。"}, {"text": "骨", "is_correct": false, "explanation": "「ほね」と読む。一つ目のモーラ「か」が「ほ」に変わる。"}, {"text": "亀", "is_correct": false, "explanation": "「かめ」と読む。二つ目のモーラ「ね」が「め」に変わる。"}], "explanations": {"金": "正解。「かね」と読む。", "壁": "「かべ」と読む。二つ目のモーラ「ね」が「べ」に変わる。", "蟹": "「かに」と読む。二つ目のモーラ「ね」が「に」に変わる。", "骨": "「ほね」と読む。一つ目のモーラ「か」が「ほ」に変わる。", "亀": "「かめ」と読む。二つ目のモーラ「ね」が「め」に変わる。"}, "sentence_index": null, "correct_answer": "金"}, "level_3": {"options": [{"text": "金", "is_correct": true, "explanation": "町の財政に必要なお金が足りないという意味。"}, {"text": "海", "is_correct": false, "explanation": "意味：町に海が足りないとは普通言わない。"}, {"text": "昼", "is_correct": false, "explanation": "意味：昼が足りないは意味をなさない。"}, {"text": "駅前", "is_correct": false, "explanation": "意味：駅前が足りないは意味が通らない。"}], "explanations": {"金": "町の財政に必要なお金が足りないという意味。", "海": "意味：町に海が足りないとは普通言わない。", "昼": "意味：昼が足りないは意味をなさない。", "駅前": "意味：駅前が足りないは意味が通らない。"}, "sentence_index": 6, "correct_answer": "金"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父は金を三冊持っている。", "explanation": "助数詞の誤り：お金を「冊」で数えない。"}, {"text": "祖父に金の話がしない。", "explanation": "助詞の混同：「祖父は金の話をしない」とすべき。"}, {"text": "祖父は金の話をしている昨日。", "explanation": "語順の誤り：時の語「昨日」が文末に来ており不自然、しかもアスペクトも合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7d8f505-44d1-4c26-a7b9-636ede622ea1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.