INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35237, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「並んでいる」の主語を表す「が」。"}, {"text": "を", "is_correct": false, "explanation": "「並ぶ」は自動詞なので「を」は使えない。"}, {"text": "に", "is_correct": false, "explanation": "場所ではないので「に」は使えない。"}, {"text": "で", "is_correct": false, "explanation": "「細工で並んでいる」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「並んでいる」の主語を表す「が」。", "を": "「並ぶ」は自動詞なので「を」は使えない。", "に": "場所ではないので「に」は使えない。", "で": "「細工で並んでいる」は意味が通らない。"}, "error_tags": {"を": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7d8f505-44d1-4c26-a7b9-636ede622ea1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35238, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "圧力", "is_correct": true, "explanation": "正解。「あつりょく」と読む。"}, {"text": "実力", "is_correct": false, "explanation": "「じつりょく」と読む。最初のモーラ「あ」が「じ」に変わる一モーラ差。"}, {"text": "活力", "is_correct": false, "explanation": "「かつりょく」と読む。最初のモーラ「あ」が「か」に変わる一モーラ差。"}, {"text": "出力", "is_correct": false, "explanation": "「しゅつりょく」と読む。最初のモーラ「あ」が「しゅ」に変わる一モーラ差。"}], "explanations": {"圧力": "正解。「あつりょく」と読む。", "実力": "「じつりょく」と読む。最初のモーラ「あ」が「じ」に変わる一モーラ差。", "活力": "「かつりょく」と読む。最初のモーラ「あ」が「か」に変わる一モーラ差。", "出力": "「しゅつりょく」と読む。最初のモーラ「あ」が「しゅ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "圧力"}, "level_3": {"options": [{"text": "圧力", "is_correct": true, "explanation": "水が扉を押す力で開かない。"}, {"text": "音", "is_correct": false, "explanation": "意味：音で扉が開かないとは普通言わない。"}, {"text": "色", "is_correct": false, "explanation": "意味：水の色で扉が開かないは意味が通らない。"}, {"text": "味", "is_correct": false, "explanation": "意味：水の味は扉に影響しない。"}], "explanations": {"圧力": "水が扉を押す力で開かない。", "音": "意味：音で扉が開かないとは普通言わない。", "色": "意味：水の色で扉が開かないは意味が通らない。", "味": "意味：水の味は扉に影響しない。"}, "sentence_index": 0, "correct_answer": "圧力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "圧力が三冊上がると危ない。", "explanation": "助数詞の誤り：圧力を「冊」で数えない。"}, {"text": "圧力が上がったと明日危ない。", "explanation": "活用・語順の誤り：時の語の位置と時制が合わない。"}, {"text": "圧力に上がると危ない。", "explanation": "助詞の混同：主語は「が」で示す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7d8f505-44d1-4c26-a7b9-636ede622ea1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
