INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35238, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「調べる」の目的語を示す「を」。"}, {"text": "が", "is_correct": false, "explanation": "「圧力が調べた」は圧力が調べる主体になり不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は使えない。"}, {"text": "で", "is_correct": false, "explanation": "「圧力で調べた」は手段になり意味が変わる。"}], "correct_answer": "を", "explanations": {"を": "「調べる」の目的語を示す「を」。", "が": "「圧力が調べた」は圧力が調べる主体になり不自然。", "へ": "方向の「へ」は使えない。", "で": "「圧力で調べた」は手段になり意味が変わる。"}, "error_tags": {"が": "topic_vs_subject", "へ": "direction", "で": "instrument"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7d8f505-44d1-4c26-a7b9-636ede622ea1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35238, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "圧力", "is_correct": true, "explanation": "正解。「あつりょく」と読む。"}, {"text": "握力", "is_correct": false, "explanation": "「あくりょく」と読む。二つ目のモーラが「つ」から「く」に変わる。"}, {"text": "出力", "is_correct": false, "explanation": "「しゅつりょく」と読む。一つ目のモーラが「あ」から「しゅ」に変わる。"}, {"text": "脱力", "is_correct": false, "explanation": "「だつりょく」と読む。一つ目のモーラが「あ」から「だ」に変わる。"}], "explanations": {"圧力": "正解。「あつりょく」と読む。", "握力": "「あくりょく」と読む。二つ目のモーラが「つ」から「く」に変わる。", "出力": "「しゅつりょく」と読む。一つ目のモーラが「あ」から「しゅ」に変わる。", "脱力": "「だつりょく」と読む。一つ目のモーラが「あ」から「だ」に変わる。"}, "sentence_index": null, "correct_answer": "圧力"}, "level_3": {"options": [{"text": "圧力", "is_correct": true, "explanation": "空気が押す力を計器で測る。"}, {"text": "夢", "is_correct": false, "explanation": "意味：空気の夢を測るは意味をなさない。"}, {"text": "形", "is_correct": false, "explanation": "意味：空気の形は測れない。"}, {"text": "名前", "is_correct": false, "explanation": "意味：空気の名前を測るは意味をなさない。"}], "explanations": {"圧力": "空気が押す力を計器で測る。", "夢": "意味：空気の夢を測るは意味をなさない。", "形": "意味：空気の形は測れない。", "名前": "意味：空気の名前を測るは意味をなさない。"}, "sentence_index": 6, "correct_answer": "圧力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ガスの圧力を下がった。", "explanation": "助詞の混同：「下がる」は自動詞なので「が」。"}, {"text": "ガスの圧力が三本下がった。", "explanation": "助数詞の誤り：圧力を「本」で数えない。"}, {"text": "ガスの圧力が下がる昨日。", "explanation": "活用・語順の誤り：「昨日」と現在形が合わず、位置も不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7d8f505-44d1-4c26-a7b9-636ede622ea1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
