INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35240, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "掛ける", "is_correct": true, "explanation": "正解。「かける」と読む。"}, {"text": "帰る", "is_correct": false, "explanation": "「かえる」と読む。二つ目のモーラ「け」が「え」に変わる一モーラ差。"}, {"text": "枯れる", "is_correct": false, "explanation": "「かれる」と読む。二つ目のモーラ「け」が「れ」に変わる一モーラ差。"}, {"text": "開ける", "is_correct": false, "explanation": "「あける」と読む。最初のモーラ「か」が「あ」に変わる一モーラ差。"}, {"text": "溶ける", "is_correct": false, "explanation": "「とける」と読む。最初のモーラ「か」が「と」に変わる一モーラ差。"}], "explanations": {"掛ける": "正解。「かける」と読む。", "帰る": "「かえる」と読む。二つ目のモーラ「け」が「え」に変わる一モーラ差。", "枯れる": "「かれる」と読む。二つ目のモーラ「け」が「れ」に変わる一モーラ差。", "開ける": "「あける」と読む。最初のモーラ「か」が「あ」に変わる一モーラ差。", "溶ける": "「とける」と読む。最初のモーラ「か」が「と」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "掛ける"}, "level_3": {"options": [{"text": "掛ける", "is_correct": true, "explanation": "寝ている子の上に毛布をのせておおう。"}, {"text": "食べる", "is_correct": false, "explanation": "意味：毛布を食べるは意味が通らない。"}, {"text": "読む", "is_correct": false, "explanation": "意味：毛布を読むことはできない。"}, {"text": "走る", "is_correct": false, "explanation": "項構造：「走る」は「毛布を」と目的語を取れない。"}], "explanations": {"掛ける": "寝ている子の上に毛布をのせておおう。", "食べる": "意味：毛布を食べるは意味が通らない。", "読む": "意味：毛布を読むことはできない。", "走る": "項構造：「走る」は「毛布を」と目的語を取れない。"}, "sentence_index": 0, "correct_answer": "掛ける"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒いので足を毛布に掛けた。", "explanation": "助詞の混同：「足に毛布を」が正しい。"}, {"text": "寒いので足に毛布を三匹掛けた。", "explanation": "助数詞の誤り：毛布は「枚」で数える。"}, {"text": "寒いので明日足に毛布を掛けた。", "explanation": "活用の誤り：「明日」と過去の「た」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7d8f505-44d1-4c26-a7b9-636ede622ea1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EX