INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35247, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "文字や絵などを、別のものに写し取ること。特に、印刷でインクを紙に移すこと。", "primary_collocate": null, "pronunciation": "てんしゃ", "ipa": "teɴɕa", "syllable_count": 3, "sentences": [{"text": "古い地図を紙に転写した。", "target_word": "転写", "complexity_tier": "T3", "furigana": "ふるい ちず かみ てんしゃ", "sentence_source": "generated"}, {"text": "この絵の転写はとても正確だ。", "target_word": "転写", "complexity_tier": "T3", "furigana": "え てんしゃ せいかく", "sentence_source": "generated"}, {"text": "転写には特別なインクを使う。", "target_word": "転写", "complexity_tier": "T3", "furigana": "てんしゃ とくべつ", "sentence_source": "generated"}, {"text": "兄は図面を丁寧に転写している。", "target_word": "転写", "complexity_tier": "T3", "furigana": "あに ずめん ていねい てんしゃ", "sentence_source": "generated"}, {"text": "転写の作業に一時間かかった。", "target_word": "転写", "complexity_tier": "T3", "furigana": "てんしゃ さぎょう いちじかん", "sentence_source": "generated"}, {"text": "石の模様を布に転写してみた。", "target_word": "転写", "complexity_tier": "T3", "furigana": "いし もよう ぬの てんしゃ", "sentence_source": "generated"}, {"text": "転写された文字が少しにじんだ。", "target_word": "転写", "complexity_tier": "T3", "furigana": "てんしゃ もじ すこ", "sentence_source": "generated"}, {"text": "シールで絵を転写できるよ。", "target_word": "転写", "complexity_tier": "T3", "furigana": "え てんしゃ", "sentence_source": "generated"}, {"text": "先生が転写の方法を教えてくれた。", "target_word": "転写", "complexity_tier": "T3", "furigana": "せんせい てんしゃ ほうほう おし", "sentence_source": "generated"}, {"text": "版画は紙への転写で完成する。", "target_word": "転写", "complexity_tier": "T3", "furigana": "はんが かみ てんしゃ かんせい", "sentence_source": "generated"}], "morphological_forms": [{"form": "転写する", "label": "派生"}, {"form": "転写した", "label": "活用"}, {"form": "転写機", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 文字や絵を別の物に写し取ること", "collocate_grounding": {"status": "no_source", "reason": 