INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35248, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "何かをするために使う、特別な道具や機械のことです。", "primary_collocate": null, "pronunciation": "そうち", "ipa": "soːtɕi", "syllable_count": 3, "sentences": [{"text": "この装置は水をきれいにする。", "target_word": "装置", "complexity_tier": "T3", "furigana": "そうち みず", "sentence_source": "generated"}, {"text": "工場に新しい装置が届いた。", "target_word": "装置", "complexity_tier": "T3", "furigana": "こうじょう あたら そうち とど", "sentence_source": "generated"}, {"text": "装置のスイッチを入れてください。", "target_word": "装置", "complexity_tier": "T3", "furigana": "そうち い", "sentence_source": "generated"}, {"text": "父は装置を点検している。", "target_word": "装置", "complexity_tier": "T3", "furigana": "ちち そうち てんけん", "sentence_source": "generated"}, {"text": "その装置は音で動きを知らせる。", "target_word": "装置", "complexity_tier": "T3", "furigana": "そうち おと うご し", "sentence_source": "generated"}, {"text": "装置が故障して作業が止まった。", "target_word": "装置", "complexity_tier": "T3", "furigana": "そうち こしょう さぎょう と", "sentence_source": "generated"}, {"text": "理科室で実験の装置を組み立てた。", "target_word": "装置", "complexity_tier": "T3", "furigana": "りかしつ じっけん そうち く た", "sentence_source": "generated"}, {"text": "大きな装置を三人で運んだ。", "target_word": "装置", "complexity_tier": "T3", "furigana": "おお そうち さんにん はこ", "sentence_source": "generated"}, {"text": "装置の使い方を説明書で読んだ。", "target_word": "装置", "complexity_tier": "T3", "furigana": "そうち つか かた せつめいしょ よ", "sentence_source": "generated"}, {"text": "兄は小さな装置を自分で作った。", "target_word": "装置", "complexity_tier": "T3", "furigana": "あに ちい そうち じぶん つく", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "助数詞"}, {"form": "安全装置", "label": "派生"}, {"form": "装置する", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 何かをするための特別な機械", "collocate_grounding": {"status": "no_source", "reason": "no collo