INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35250, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "神や仏のために、学びや祈りを続ける生活のこと。", "primary_collocate": null, "pronunciation": "しゅうどう", "ipa": "ɕɯːdoː", "syllable_count": 4, "sentences": [{"text": "彼は山の寺で修道を続けた。", "target_word": "修道", "complexity_tier": "T3", "furigana": "かれ やま てら しゅうどう つづ", "sentence_source": "generated"}, {"text": "修道の生活はとても静かだ。", "target_word": "修道", "complexity_tier": "T3", "furigana": "しゅうどう せいかつ しず", "sentence_source": "generated"}, {"text": "祖父は若いころ修道を志した。", "target_word": "修道", "complexity_tier": "T3", "furigana": "そふ わか しゅうどう こころざ", "sentence_source": "generated"}, {"text": "修道には毎日のお祈りがある。", "target_word": "修道", "complexity_tier": "T3", "furigana": "しゅうどう まいにち いの", "sentence_source": "generated"}, {"text": "修道の道は簡単ではない。", "target_word": "修道", "complexity_tier": "T3", "furigana": "しゅうどう みち かんたん", "sentence_source": "generated"}, {"text": "姉は修道に興味を持っている。", "target_word": "修道", "complexity_tier": "T3", "furigana": "あね しゅうどう きょうみ も", "sentence_source": "generated"}, {"text": "修道をする人は早く起きる。", "target_word": "修道", "complexity_tier": "T3", "furigana": "しゅうどう ひと はや お", "sentence_source": "generated"}, {"text": "彼女は十年間修道に励んだ。", "target_word": "修道", "complexity_tier": "T3", "furigana": "かのじょ じゅうねんかん しゅうどう はげ", "sentence_source": "generated"}, {"text": "修道の中で心が落ち着いた。", "target_word": "修道", "complexity_tier": "T3", "furigana": "しゅうどう なか こころ お つ", "sentence_source": "generated"}, {"text": "本で修道の歴史を学んだ。", "target_word": "修道", "complexity_tier": "T3", "furigana": "ほん しゅうどう れきし まな", "sentence_source": "generated"}], "morphological_forms": [{"form": "修道院", "label": "派生"}, {"form": "修道士", "label": "派生"}, {"form": "修道女", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 神仏のため祈り学ぶ生活", "collocate_grounding": {"status": "no_source", "reason": "n