INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35251, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "宗教的な修行や学問に励みながら、神や仏に仕える生活をすること。特にキリスト教で、修道院で行われる信仰に基づく生活を指す。", "primary_collocate": null, "pronunciation": "しゅうどう", "ipa": "ɕɯːdoː", "syllable_count": 4, "sentences": [{"text": "修道の生活では祈りが中心だ。", "target_word": "修道", "complexity_tier": "T3", "furigana": "しゅうどう せいかつ いの ちゅうしん", "sentence_source": "generated"}, {"text": "彼女は修道院で修道を続けた。", "target_word": "修道", "complexity_tier": "T3", "furigana": "かのじょ しゅうどういん しゅうどう つづ", "sentence_source": "generated"}, {"text": "修道には学問も含まれる。", "target_word": "修道", "complexity_tier": "T3", "furigana": "しゅうどう がくもん ふく", "sentence_source": "generated"}, {"text": "修道の道を選ぶ人は少ない。", "target_word": "修道", "complexity_tier": "T3", "furigana": "しゅうどう みち えら ひと すく", "sentence_source": "generated"}, {"text": "中世には修道が盛んだった。", "target_word": "修道", "complexity_tier": "T3", "furigana": "ちゅうせい しゅうどう さか", "sentence_source": "generated"}, {"text": "彼は修道に一生をささげた。", "target_word": "修道", "complexity_tier": "T3", "furigana": "かれ しゅうどう いっしょう", "sentence_source": "generated"}, {"text": "修道の決まりはとても厳しい。", "target_word": "修道", "complexity_tier": "T3", "furigana": "しゅうどう き きび", "sentence_source": "generated"}, {"text": "修道をする人々が畑で働く。", "target_word": "修道", "complexity_tier": "T3", "furigana": "しゅうどう ひとびと はたけ はたら", "sentence_source": "generated"}, {"text": "修道の考え方に心を動かされた。", "target_word": "修道", "complexity_tier": "T3", "furigana": "しゅうどう かんが かた こころ うご", "sentence_source": "generated"}, {"text": "修道を通して信仰を深めた。", "target_word": "修道", "complexity_tier": "T3", "furigana": "しゅうどう とお しんこう ふか", "sentence_source": "generated"}], "morphological_forms": [{"form": "修道院", "label": "派生"}, {"form": "修道士", "label": "派生"}, {"form": "修道女", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 修道院などで信仰に生きる生活", "colloc