INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35247, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "転写", "is_correct": true, "explanation": "正解。「転写」（てんしゃ）。"}, {"text": "電車", "is_correct": false, "explanation": "「電車」（でんしゃ）。最初の「て」が濁音「で」になる清濁の違い。"}, {"text": "店主", "is_correct": false, "explanation": "「店主」（てんしゅ）。最後のモーラ「しゃ」が「しゅ」に変わる一モーラ差。"}, {"text": "感謝", "is_correct": false, "explanation": "「感謝」（かんしゃ）。最初のモーラ「て」が「か」に変わる一モーラ差。"}, {"text": "点差", "is_correct": false, "explanation": "「点差」（てんさ）。最後のモーラ「しゃ」が「さ」に変わる一モーラ差。"}], "explanations": {"転写": "正解。「転写」（てんしゃ）。", "電車": "「電車」（でんしゃ）。最初の「て」が濁音「で」になる清濁の違い。", "店主": "「店主」（てんしゅ）。最後のモーラ「しゃ」が「しゅ」に変わる一モーラ差。", "感謝": "「感謝」（かんしゃ）。最初のモーラ「て」が「か」に変わる一モーラ差。", "点差": "「点差」（てんさ）。最後のモーラ「しゃ」が「さ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "転写"}, "level_3": {"options": [{"text": "転写", "is_correct": true, "explanation": "地図を紙に写し取ったので「転写」が合う。"}, {"text": "配達", "is_correct": false, "explanation": "地図を紙に配達するとは言わない。"}, {"text": "注文", "is_correct": false, "explanation": "地図を紙に注文するのは不自然。"}, {"text": "掃除", "is_correct": false, "explanation": "地図を紙に掃除するは意味が通らない。"}], "explanations": {"転写": "地図を紙に写し取ったので「転写」が合う。", "配達": "地図を紙に配達するとは言わない。", "注文": "地図を紙に注文するのは不自然。", "掃除": "地図を紙に掃除するは意味が通らない。"}, "sentence_index": 0, "correct_answer": "転写"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、駅まで転写で通っている。", "explanation": "「転写」は写し取ることで、乗り物ではない。"}, {"text": "彼の意見に転写して手をあげた。", "explanation": "賛成の意味で「転写」は使えない。"}, {"text": "夕ごはんに魚を転写して食べた。", "explanation": "料理の意味で「転写」は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba4fcb32-ffb7-4bef-a0b1-c7efa065a4f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validatio