INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35247, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "転写", "is_correct": true, "explanation": "正解。「転写」（てんしゃ）。"}, {"text": "天使", "is_correct": false, "explanation": "「天使」（てんし）。最後のモーラ「しゃ」が「し」に変わる一モーラ差。"}, {"text": "単車", "is_correct": false, "explanation": "「単車」（たんしゃ）。最初のモーラ「て」が「た」に変わる一モーラ差。"}, {"text": "電車", "is_correct": false, "explanation": "「電車」（でんしゃ）。最初の「て」が「で」になる清濁の違い。"}, {"text": "店舗", "is_correct": false, "explanation": "「店舗」（てんぽ）。最後のモーラ「しゃ」が「ぽ」に変わる一モーラ差。"}], "explanations": {"転写": "正解。「転写」（てんしゃ）。", "天使": "「天使」（てんし）。最後のモーラ「しゃ」が「し」に変わる一モーラ差。", "単車": "「単車」（たんしゃ）。最初のモーラ「て」が「た」に変わる一モーラ差。", "電車": "「電車」（でんしゃ）。最初の「て」が「で」になる清濁の違い。", "店舗": "「店舗」（てんぽ）。最後のモーラ「しゃ」が「ぽ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "転写"}, "level_3": {"options": [{"text": "転写", "is_correct": true, "explanation": "写し取られた文字がにじむので「転写」が合う。"}, {"text": "変更", "is_correct": false, "explanation": "「変更された文字がにじんだ」は意味がつながらない。"}, {"text": "発表", "is_correct": false, "explanation": "発表された文字がにじむのは不自然。"}, {"text": "説明", "is_correct": false, "explanation": "説明された文字がにじむは意味が合わない。"}], "explanations": {"転写": "写し取られた文字がにじむので「転写」が合う。", "変更": "「変更された文字がにじんだ」は意味がつながらない。", "発表": "発表された文字がにじむのは不自然。", "説明": "説明された文字がにじむは意味が合わない。"}, "sentence_index": 6, "correct_answer": "転写"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "風邪を転写して学校を休んだ。", "explanation": "病気がうつる意味で「転写」は使わない。"}, {"text": "引っ越しで家を転写した。", "explanation": "住まいを移す意味では使わない。"}, {"text": "友だちに手紙を転写して送った。", "explanation": "送る・届ける意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba4fcb32-ffb7-4bef-a0b1-c7efa065a4f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCL