INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35250, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "修道", "is_correct": true, "explanation": "正解。「修道」（しゅうどう）。"}, {"text": "手動", "is_correct": false, "explanation": "「手動」（しゅどう）。「しゅう」の長音が短くなる長短母音の違い。"}, {"text": "柔道", "is_correct": false, "explanation": "「柔道」（じゅうどう）。最初の「しゅ」が「じゅ」になる清濁の違い。"}, {"text": "就労", "is_correct": false, "explanation": "「就労」（しゅうろう）。三つ目のモーラ「ど」が「ろ」に変わる一モーラ差。"}, {"text": "衝動", "is_correct": false, "explanation": "「衝動」（しょうどう）。最初のモーラ「しゅ」が「しょ」に変わる一モーラ差。"}], "explanations": {"修道": "正解。「修道」（しゅうどう）。", "手動": "「手動」（しゅどう）。「しゅう」の長音が短くなる長短母音の違い。", "柔道": "「柔道」（じゅうどう）。最初の「しゅ」が「じゅ」になる清濁の違い。", "就労": "「就労」（しゅうろう）。三つ目のモーラ「ど」が「ろ」に変わる一モーラ差。", "衝動": "「衝動」（しょうどう）。最初のモーラ「しゅ」が「しょ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "修道"}, "level_3": {"options": [{"text": "修道", "is_correct": true, "explanation": "山の寺で続ける信仰の生活なので「修道」が合う。"}, {"text": "買い物", "is_correct": false, "explanation": "寺で買い物を続けるは文意に合わない。"}, {"text": "旅行", "is_correct": false, "explanation": "寺で旅行を続けるは不自然。"}, {"text": "試合", "is_correct": false, "explanation": "寺で試合を続けるは意味が通らない。"}], "explanations": {"修道": "山の寺で続ける信仰の生活なので「修道」が合う。", "買い物": "寺で買い物を続けるは文意に合わない。", "旅行": "寺で旅行を続けるは不自然。", "試合": "寺で試合を続けるは意味が通らない。"}, "sentence_index": 0, "correct_answer": "修道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "修道でコンビニまで行った。", "explanation": "道路や乗り物の意味では使わない。"}, {"text": "この服はとても修道だね。", "explanation": "服の性質を表す語ではない。"}, {"text": "壊れた自転車を修道した。", "explanation": "修理の意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba4fcb32-ffb7-4bef-a0b1-c7efa065a4f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, 