INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35251, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "修道", "is_correct": true, "explanation": "正解。「修道」（しゅうどう）。"}, {"text": "柔道", "is_correct": false, "explanation": "「柔道」（じゅうどう）。最初の「しゅ」が「じゅ」になる清濁の違い。"}, {"text": "集合", "is_correct": false, "explanation": "「集合」（しゅうごう）。三つ目のモーラ「ど」が「ご」に変わる一モーラ差。"}, {"text": "手動", "is_correct": false, "explanation": "「手動」（しゅどう）。「しゅう」の長音が短くなる長短母音の違い。"}, {"text": "中道", "is_correct": false, "explanation": "「中道」（ちゅうどう）。最初のモーラ「しゅ」が「ちゅ」に変わる一モーラ差。"}], "explanations": {"修道": "正解。「修道」（しゅうどう）。", "柔道": "「柔道」（じゅうどう）。最初の「しゅ」が「じゅ」になる清濁の違い。", "集合": "「集合」（しゅうごう）。三つ目のモーラ「ど」が「ご」に変わる一モーラ差。", "手動": "「手動」（しゅどう）。「しゅう」の長音が短くなる長短母音の違い。", "中道": "「中道」（ちゅうどう）。最初のモーラ「しゅ」が「ちゅ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "修道"}, "level_3": {"options": [{"text": "修道", "is_correct": true, "explanation": "祈りが中心となる信仰の生活なので「修道」が合う。"}, {"text": "会社", "is_correct": false, "explanation": "会社の生活で祈りが中心は不自然。"}, {"text": "都会", "is_correct": false, "explanation": "都会の生活で祈りが中心は文意に合わない。"}, {"text": "部活", "is_correct": false, "explanation": "部活の生活で祈りが中心は意味が通らない。"}], "explanations": {"修道": "祈りが中心となる信仰の生活なので「修道」が合う。", "会社": "会社の生活で祈りが中心は不自然。", "都会": "都会の生活で祈りが中心は文意に合わない。", "部活": "部活の生活で祈りが中心は意味が通らない。"}, "sentence_index": 0, "correct_answer": "修道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "修道を走って学校へ行った。", "explanation": "道路の意味では使わない。"}, {"text": "このケーキは修道でおいしい。", "explanation": "味や性質を表す語ではない。"}, {"text": "壊れた時計を修道に出した。", "explanation": "修理の意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba4fcb32-ffb7-4bef-a0b1-c7efa065a4f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.vali