INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35254, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "もとの書類と同じ内容に作ったもの。コピー。", "primary_collocate": null, "pronunciation": "うつし", "ipa": "ɯtsɯɕi", "syllable_count": 3, "sentences": [{"text": "住民票の写しを持ってきてください。", "target_word": "写し", "complexity_tier": "T3", "furigana": "じゅうみんひょう うつし も", "sentence_source": "generated"}, {"text": "契約書の写しは私が持っている。", "target_word": "写し", "complexity_tier": "T3", "furigana": "けいやくしょ うつし わたし も", "sentence_source": "generated"}, {"text": "写しを一枚もらえますか。", "target_word": "写し", "complexity_tier": "T3", "furigana": "うつし いちまい", "sentence_source": "generated"}, {"text": "この写しは原本と同じ内容だ。", "target_word": "写し", "complexity_tier": "T3", "furigana": "うつし げんぽん おな ないよう", "sentence_source": "generated"}, {"text": "免許証の写しが必要です。", "target_word": "写し", "complexity_tier": "T3", "furigana": "めんきょしょう うつし ひつよう", "sentence_source": "generated"}, {"text": "写しを取ってから原本を返した。", "target_word": "写し", "complexity_tier": "T3", "furigana": "うつし と げんぽん かえ", "sentence_source": "generated"}, {"text": "先生に答案の写しを渡した。", "target_word": "写し", "complexity_tier": "T3", "furigana": "せんせい とうあん うつし わた", "sentence_source": "generated"}, {"text": "写しだけでは手続きができない。", "target_word": "写し", "complexity_tier": "T3", "furigana": "うつし てつづ", "sentence_source": "generated"}, {"text": "申込書の写しを大切に保管している。", "target_word": "写し", "complexity_tier": "T3", "furigana": "もうしこみしょ うつし たいせつ ほかん", "sentence_source": "generated"}, {"text": "これは手紙の写しで、本物ではない。", "target_word": "写し", "complexity_tier": "T3", "furigana": "てがみ うつし ほんもの", "sentence_source": "generated"}], "morphological_forms": [{"form": "写す", "label": "派生"}, {"form": "写し取る", "label": "派生"}, {"form": "枚", "label": "助数詞"}], "register": "formal", "sense_fingerprint": "名詞 | 書類などを同じに作ったもの", "collocate_grounding": {"status": "no_source", "reason": "no