INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35255, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "もとの文や絵と同じ内容を書き写すこと。", "primary_collocate": null, "pronunciation": "うつし", "ipa": "ɯtsɯɕi", "syllable_count": 3, "sentences": [{"text": "お経の写しを毎朝続けている。", "target_word": "写し", "complexity_tier": "T3", "furigana": "きょう うつし まいあさ つづ", "sentence_source": "generated"}, {"text": "古い本の写しには時間がかかる。", "target_word": "写し", "complexity_tier": "T3", "furigana": "ふる ほん うつし じかん", "sentence_source": "generated"}, {"text": "写しの作業は一日で終わった。", "target_word": "写し", "complexity_tier": "T3", "furigana": "うつし さぎょう いちにち お", "sentence_source": "generated"}, {"text": "弟は漢字の写しが苦手だ。", "target_word": "写し", "complexity_tier": "T3", "furigana": "おとうと かんじ うつし にがて", "sentence_source": "generated"}, {"text": "昔は写しで本を増やしていた。", "target_word": "写し", "complexity_tier": "T3", "furigana": "むかし うつし ほん ふ", "sentence_source": "generated"}, {"text": "写しを間違えないように気をつけた。", "target_word": "写し", "complexity_tier": "T3", "furigana": "うつし まちが き", "sentence_source": "generated"}, {"text": "絵の写しを習っている。", "target_word": "写し", "complexity_tier": "T3", "furigana": "え うつし なら", "sentence_source": "generated"}, {"text": "写しは丁寧にゆっくり進めた。", "target_word": "写し", "complexity_tier": "T3", "furigana": "うつし ていねい すす", "sentence_source": "generated"}, {"text": "写しが終わったら先生に見せよう。", "target_word": "写し", "complexity_tier": "T3", "furigana": "うつし お せんせい み", "sentence_source": "generated"}, {"text": "手での写しは集中力が必要だ。", "target_word": "写し", "complexity_tier": "T3", "furigana": "て うつし しゅうちゅうりょく ひつよう", "sentence_source": "generated"}], "morphological_forms": [{"form": "写す", "label": "派生"}, {"form": "書き写し", "label": "派生"}, {"form": "写し方", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 原本と同じ内容を書き写すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asser