INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35258, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "決まっていたことや結果を、まったく反対のものに変える。", "primary_collocate": null, "pronunciation": "くつがえす", "ipa": "kɯtsɯɡaesɯ", "syllable_count": 5, "sentences": [{"text": "弱いチームが予想を覆した。", "target_word": "覆し", "complexity_tier": "T3", "furigana": "よわ よそう くつがえ", "sentence_source": "generated"}, {"text": "裁判所が前の判決を覆した。", "target_word": "覆し", "complexity_tier": "T3", "furigana": "さいばんしょ まえ はんけつ くつがえ", "sentence_source": "generated"}, {"text": "彼は最後に試合の流れを覆した。", "target_word": "覆し", "complexity_tier": "T3", "furigana": "かれ さいご しあい なが くつがえ", "sentence_source": "generated"}, {"text": "一度決めた結論は覆さない。", "target_word": "覆さ", "complexity_tier": "T3", "furigana": "いちど き けつろん くつがえ", "sentence_source": "generated"}, {"text": "新しい証拠が判断を覆した。", "target_word": "覆し", "complexity_tier": "T3", "furigana": "あたら しょうこ はんだん くつがえ", "sentence_source": "generated"}, {"text": "負けている試合を覆すのは難しい。", "target_word": "覆す", "complexity_tier": "T3", "furigana": "ま しあい くつがえ むずか", "sentence_source": "generated"}, {"text": "彼女は不利な状況を覆して勝った。", "target_word": "覆し", "complexity_tier": "T3", "furigana": "かのじょ ふり じょうきょう くつがえ か", "sentence_source": "generated"}, {"text": "結果を覆すほどの点差ではない。", "target_word": "覆す", "complexity_tier": "T3", "furigana": "けっか くつがえ てんさ", "sentence_source": "generated"}, {"text": "審判の決定が覆されることはない。", "target_word": "覆さ", "complexity_tier": "T3", "furigana": "しんぱん けってい くつがえ", "sentence_source": "generated"}, {"text": "みんなの評価を覆したい。", "target_word": "覆し", "complexity_tier": "T3", "furigana": "ひょうか くつがえ", "sentence_source": "generated"}], "morphological_forms": [{"form": "覆した", "label": "活用"}, {"form": "覆して", "label": "活用"}, {"form": "覆さない", "label": "活用"}, {"form": "覆される", "label": "活用"}], "register": "formal", "sense_fingerprint": "動詞 | 結果や判断を反対に変える", "colloca