INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35259, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "今まで正しいとされていた考えや体制を、新しいものに変える。", "primary_collocate": "常識", "pronunciation": "くつがえす", "ipa": "kɯtsɯɡaesɯ", "syllable_count": 5, "sentences": [{"text": "その発見は常識を覆した。", "target_word": "覆し", "complexity_tier": "T3", "furigana": "はっけん じょうしき くつがえ", "sentence_source": "generated"}, {"text": "彼の研究は古い定説を覆した。", "target_word": "覆し", "complexity_tier": "T3", "furigana": "かれ けんきゅう ふる ていせつ くつがえ", "sentence_source": "generated"}, {"text": "常識を覆す新しい考え方だ。", "target_word": "覆す", "complexity_tier": "T3", "furigana": "じょうしき くつがえ あたら かんが かた", "sentence_source": "generated"}, {"text": "人々は古い体制を覆そうとした。", "target_word": "覆そ", "complexity_tier": "T3", "furigana": "ひとびと ふる たいせい くつがえ", "sentence_source": "generated"}, {"text": "伝統を覆すのは簡単ではない。", "target_word": "覆す", "complexity_tier": "T3", "furigana": "でんとう くつがえ かんたん", "sentence_source": "generated"}, {"text": "長年の考えが一つの実験で覆された。", "target_word": "覆さ", "complexity_tier": "T3", "furigana": "ながねん かんが ひと じっけん くつがえ", "sentence_source": "generated"}, {"text": "若い画家が絵の常識を覆している。", "target_word": "覆し", "complexity_tier": "T3", "furigana": "わか がか え じょうしき くつがえ", "sentence_source": "generated"}, {"text": "この本は歴史の見方を覆した。", "target_word": "覆し", "complexity_tier": "T3", "furigana": "ほん れきし みかた くつがえ", "sentence_source": "generated"}, {"text": "権力を覆す動きが広がった。", "target_word": "覆す", "complexity_tier": "T3", "furigana": "けんりょく くつがえ うご ひろ", "sentence_source": "generated"}, {"text": "常識は覆せると彼は信じている。", "target_word": "覆せ", "complexity_tier": "T3", "furigana": "じょうしき くつがえ かれ しん", "sentence_source": "generated"}], "morphological_forms": [{"form": "覆した", "label": "活用"}, {"form": "覆して", "label": "活用"}, {"form": "覆される", "label": "活用"}, {"form": "覆せる", "label": "活用"}], "register": "formal", "sense_fingerprint": "動詞 