INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35260, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "少しずつたくさんためること。また、ためたもの。", "primary_collocate": null, "pronunciation": "ちくせき", "ipa": "tɕikɯseki", "syllable_count": 4, "sentences": [{"text": "毎日の練習の蓄積が力になる。", "target_word": "蓄積", "complexity_tier": "T3", "furigana": "まいにち れんしゅう ちくせき ちから", "sentence_source": "generated"}, {"text": "疲れが蓄積して体調をくずした。", "target_word": "蓄積", "complexity_tier": "T3", "furigana": "つか ちくせき たいちょう", "sentence_source": "generated"}, {"text": "知識の蓄積には時間がかかる。", "target_word": "蓄積", "complexity_tier": "T3", "furigana": "ちしき ちくせき じかん", "sentence_source": "generated"}, {"text": "データを蓄積して分析する。", "target_word": "蓄積", "complexity_tier": "T3", "furigana": "ぶんせき ちくせき", "sentence_source": "generated"}, {"text": "経験の蓄積が自信につながった。", "target_word": "蓄積", "complexity_tier": "T3", "furigana": "けいけん ちくせき じしん", "sentence_source": "generated"}, {"text": "ストレスの蓄積は体に悪い。", "target_word": "蓄積", "complexity_tier": "T3", "furigana": "ちくせき からだ わる", "sentence_source": "generated"}, {"text": "ごみが蓄積している川がある。", "target_word": "蓄積", "complexity_tier": "T3", "furigana": "ちくせき かわ", "sentence_source": "generated"}, {"text": "この会社には技術の蓄積がある。", "target_word": "蓄積", "complexity_tier": "T3", "furigana": "かいしゃ ぎじゅつ ちくせき", "sentence_source": "generated"}, {"text": "小さな努力を蓄積していきたい。", "target_word": "蓄積", "complexity_tier": "T3", "furigana": "ちい どりょく ちくせき", "sentence_source": "generated"}, {"text": "長年蓄積された記録を調べた。", "target_word": "蓄積", "complexity_tier": "T3", "furigana": "ながねん ちくせき きろく しら", "sentence_source": "generated"}], "morphological_forms": [{"form": "蓄積する", "label": "派生"}, {"form": "蓄積した", "label": "活用"}, {"form": "蓄積されて", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | 少しずつ多くためること", "collocate_grounding": {"status": "no_source", "reason": "no colloca