INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35254, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "写し", "is_correct": true, "explanation": "「うつし」：書類のコピー。"}, {"text": "器", "is_correct": false, "explanation": "「うつわ」：最後の音が違う。入れ物のこと。"}, {"text": "移り", "is_correct": false, "explanation": "「うつり」：最後の音が違う。移ること。"}, {"text": "現", "is_correct": false, "explanation": "「うつつ」：最後の音が違う。現実のこと。"}, {"text": "仏師", "is_correct": false, "explanation": "「ぶつし」：最初の音が違う。仏像を作る人。"}], "explanations": {"写し": "「うつし」：書類のコピー。", "器": "「うつわ」：最後の音が違う。入れ物のこと。", "移り": "「うつり」：最後の音が違う。移ること。", "現": "「うつつ」：最後の音が違う。現実のこと。", "仏師": "「ぶつし」：最初の音が違う。仏像を作る人。"}, "sentence_index": null, "correct_answer": "写し"}, "level_3": {"options": [{"text": "写し", "is_correct": true, "explanation": "住民票のコピーという意味で合う。"}, {"text": "天気", "is_correct": false, "explanation": "住民票の天気は意味をなさない。"}, {"text": "下書き", "is_correct": false, "explanation": "住民票に下書きはない。"}, {"text": "感想", "is_correct": false, "explanation": "住民票の感想は意味をなさない。"}], "explanations": {"写し": "住民票のコピーという意味で合う。", "天気": "住民票の天気は意味をなさない。", "下書き": "住民票に下書きはない。", "感想": "住民票の感想は意味をなさない。"}, "sentence_index": 0, "correct_answer": "写し"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "写しを着て出かけた。", "explanation": "書類のコピーは服ではない。"}, {"text": "彼は顔の写しがとても明るい。", "explanation": "性格や表情の意味では使わない。"}, {"text": "写しを食べたらおなかが痛くなった。", "explanation": "書類のコピーは食べ物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ece5ce-747b-4422-b01b-522e608a4d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
