INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35262, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものが人から人へと広がっていくこと。", "primary_collocate": null, "pronunciation": "りゅうつう", "ipa": "ɾʲɯːtsɯː", "syllable_count": 4, "sentences": [{"text": "この言葉は若者の間で流通している。", "target_word": "流通", "complexity_tier": "T3", "furigana": "ことば わかもの あいだ りゅうつう", "sentence_source": "generated"}, {"text": "昔の硬貨はもう流通していない。", "target_word": "流通", "complexity_tier": "T3", "furigana": "むかし こうか りゅうつう", "sentence_source": "generated"}, {"text": "うわさの流通はとても速い。", "target_word": "流通", "complexity_tier": "T3", "furigana": "りゅうつう はや", "sentence_source": "generated"}, {"text": "新しい考えが人々に流通した。", "target_word": "流通", "complexity_tier": "T3", "furigana": "あたら かんが ひとびと りゅうつう", "sentence_source": "generated"}, {"text": "その本は手から手へと流通した。", "target_word": "流通", "complexity_tier": "T3", "furigana": "ほん て て りゅうつう", "sentence_source": "generated"}, {"text": "流通している話が本当とは限らない。", "target_word": "流通", "complexity_tier": "T3", "furigana": "りゅうつう はなし ほんとう かぎ", "sentence_source": "generated"}, {"text": "この写真は町中に流通している。", "target_word": "流通", "complexity_tier": "T3", "furigana": "しゃしん まちじゅう りゅうつう", "sentence_source": "generated"}, {"text": "偽のお札の流通が問題になった。", "target_word": "流通", "complexity_tier": "T3", "furigana": "にせ さつ りゅうつう もんだい", "sentence_source": "generated"}, {"text": "情報の流通を止めるのは難しい。", "target_word": "流通", "complexity_tier": "T3", "furigana": "じょうほう りゅうつう と むずか", "sentence_source": "generated"}, {"text": "古い地図が今も流通している。", "target_word": "流通", "complexity_tier": "T3", "furigana": "ふる ちず いま りゅうつう", "sentence_source": "generated"}], "morphological_forms": [{"form": "流通する", "label": "派生"}, {"form": "流通した", "label": "活用"}, {"form": "流通している", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | ものが人から人へ広がること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43983848-d34d-48bb-b4db-b8a76648d11d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35263, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "品物やお金、情報などが広く世の中に出回って、人から人へと移っていくこと。", "primary_collocate": null, "pronunciation": "りゅうつう", "ipa": "ɾʲɯːtsɯː", "syllable_count": 4, "sentences": [{"text": "父は流通の会社で働いている。", "target_word": "流通", "complexity_tier": "T3", "furigana": "ちち りゅうつう かいしゃ はたら", "sentence_source": "generated"}, {"text": "野菜の流通にはトラックが必要だ。", "target_word": "流通", "complexity_tier": "T3", "furigana": "やさい りゅうつう ひつよう", "sentence_source": "generated"}, {"text": "この商品は全国に流通している。", "target_word": "流通", "complexity_tier": "T3", "furigana": "しょうひん ぜんこく りゅうつう", "sentence_source": "generated"}, {"text": "お金の流通が少なくなった。", "target_word": "流通", "complexity_tier": "T3", "furigana": "かね りゅうつう すく", "sentence_source": "generated"}, {"text": "流通のしくみを授業で学んだ。", "target_word": "流通", "complexity_tier": "T3", "furigana": "りゅうつう じゅぎょう まな", "sentence_source": "generated"}, {"text": "台風で米の流通が止まった。", "target_word": "流通", "complexity_tier": "T3", "furigana": "たいふう こめ りゅうつう と", "sentence_source": "generated"}, {"text": "この魚は市場で流通しない。", "target_word": "流通", "complexity_tier": "T3", "furigana": "さかな いちば りゅうつう", "sentence_source": "generated"}, {"text": "流通コストが高いと値段も上がる。", "target_word": "流通", "complexity_tier": "T3", "furigana": "りゅうつう たか ねだん あ", "sentence_source": "generated"}, {"text": "ネットで流通する商品が増えた。", "target_word": "流通", "complexity_tier": "T3", "furigana": "りゅうつう しょうひん ふ", "sentence_source": "generated"}, {"text": "新しいお札が流通し始めた。", "target_word": "流通", "complexity_tier": "T3", "furigana": "あたら さつ りゅうつう はじ", "sentence_source": "generated"}], "morphological_forms": [{"form": "流通する", "label": "派生"}, {"form": "流通業", "label": "派生"}, {"form": "流通量", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 品物やお金が世の中に出回ること", "collocate_grounding": {"status": "no_