INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35264, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "とてもという意味。", "primary_collocate": null, "pronunciation": "ごく", "ipa": "ɡokɯ", "syllable_count": 2, "sentences": [{"text": "それは極く簡単な問題だ。", "target_word": "極く", "complexity_tier": "T3", "furigana": "ご かんたん もんだい", "sentence_source": "generated"}, {"text": "極く小さな虫を見つけた。", "target_word": "極く", "complexity_tier": "T3", "furigana": "ご ちい むし み", "sentence_source": "generated"}, {"text": "彼女とは極く親しい友達だ。", "target_word": "極く", "complexity_tier": "T3", "furigana": "ご した ともだち", "sentence_source": "generated"}, {"text": "この町は極く静かです。", "target_word": "極く", "complexity_tier": "T3", "furigana": "ご まち しず", "sentence_source": "generated"}, {"text": "極く普通の家に住んでいる。", "target_word": "極く", "complexity_tier": "T3", "furigana": "ご ふつう いえ す", "sentence_source": "generated"}, {"text": "その話を知る人は極く少ない。", "target_word": "極く", "complexity_tier": "T3", "furigana": "ご はなし し ひと すく", "sentence_source": "generated"}, {"text": "極く近い場所に駅がある。", "target_word": "極く", "complexity_tier": "T3", "furigana": "ご ちか ばしょ えき", "sentence_source": "generated"}, {"text": "極くたまに映画を見る。", "target_word": "極く", "complexity_tier": "T3", "furigana": "ご えいが み", "sentence_source": "generated"}, {"text": "今日は極く短い時間しかない。", "target_word": "極く", "complexity_tier": "T3", "furigana": "ご きょう みじか じかん", "sentence_source": "generated"}, {"text": "極く一部の人だけが来た。", "target_word": "極く", "complexity_tier": "T3", "furigana": "ご いちぶ ひと き", "sentence_source": "generated"}], "morphological_forms": [{"form": "ごく", "label": "派生"}, {"form": "極めて", "label": "派生"}, {"form": "至極", "label": "派生"}], "register": "plain", "sense_fingerprint": "副詞 | とても、非常にという程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', tr