INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35265, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "程度が非常に大きいさま。きわめて。", "primary_collocate": null, "pronunciation": "ごく", "ipa": "ɡokɯ", "syllable_count": 2, "sentences": [{"text": "それは極くまれなことだ。", "target_word": "極く", "complexity_tier": "T3", "furigana": "ご", "sentence_source": "generated"}, {"text": "極くわずかな差で負けた。", "target_word": "極く", "complexity_tier": "T3", "furigana": "ご さ ま", "sentence_source": "generated"}, {"text": "この薬は極く少量で効く。", "target_word": "極く", "complexity_tier": "T3", "furigana": "ご くすり しょうりょう き", "sentence_source": "generated"}, {"text": "極く自然に笑顔になった。", "target_word": "極く", "complexity_tier": "T3", "furigana": "ご しぜん えがお", "sentence_source": "generated"}, {"text": "その考えは極く当たり前だ。", "target_word": "極く", "complexity_tier": "T3", "furigana": "ご かんが あ まえ", "sentence_source": "generated"}, {"text": "極く初期の作品が残っている。", "target_word": "極く", "complexity_tier": "T3", "furigana": "ご しょき さくひん のこ", "sentence_source": "generated"}, {"text": "彼の失敗は極く小さかった。", "target_word": "極く", "complexity_tier": "T3", "furigana": "ご かれ しっぱい ちい", "sentence_source": "generated"}, {"text": "極く最近、引っ越しをした。", "target_word": "極く", "complexity_tier": "T3", "furigana": "ご さいきん ひ こ", "sentence_source": "generated"}, {"text": "ここでは極く短い夏が来る。", "target_word": "極く", "complexity_tier": "T3", "furigana": "ご みじか なつ く", "sentence_source": "generated"}, {"text": "極く限られた人しか入れない。", "target_word": "極く", "complexity_tier": "T3", "furigana": "ご かぎ ひと はい", "sentence_source": "generated"}], "morphological_forms": [{"form": "ごく", "label": "派生"}, {"form": "極めて", "label": "派生"}, {"form": "至極", "label": "派生"}], "register": "formal", "sense_fingerprint": "副詞 | 程度がきわめて大きいさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', '