INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35270, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人を、お金や力の大きさで分けたグループ。", "primary_collocate": null, "pronunciation": "かいきゅう", "ipa": "kaikʲɯː", "syllable_count": 4, "sentences": [{"text": "昔は階級によって服が違った。", "target_word": "階級", "complexity_tier": "T3", "furigana": "むかし かいきゅう ふく ちが", "sentence_source": "generated"}, {"text": "彼は貴族の階級に生まれた。", "target_word": "階級", "complexity_tier": "T3", "furigana": "かれ きぞく かいきゅう う", "sentence_source": "generated"}, {"text": "階級の差をなくしたいと思う。", "target_word": "階級", "complexity_tier": "T3", "furigana": "かいきゅう さ おも", "sentence_source": "generated"}, {"text": "その国には厳しい階級があった。", "target_word": "階級", "complexity_tier": "T3", "furigana": "くに きび かいきゅう", "sentence_source": "generated"}, {"text": "階級が違うと結婚できなかった。", "target_word": "階級", "complexity_tier": "T3", "furigana": "かいきゅう ちが けっこん", "sentence_source": "generated"}, {"text": "働く人の階級が力を持ち始めた。", "target_word": "階級", "complexity_tier": "T3", "furigana": "はたら ひと かいきゅう ちから も はじ", "sentence_source": "generated"}, {"text": "社会の階級について授業で学んだ。", "target_word": "階級", "complexity_tier": "T3", "furigana": "しゃかい かいきゅう じゅぎょう まな", "sentence_source": "generated"}, {"text": "お金持ちの階級は少数だった。", "target_word": "階級", "complexity_tier": "T3", "furigana": "かねも かいきゅう しょうすう", "sentence_source": "generated"}, {"text": "人を階級で分けるのはよくない。", "target_word": "階級", "complexity_tier": "T3", "furigana": "ひと かいきゅう わ", "sentence_source": "generated"}, {"text": "彼らは同じ階級の人と遊んだ。", "target_word": "階級", "complexity_tier": "T3", "furigana": "かれ おな かいきゅう ひと あそ", "sentence_source": "generated"}], "morphological_forms": [{"form": "階級社会", "label": "派生"}, {"form": "上流階級", "label": "派生"}, {"form": "労働者階級", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 財産や力で分けた人の層", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43983848-d34d-48bb-b4db-b8a76648d11d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35272, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "神さまや仏さまを信じる人たちの集まりや、その教えのこと。", "primary_collocate": null, "pronunciation": "しゅうきょう", "ipa": "ɕɯːkʲoː", "syllable_count": 4, "sentences": [{"text": "世界にはたくさんの宗教がある。", "target_word": "宗教", "complexity_tier": "T3", "furigana": "せかい しゅうきょう", "sentence_source": "generated"}, {"text": "宗教の話は少し難しい。", "target_word": "宗教", "complexity_tier": "T3", "furigana": "しゅうきょう はなし すこ むずか", "sentence_source": "generated"}, {"text": "彼は宗教を大切にしている。", "target_word": "宗教", "complexity_tier": "T3", "furigana": "かれ しゅうきょう たいせつ", "sentence_source": "generated"}, {"text": "宗教によって食べ物が違う。", "target_word": "宗教", "complexity_tier": "T3", "furigana": "しゅうきょう た もの ちが", "sentence_source": "generated"}, {"text": "その祭りは宗教と関係がある。", "target_word": "宗教", "complexity_tier": "T3", "furigana": "まつ しゅうきょう かんけい", "sentence_source": "generated"}, {"text": "宗教を信じない人もいる。", "target_word": "宗教", "complexity_tier": "T3", "furigana": "しゅうきょう しん ひと", "sentence_source": "generated"}, {"text": "授業で世界の宗教を学んだ。", "target_word": "宗教", "complexity_tier": "T3", "furigana": "じゅぎょう せかい しゅうきょう まな", "sentence_source": "generated"}, {"text": "宗教が違っても仲良くできる。", "target_word": "宗教", "complexity_tier": "T3", "furigana": "しゅうきょう ちが なかよ", "sentence_source": "generated"}, {"text": "この寺は古い宗教の建物だ。", "target_word": "宗教", "complexity_tier": "T3", "furigana": "てら ふる しゅうきょう たてもの", "sentence_source": "generated"}, {"text": "宗教の教えを守って暮らす。", "target_word": "宗教", "complexity_tier": "T3", "furigana": "しゅうきょう おし まも く", "sentence_source": "generated"}], "morphological_forms": [{"form": "宗教的", "label": "派生"}, {"form": "宗教家", "label": "派生"}, {"form": "宗教団体", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 神仏を信じる教えや集まり", "collocate_grounding": {"status": "no_source", "reason": "n