INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35262, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "流通", "is_correct": true, "explanation": "正解。読みは「りゅうつう」。"}, {"text": "流行", "is_correct": false, "explanation": "読みは「りゅうこう」。「つ」が「こ」に変わる一モーラ差。"}, {"text": "流暢", "is_correct": false, "explanation": "読みは「りゅうちょう」。「つ」が「ちょ」に変わる一モーラ差。"}, {"text": "流動", "is_correct": false, "explanation": "読みは「りゅうどう」。「つ」が「ど」に変わる一モーラ差。"}, {"text": "琉球", "is_correct": false, "explanation": "読みは「りゅうきゅう」。「つ」が「きゅ」に変わる一モーラ差。"}], "explanations": {"流通": "正解。読みは「りゅうつう」。", "流行": "読みは「りゅうこう」。「つ」が「こ」に変わる一モーラ差。", "流暢": "読みは「りゅうちょう」。「つ」が「ちょ」に変わる一モーラ差。", "流動": "読みは「りゅうどう」。「つ」が「ど」に変わる一モーラ差。", "琉球": "読みは「りゅうきゅう」。「つ」が「きゅ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "流通"}, "level_3": {"options": [{"text": "流通", "is_correct": true, "explanation": "文脈に合う正しい語。"}, {"text": "卒業", "is_correct": false, "explanation": "意味：言葉が卒業することはない。"}, {"text": "入院", "is_correct": false, "explanation": "意味：言葉は入院しない。"}, {"text": "建設", "is_correct": false, "explanation": "項構造：「言葉が建設している」は主語と動作が合わない。"}], "explanations": {"流通": "文脈に合う正しい語。", "卒業": "意味：言葉が卒業することはない。", "入院": "意味：言葉は入院しない。", "建設": "項構造：「言葉が建設している」は主語と動作が合わない。"}, "sentence_index": 0, "correct_answer": "流通"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい考えを人々に流通した。", "explanation": "助詞の混同：「流通する」は自動詞なので「考えが」とすべき。"}, {"text": "新しい考えが人々に流通してある。", "explanation": "アスペクトの誤り：「てある」は他動詞に使う。"}, {"text": "新しい考えが人々に流通させた。", "explanation": "態の誤り：「流通させる」は使役で、主語「考えが」と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f8c8899-2189-4ffb-877c-03fbf4f1d020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation