INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35273, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "神や仏を信じ、その教えや儀式をもつ文化のこと。", "primary_collocate": null, "pronunciation": "しゅうきょう", "ipa": "ɕɯːkʲoː", "syllable_count": 4, "sentences": [{"text": "世界にはたくさんの宗教がある。", "target_word": "宗教", "complexity_tier": "T3", "furigana": "せかい しゅうきょう", "sentence_source": "generated"}, {"text": "宗教について授業で学んだ。", "target_word": "宗教", "complexity_tier": "T3", "furigana": "しゅうきょう じゅぎょう まな", "sentence_source": "generated"}, {"text": "祖母は宗教を大切にしている。", "target_word": "宗教", "complexity_tier": "T3", "furigana": "そぼ しゅうきょう たいせつ", "sentence_source": "generated"}, {"text": "この国では宗教の自由が守られている。", "target_word": "宗教", "complexity_tier": "T3", "furigana": "くに しゅうきょう じゆう まも", "sentence_source": "generated"}, {"text": "宗教の違いで争いが起きることもある。", "target_word": "宗教", "complexity_tier": "T3", "furigana": "しゅうきょう ちが あらそ お", "sentence_source": "generated"}, {"text": "彼は特定の宗教を信じていない。", "target_word": "宗教", "complexity_tier": "T3", "furigana": "かれ とくてい しゅうきょう しん", "sentence_source": "generated"}, {"text": "宗教は人々の生活に深く関わる。", "target_word": "宗教", "complexity_tier": "T3", "furigana": "しゅうきょう ひとびと せいかつ ふか かか", "sentence_source": "generated"}, {"text": "古い宗教の行事が今も続いている。", "target_word": "宗教", "complexity_tier": "T3", "furigana": "ふる しゅうきょう ぎょうじ いま つづ", "sentence_source": "generated"}, {"text": "宗教が違っても友達になれる。", "target_word": "宗教", "complexity_tier": "T3", "furigana": "しゅうきょう ちが ともだち", "sentence_source": "generated"}, {"text": "その祭りは宗教と関係がある。", "target_word": "宗教", "complexity_tier": "T3", "furigana": "まつ しゅうきょう かんけい", "sentence_source": "generated"}], "morphological_forms": [{"form": "宗教的", "label": "派生"}, {"form": "宗教家", "label": "派生"}, {"form": "宗教心", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 神仏を信じる教えと儀式の体系", "collocate_grounding": {"sta