INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35274, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある目的のために作られた、決まったしくみや組織のこと。", "primary_collocate": null, "pronunciation": "きかん", "ipa": "kʲikaɴ", "syllable_count": 3, "sentences": [{"text": "電車やバスは交通機関だ。", "target_word": "機関", "complexity_tier": "T3", "furigana": "でんしゃ こうつう きかん", "sentence_source": "generated"}, {"text": "大雪で交通機関が止まった。", "target_word": "機関", "complexity_tier": "T3", "furigana": "おおゆき こうつう きかん と", "sentence_source": "generated"}, {"text": "この機関は町の安全を守っている。", "target_word": "機関", "complexity_tier": "T3", "furigana": "きかん まち あんぜん まも", "sentence_source": "generated"}, {"text": "病院は大切な医療機関です。", "target_word": "機関", "complexity_tier": "T3", "furigana": "びょういん たいせつ いりょう きかん", "sentence_source": "generated"}, {"text": "国の機関に手紙を送った。", "target_word": "機関", "complexity_tier": "T3", "furigana": "くに きかん てがみ おく", "sentence_source": "generated"}, {"text": "その機関で働く人が増えている。", "target_word": "機関", "complexity_tier": "T3", "furigana": "きかん はたら ひと ふ", "sentence_source": "generated"}, {"text": "調査は専門の機関が行った。", "target_word": "機関", "complexity_tier": "T3", "furigana": "ちょうさ せんもん きかん おこな", "sentence_source": "generated"}, {"text": "市の機関に相談してみた。", "target_word": "機関", "complexity_tier": "T3", "furigana": "し きかん そうだん", "sentence_source": "generated"}, {"text": "新しい機関が作られることになった。", "target_word": "機関", "complexity_tier": "T3", "furigana": "あたら きかん つく", "sentence_source": "generated"}, {"text": "学校も教育機関の一つだ。", "target_word": "機関", "complexity_tier": "T3", "furigana": "がっこう きょういく きかん ひと", "sentence_source": "generated"}], "morphological_forms": [{"form": "機関誌", "label": "派生"}, {"form": "公共機関", "label": "派生"}, {"form": "交通機関", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 目的のための仕組みや組織", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6976cf-50fa-4cf7-bfb8-313d411504b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35275, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "特定の目的のために組織された、社会のしくみや施設。", "primary_collocate": null, "pronunciation": "きかん", "ipa": "kʲikaɴ", "syllable_count": 3, "sentences": [{"text": "銀行は金融機関の一つだ。", "target_word": "機関", "complexity_tier": "T3", "furigana": "ぎんこう きんゆう きかん ひと", "sentence_source": "generated"}, {"text": "研究機関で新しい薬を作っている。", "target_word": "機関", "complexity_tier": "T3", "furigana": "けんきゅう きかん あたら くすり つく", "sentence_source": "generated"}, {"text": "国際機関が支援を始めた。", "target_word": "機関", "complexity_tier": "T3", "furigana": "こくさい きかん しえん はじ", "sentence_source": "generated"}, {"text": "この機関は災害の時に役立つ。", "target_word": "機関", "complexity_tier": "T3", "furigana": "きかん さいがい とき やくだ", "sentence_source": "generated"}, {"text": "公的な機関に書類を出した。", "target_word": "機関", "complexity_tier": "T3", "furigana": "こうてき きかん しょるい だ", "sentence_source": "generated"}, {"text": "その機関の役割を調べた。", "target_word": "機関", "complexity_tier": "T3", "furigana": "きかん やくわり しら", "sentence_source": "generated"}, {"text": "多くの機関が協力している。", "target_word": "機関", "complexity_tier": "T3", "furigana": "おお きかん きょうりょく", "sentence_source": "generated"}, {"text": "行政機関の窓口で話を聞いた。", "target_word": "機関", "complexity_tier": "T3", "furigana": "ぎょうせい きかん まどぐち はなし き", "sentence_source": "generated"}, {"text": "機関の代表が会見をした。", "target_word": "機関", "complexity_tier": "T3", "furigana": "きかん だいひょう かいけん", "sentence_source": "generated"}, {"text": "姉は政府の機関で働いている。", "target_word": "機関", "complexity_tier": "T3", "furigana": "あね せいふ きかん はたら", "sentence_source": "generated"}], "morphological_forms": [{"form": "行政機関", "label": "派生"}, {"form": "金融機関", "label": "派生"}, {"form": "研究機関", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 社会の目的別の組織・施設", "collocate_grounding": {"status": "no_source", "reaso