INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35273, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "宗教", "is_correct": true, "explanation": "正解：「宗教」（しゅうきょう）。"}, {"text": "終業", "is_correct": false, "explanation": "「終業」は「しゅうぎょう」と読み、「きょ」が濁って「ぎょ」になる清濁の違い。"}, {"text": "就航", "is_correct": false, "explanation": "「就航」は「しゅうこう」と読み、三拍目「きょ」が「こ」になる一モーラの違い。"}, {"text": "終局", "is_correct": false, "explanation": "「終局」は「しゅうきょく」と読み、最後の長音「う」が「く」になる一モーラの違い。"}], "explanations": {"宗教": "正解：「宗教」（しゅうきょう）。", "終業": "「終業」は「しゅうぎょう」と読み、「きょ」が濁って「ぎょ」になる清濁の違い。", "就航": "「就航」は「しゅうこう」と読み、三拍目「きょ」が「こ」になる一モーラの違い。", "終局": "「終局」は「しゅうきょく」と読み、最後の長音「う」が「く」になる一モーラの違い。"}, "sentence_index": null, "correct_answer": "宗教"}, "level_3": {"options": [{"text": "宗教", "is_correct": true, "explanation": "文の意味に合う。"}, {"text": "太陽", "is_correct": false, "explanation": "意味：世界に太陽はたくさんない。"}, {"text": "地球", "is_correct": false, "explanation": "意味：地球は一つしかない。"}, {"text": "人口", "is_correct": false, "explanation": "連語：「たくさんの人口がある」とは言わない。"}], "explanations": {"宗教": "文の意味に合う。", "太陽": "意味：世界に太陽はたくさんない。", "地球": "意味：地球は一つしかない。", "人口": "連語：「たくさんの人口がある」とは言わない。"}, "sentence_index": 0, "correct_answer": "宗教"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "宗教を三冊信じている。", "explanation": "助数詞の誤り：宗教は「冊」で数えない。"}, {"text": "この国では宗教に自由が守られている。", "explanation": "助詞の混同：「宗教の自由」とすべき。"}, {"text": "この国では宗教の自由が昨日守っている。", "explanation": "活用・アスペクトの誤り：時の語と「守っている」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c93add-e333-4ade-8896-6abbe00979bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_ba