INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35275, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "活動の場所を示す「で」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「薬を」と目的語が二つになり非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、作る場所には使えない。"}, {"text": "まで", "is_correct": false, "explanation": "範囲の終点を表し、この文では非文。"}], "correct_answer": "で", "explanations": {"で": "活動の場所を示す「で」が正しい。", "を": "「薬を」と目的語が二つになり非文。", "へ": "方向を表し、作る場所には使えない。", "まで": "範囲の終点を表し、この文では非文。"}, "error_tags": {"を": "object_marking", "へ": "direction", "まで": "source_vs_goal"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c93add-e333-4ade-8896-6abbe00979bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
