INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35280, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "記す", "is_correct": true, "explanation": "正解：「記す」（しるす）。"}, {"text": "印", "is_correct": false, "explanation": "「印」は「しるし」と読み、最後の「す」が「し」になる一モーラの違い。"}, {"text": "知らす", "is_correct": false, "explanation": "「知らす」は「しらす」と読み、二拍目「る」が「ら」になる一モーラの違い。"}, {"text": "汁粉", "is_correct": false, "explanation": "「汁粉」は「しるこ」と読み、最後の「す」が「こ」になる一モーラの違い。"}], "explanations": {"記す": "正解：「記す」（しるす）。", "印": "「印」は「しるし」と読み、最後の「す」が「し」になる一モーラの違い。", "知らす": "「知らす」は「しらす」と読み、二拍目「る」が「ら」になる一モーラの違い。", "汁粉": "「汁粉」は「しるこ」と読み、最後の「す」が「こ」になる一モーラの違い。"}, "sentence_index": null, "correct_answer": "記す"}, "level_3": {"options": [{"text": "記す", "is_correct": true, "explanation": "文の意味に合う。"}, {"text": "食べる", "is_correct": false, "explanation": "項構造：名前は食べられない。"}, {"text": "走る", "is_correct": false, "explanation": "項構造：「名前を走る」は成り立たない。"}, {"text": "泳ぐ", "is_correct": false, "explanation": "項構造：「ノートに名前を泳ぐ」は成り立たない。"}], "explanations": {"記す": "文の意味に合う。", "食べる": "項構造：名前は食べられない。", "走る": "項構造：「名前を走る」は成り立たない。", "泳ぐ": "項構造：「ノートに名前を泳ぐ」は成り立たない。"}, "sentence_index": 0, "correct_answer": "記す"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は旅の思い出を本が記した。", "explanation": "助詞の混同：場所は「本に」とすべき。"}, {"text": "彼は旅の思い出を本に記している昨日。", "explanation": "活用・語順の誤り：時の語の位置とアスペクトが合わない。"}, {"text": "彼は旅の思い出を三匹本に記した。", "explanation": "助数詞の誤り：思い出は「匹」で数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c93add-e333-4ade-8896-6abbe00979bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
