INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35280, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "記す", "is_correct": true, "explanation": "正解：「記す」（しるす）。"}, {"text": "汁気", "is_correct": false, "explanation": "「汁気」は「しるけ」と読み、最後の「す」が「け」になる一モーラの違い。"}, {"text": "白洲", "is_correct": false, "explanation": "「白洲」は「しらす」と読み、二拍目「る」が「ら」になる一モーラの違い。"}, {"text": "印", "is_correct": false, "explanation": "「印」は「しるし」と読み、最後の「す」が「し」になる一モーラの違い。"}], "explanations": {"記す": "正解：「記す」（しるす）。", "汁気": "「汁気」は「しるけ」と読み、最後の「す」が「け」になる一モーラの違い。", "白洲": "「白洲」は「しらす」と読み、二拍目「る」が「ら」になる一モーラの違い。", "印": "「印」は「しるし」と読み、最後の「す」が「し」になる一モーラの違い。"}, "sentence_index": null, "correct_answer": "記す"}, "level_3": {"options": [{"text": "記して", "is_correct": true, "explanation": "文の意味に合う。"}, {"text": "泣いて", "is_correct": false, "explanation": "項構造：「日付を泣く」は成り立たない。"}, {"text": "眠って", "is_correct": false, "explanation": "項構造：「日付を眠る」は成り立たない。"}, {"text": "歩いて", "is_correct": false, "explanation": "意味：黒板に日付を歩くことはできない。"}], "explanations": {"記して": "文の意味に合う。", "泣いて": "項構造：「日付を泣く」は成り立たない。", "眠って": "項構造：「日付を眠る」は成り立たない。", "歩いて": "意味：黒板に日付を歩くことはできない。"}, "sentence_index": 6, "correct_answer": "記して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "石を記した言葉が残っている。", "explanation": "助詞の混同：書いた場所は「石に」とすべき。"}, {"text": "石に記した言葉が二匹残っている。", "explanation": "助数詞の誤り：言葉は「匹」で数えない。"}, {"text": "石に記す言葉が昔から残っている。", "explanation": "活用の誤り：昔に書いたので「記した」とすべき。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c93add-e333-4ade-8896-6abbe00979bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
