INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35281, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "文字や記号を使って書き残す。記録する。", "primary_collocate": null, "pronunciation": "しるす", "ipa": "ɕiɾɯsɯ", "syllable_count": 3, "sentences": [{"text": "ノートに名前を記す。", "target_word": "記す", "complexity_tier": "T3", "furigana": "しるす", "sentence_source": "generated"}, {"text": "日記に今日の出来事を記した。", "target_word": "記した", "complexity_tier": "T3", "furigana": "にっき きょう できごと しるした", "sentence_source": "generated"}, {"text": "住所をここに記してください。", "target_word": "記して", "complexity_tier": "T3", "furigana": "じゅうしょ しるして", "sentence_source": "generated"}, {"text": "彼は旅の思い出を本に記した。", "target_word": "記した", "complexity_tier": "T3", "furigana": "かれ たび おも で ほん しるした", "sentence_source": "generated"}, {"text": "答えを紙に記すのを忘れた。", "target_word": "記す", "complexity_tier": "T3", "furigana": "こた かみ しるす わす", "sentence_source": "generated"}, {"text": "先生は黒板に日付を記した。", "target_word": "記した", "complexity_tier": "T3", "furigana": "せんせい こくばん ひづけ しるした", "sentence_source": "generated"}, {"text": "手帳に予定を記しておく。", "target_word": "記して", "complexity_tier": "T3", "furigana": "てちょう よてい しるして", "sentence_source": "generated"}, {"text": "記された日付を確かめた。", "target_word": "記された", "complexity_tier": "T3", "furigana": "しるされた ひづけ たし", "sentence_source": "generated"}, {"text": "石に古い文字が記されている。", "target_word": "記されて", "complexity_tier": "T3", "furigana": "いし ふる もじ しるされて", "sentence_source": "generated"}, {"text": "その気持ちは手紙に記せない。", "target_word": "記せ", "complexity_tier": "T3", "furigana": "きも てがみ しるせ", "sentence_source": "generated"}], "morphological_forms": [{"form": "記した", "label": "活用"}, {"form": "記して", "label": "活用"}, {"form": "記さない", "label": "活用"}, {"form": "記される", "label": "活用"}], "register": "formal", "sense_fingerprint": "動詞 | 文字で書き残して記録する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c341142c-eecb-4033-81ab-7be3658e1e2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35858, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の、変わらない大切な中身。", "primary_collocate": null, "pronunciation": "ほんしつ", "ipa": "hoɴɕitsɯ", "syllable_count": 4, "sentences": [{"text": "問題の本質を考える。", "target_word": "本質", "complexity_tier": "T3", "furigana": "もんだい ほんしつ かんが", "sentence_source": "generated"}, {"text": "本質が見えていない。", "target_word": "本質", "complexity_tier": "T3", "furigana": "ほんしつ み", "sentence_source": "generated"}, {"text": "それは友情の本質だと思う。", "target_word": "本質", "complexity_tier": "T3", "furigana": "ゆうじょう ほんしつ おも", "sentence_source": "generated"}, {"text": "彼は話の本質をつかんだ。", "target_word": "本質", "complexity_tier": "T3", "furigana": "かれ はなし ほんしつ", "sentence_source": "generated"}, {"text": "本質はいつも変わらない。", "target_word": "本質", "complexity_tier": "T3", "furigana": "ほんしつ か", "sentence_source": "generated"}, {"text": "見た目より本質が大切だ。", "target_word": "本質", "complexity_tier": "T3", "furigana": "み め ほんしつ たいせつ", "sentence_source": "generated"}, {"text": "この二つは本質的に同じだ。", "target_word": "本質", "complexity_tier": "T3", "furigana": "ふた ほんしつてき おな", "sentence_source": "generated"}, {"text": "勉強の本質について話した。", "target_word": "本質", "complexity_tier": "T3", "furigana": "べんきょう ほんしつ はな", "sentence_source": "generated"}, {"text": "本質から目をそらすな。", "target_word": "本質", "complexity_tier": "T3", "furigana": "ほんしつ め", "sentence_source": "generated"}, {"text": "先生は本質的な質問をした。", "target_word": "本質", "complexity_tier": "T3", "furigana": "せんせい ほんしつてき しつもん", "sentence_source": "generated"}], "morphological_forms": [{"form": "本質的", "label": "派生"}, {"form": "本質的に", "label": "派生"}, {"form": "本質論", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事の根本的で大切な中身", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code