INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35284, 3, 'prompt1_core', '{"pos": "接尾辞", "semantic_class": "function", "definition": "月の数を数えるときに使う言葉。「三箇月」は月が三つ分。", "primary_collocate": null, "pronunciation": "かげつ", "ipa": "kaɡetsɯ", "syllable_count": 3, "sentences": [{"text": "三箇月で日本語を学んだ。", "target_word": "箇月", "complexity_tier": "T3", "furigana": "さん かげつ にほんご まな", "sentence_source": "generated"}, {"text": "工事は六箇月かかる。", "target_word": "箇月", "complexity_tier": "T3", "furigana": "ろっ かげつ こうじ", "sentence_source": "generated"}, {"text": "一箇月に一度会う。", "target_word": "箇月", "complexity_tier": "T3", "furigana": "いっ かげつ いちど あ", "sentence_source": "generated"}, {"text": "二箇月ぶりに雨が降った。", "target_word": "箇月", "complexity_tier": "T3", "furigana": "に かげつ あめ ふ", "sentence_source": "generated"}, {"text": "あと数箇月で卒業だ。", "target_word": "箇月", "complexity_tier": "T3", "furigana": "すう かげつ そつぎょう", "sentence_source": "generated"}, {"text": "五箇月前に引っ越した。", "target_word": "箇月", "complexity_tier": "T3", "furigana": "ご かげつ まえ ひ こ", "sentence_source": "generated"}, {"text": "この仕事は三箇月の予定だ。", "target_word": "箇月", "complexity_tier": "T3", "furigana": "さん かげつ しごと よてい", "sentence_source": "generated"}, {"text": "十箇月かけて本を書いた。", "target_word": "箇月", "complexity_tier": "T3", "furigana": "じゅっ かげつ ほん か", "sentence_source": "generated"}, {"text": "四箇月の間、毎日練習した。", "target_word": "箇月", "complexity_tier": "T3", "furigana": "よん かげつ あいだ まいにち れんしゅう", "sentence_source": "generated"}, {"text": "九箇月後に家が完成する。", "target_word": "箇月", "complexity_tier": "T3", "furigana": "きゅう かげつ ご いえ かんせい", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "接尾辞 | 月の数を数える語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c341142c-eecb-4033-81ab-7be3658e1e2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35281, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "記す", "is_correct": true, "explanation": "正解。「しるす」と読む。"}, {"text": "印", "is_correct": false, "explanation": "「しるし」。三拍目の「す」が「し」に変わる一モーラ差。"}, {"text": "汁粉", "is_correct": false, "explanation": "「しるこ」。三拍目の「す」が「こ」に変わる一モーラ差。"}, {"text": "しるべ", "is_correct": false, "explanation": "「しるべ」（道案内）。三拍目の「す」が「べ」に変わる一モーラ差。"}], "explanations": {"記す": "正解。「しるす」と読む。", "印": "「しるし」。三拍目の「す」が「し」に変わる一モーラ差。", "汁粉": "「しるこ」。三拍目の「す」が「こ」に変わる一モーラ差。", "しるべ": "「しるべ」（道案内）。三拍目の「す」が「べ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "記す"}, "level_3": {"options": [{"text": "記す", "is_correct": true, "explanation": "名前を文字で書き残す意味で自然。"}, {"text": "飲む", "is_correct": false, "explanation": "意味：名前は飲むものではない。"}, {"text": "走る", "is_correct": false, "explanation": "項構造：自動詞で「名前を」を取れない。"}, {"text": "眠る", "is_correct": false, "explanation": "項構造：自動詞で目的語を取らない。"}], "explanations": {"記す": "名前を文字で書き残す意味で自然。", "飲む": "意味：名前は飲むものではない。", "走る": "項構造：自動詞で「名前を」を取れない。", "眠る": "項構造：自動詞で目的語を取らない。"}, "sentence_index": 0, "correct_answer": "記す"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は旅の思い出が本に記した。", "explanation": "助詞の混同：目的語は「を」で示す。"}, {"text": "彼は明日旅の思い出を本に記した。", "explanation": "語順・時制の誤り：「明日」と過去形が合わない。"}, {"text": "彼は旅の思い出を本に記すした。", "explanation": "活用の誤り：過去形は「記した」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd08fda9f-3577-48ad-9bcd-e11daf3b78e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35281, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ノートに名前が記す。", "corrected_sentence": "ノートに名前を記す。", "error_description": "助詞の混同：目的語「名前」は「を」で示す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "記した", "is_correct": true, "explanation": "「今日の出来事」を書き終えたことを表すた形。"}, {"text": "記して", "is_correct": false, "explanation": "て形は後に続く要素が必要で、文が終わらない。"}, {"text": "記される", "is_correct": false, "explanation": "受身形は「を」と合わず、文の構造が崩れる。"}, {"text": "記させて", "is_correct": false, "explanation": "使役のて形で、させる相手もなく文が終わらない。"}], "correct_form": "記した", "base_form": "記す", "form_label": "活用", "sentence_index": 1, "explanations": {"記した": "「今日の出来事」を書き終えたことを表すた形。", "記して": "て形は後に続く要素が必要で、文が終わらない。", "記される": "受身形は「を」と合わず、文の構造が崩れる。", "記させて": "使役のて形で、させる相手もなく文が終わらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd08fda9f-3577-48ad-9bcd-e11daf3b78e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35281, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「記した」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "主格を示し、他動詞の目的語にならない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を表し、出来事には合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、書く内容には使えない。"}], "correct_answer": "を", "explanations": {"を": "「記した」の目的語を示す。", "が": "主格を示し、他動詞の目的語にならない。", "で": "手段・場所を表し、出来事には合わない。", "へ": "方向を表し、書く内容には使えない。"}, "error_tags": {"が": "object_marking", "で": "instrument", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "消す", "is_correct": true, "explanation": "書いたものをなくす意味で、記すの反対。"}, {"text": "書く", "is_correct": false, "explanation": "類義語で対義語ではない。"}, {"text": "読む", "is_correct": false, "explanation": "書かれたものを読む行為で、反対の意味ではない。"}, {"text": "写す", "is_correct": false, "explanation": "書き写す意味で、記すに近い。"}], "correct_answer": "消す", "explanations": {"消す": "書いたものをなくす意味で、記すの反対。", "書く": "類義語で対義語ではない。", "読む": "書かれたものを読む行為で、反対の意味ではない。", "写す": "書き写す意味で、記すに近い。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd08fda9f-3577-48ad-9bcd-e11daf3b78e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35281, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "記す", "is_correct": true, "explanation": "正解。読みは「しるす」。"}, {"text": "揺する", "is_correct": false, "explanation": "「ゆする」：一拍目「し」→「ゆ」。"}, {"text": "示す", "is_correct": false, "explanation": "「しめす」：二拍目「る」→「め」。"}, {"text": "汁", "is_correct": false, "explanation": "「しる」：最後の拍「す」が落ちる。"}], "explanations": {"記す": "正解。読みは「しるす」。", "揺する": "「ゆする」：一拍目「し」→「ゆ」。", "示す": "「しめす」：二拍目「る」→「め」。", "汁": "「しる」：最後の拍「す」が落ちる。"}, "sentence_index": null, "correct_answer": "記す"}, "level_3": {"options": [{"text": "記して", "is_correct": true, "explanation": "手帳に予定を書いておく意味で自然。"}, {"text": "泳いで", "is_correct": false, "explanation": "意味：手帳に予定を泳ぐことはできない。"}, {"text": "座って", "is_correct": false, "explanation": "項構造：自動詞で「予定を」を取れない。"}, {"text": "食べて", "is_correct": false, "explanation": "意味：予定は食べるものではない。"}], "explanations": {"記して": "手帳に予定を書いておく意味で自然。", "泳いで": "意味：手帳に予定を泳ぐことはできない。", "座って": "項構造：自動詞で「予定を」を取れない。", "食べて": "意味：予定は食べるものではない。"}, "sentence_index": 6, "correct_answer": "記して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その気持ちが手紙を記せない。", "explanation": "助詞の混同：「手紙に」を「手紙を」にし、主語も崩れている。"}, {"text": "その気持ちは手紙に記せなかった明日。", "explanation": "語順・時制の誤り：「明日」と過去形が衝突する。"}, {"text": "その気持ちは手紙に記しせない。", "explanation": "活用の誤り：可能の否定は「記せない」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd08fda9f-3577-48ad-9bcd-e11daf3b78e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35281, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は日付が黒板に記した。", "corrected_sentence": "先生は黒板に日付を記した。", "error_description": "助詞の混同：目的語「日付」は「を」で示す。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "記された", "is_correct": true, "explanation": "「日付」を修飾する受身のた形で自然。"}, {"text": "記して", "is_correct": false, "explanation": "て形は名詞を修飾できない。"}, {"text": "記そう", "is_correct": false, "explanation": "意向形は名詞の前に置けない。"}, {"text": "記せ", "is_correct": false, "explanation": "命令形は名詞を修飾できない。"}], "correct_form": "記された", "base_form": "記す", "form_label": "活用", "sentence_index": 7, "explanations": {"記された": "「日付」を修飾する受身のた形で自然。", "記して": "て形は名詞を修飾できない。", "記そう": "意向形は名詞の前に置けない。", "記せ": "命令形は名詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd08fda9f-3577-48ad-9bcd-e11daf3b78e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35281, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "書き込む先「ノート」を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」が二つ重なり非文になる。"}, {"text": "が", "is_correct": false, "explanation": "主格になり、ノートが書く主体になってしまう。"}, {"text": "より", "is_correct": false, "explanation": "比較を表し、この文では意味をなさない。"}], "correct_answer": "に", "explanations": {"に": "書き込む先「ノート」を示す。", "を": "目的語の「を」が二つ重なり非文になる。", "が": "主格になり、ノートが書く主体になってしまう。", "より": "比較を表し、この文では意味をなさない。"}, "error_tags": {"を": "object_marking", "が": "topic_vs_subject", "より": "other"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd08fda9f-3577-48ad-9bcd-e11daf3b78e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35858, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "本質", "is_correct": true, "explanation": "正解。「ほんしつ」と読む。"}, {"text": "本日", "is_correct": false, "explanation": "「ほんじつ」。三拍目「し」と「じ」の清濁の対立。"}, {"text": "温室", "is_correct": false, "explanation": "「おんしつ」。一拍目「ほ」が「お」に変わる一モーラ差。"}, {"text": "本式", "is_correct": false, "explanation": "「ほんしき」。四拍目「つ」が「き」に変わる一モーラ差。"}], "explanations": {"本質": "正解。「ほんしつ」と読む。", "本日": "「ほんじつ」。三拍目「し」と「じ」の清濁の対立。", "温室": "「おんしつ」。一拍目「ほ」が「お」に変わる一モーラ差。", "本式": "「ほんしき」。四拍目「つ」が「き」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "本質"}, "level_3": {"options": [{"text": "本質", "is_correct": true, "explanation": "問題の大切な中身を考える意味で自然。"}, {"text": "天気", "is_correct": false, "explanation": "意味：「問題の天気」は意味をなさない。"}, {"text": "牛乳", "is_correct": false, "explanation": "意味：問題に牛乳はない。"}, {"text": "机", "is_correct": false, "explanation": "連語：「問題の机を考える」は不自然。"}], "explanations": {"本質": "問題の大切な中身を考える意味で自然。", "天気": "意味：「問題の天気」は意味をなさない。", "牛乳": "意味：問題に牛乳はない。", "机": "連語：「問題の机を考える」は不自然。"}, "sentence_index": 0, "correct_answer": "本質"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は話を本質をつかんだ。", "explanation": "助詞の混同：「話の」を「話を」にしている。"}, {"text": "彼は話の本質がつかんだ。", "explanation": "助詞の混同：他動詞の目的語に「が」を使っている。"}, {"text": "彼は明日話の本質をつかんだ。", "explanation": "時制の誤り：「明日」と過去形が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd08fda9f-3577-48ad-9bcd-e11daf3b78e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
