INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35858, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "自動詞「見える」の対象を示す。"}, {"text": "を", "is_correct": false, "explanation": "「見える」は自動詞で「を」を取らない。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段を表し、ここでは非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、意味をなさない。"}], "correct_answer": "が", "explanations": {"が": "自動詞「見える」の対象を示す。", "を": "「見える」は自動詞で「を」を取らない。", "で": "場所・手段を表し、ここでは非文。", "へ": "方向を表し、意味をなさない。"}, "error_tags": {"を": "object_marking", "で": "instrument", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "表面", "is_correct": true, "explanation": "物事の外側だけの部分で、本質の反対。"}, {"text": "中心", "is_correct": false, "explanation": "大切な部分を指し、本質に近い。"}, {"text": "核心", "is_correct": false, "explanation": "類義語で対義語ではない。"}, {"text": "価値", "is_correct": false, "explanation": "関連はあるが反対の意味ではない。"}], "correct_answer": "表面", "explanations": {"表面": "物事の外側だけの部分で、本質の反対。", "中心": "大切な部分を指し、本質に近い。", "核心": "類義語で対義語ではない。", "価値": "関連はあるが反対の意味ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd08fda9f-3577-48ad-9bcd-e11daf3b78e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35858, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "本質", "is_correct": true, "explanation": "正解。読みは「ほんしつ」。"}, {"text": "品質", "is_correct": false, "explanation": "「ひんしつ」：一拍目「ほ」→「ひ」。"}, {"text": "紛失", "is_correct": false, "explanation": "「ふんしつ」：一拍目「ほ」→「ふ」。"}, {"text": "本誌", "is_correct": false, "explanation": "「ほんし」：最後の拍「つ」が落ちる。"}], "explanations": {"本質": "正解。読みは「ほんしつ」。", "品質": "「ひんしつ」：一拍目「ほ」→「ひ」。", "紛失": "「ふんしつ」：一拍目「ほ」→「ふ」。", "本誌": "「ほんし」：最後の拍「つ」が落ちる。"}, "sentence_index": null, "correct_answer": "本質"}, "level_3": {"options": [{"text": "本質", "is_correct": true, "explanation": "「本質的に」で、根本では同じという意味。"}, {"text": "雨", "is_correct": false, "explanation": "意味：「雨的」という語はない。"}, {"text": "犬", "is_correct": false, "explanation": "意味：「犬的に同じ」は意味をなさない。"}, {"text": "机", "is_correct": false, "explanation": "連語：「机的」とは言わない。"}], "explanations": {"本質": "「本質的に」で、根本では同じという意味。", "雨": "意味：「雨的」という語はない。", "犬": "意味：「犬的に同じ」は意味をなさない。", "机": "連語：「机的」とは言わない。"}, "sentence_index": 6, "correct_answer": "本質"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は本質的に質問をした。", "explanation": "活用の誤り：名詞を修飾するのは「本質的な」。"}, {"text": "先生が本質的な質問にした。", "explanation": "助詞の混同：「質問を」を「質問に」にしている。"}, {"text": "先生は本質的だ質問をした。", "explanation": "活用の誤り：名詞を修飾するのは「本質的な」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd08fda9f-3577-48ad-9bcd-e11daf3b78e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
