INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35860, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "内包", "is_correct": true, "explanation": "正解。「ないほう」と読む。"}, {"text": "内容", "is_correct": false, "explanation": "「ないよう」。三拍目「ほ」が「よ」に変わる一モーラ差。"}, {"text": "解放", "is_correct": false, "explanation": "「かいほう」。一拍目「な」が「か」に変わる一モーラ差。"}, {"text": "大砲", "is_correct": false, "explanation": "「たいほう」。一拍目「な」が「た」に変わる一モーラ差。"}, {"text": "内向", "is_correct": false, "explanation": "「ないこう」。三拍目「ほ」が「こ」に変わる一モーラ差。"}], "explanations": {"内包": "正解。「ないほう」と読む。", "内容": "「ないよう」。三拍目「ほ」が「よ」に変わる一モーラ差。", "解放": "「かいほう」。一拍目「な」が「か」に変わる一モーラ差。", "大砲": "「たいほう」。一拍目「な」が「た」に変わる一モーラ差。", "内向": "「ないこう」。三拍目「ほ」が「こ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "内包"}, "level_3": {"options": [{"text": "内包", "is_correct": true, "explanation": "計画が危険を中に含む意味で自然。"}, {"text": "散歩", "is_correct": false, "explanation": "意味：計画が危険を散歩することはない。"}, {"text": "料理", "is_correct": false, "explanation": "意味：危険を料理するのは不自然。"}, {"text": "運動", "is_correct": false, "explanation": "項構造：「危険を運動する」とは言えない。"}], "explanations": {"内包": "計画が危険を中に含む意味で自然。", "散歩": "意味：計画が危険を散歩することはない。", "料理": "意味：危険を料理するのは不自然。", "運動": "項構造：「危険を運動する」とは言えない。"}, "sentence_index": 0, "correct_answer": "内包"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "町が多くの課題に内包している。", "explanation": "助詞の混同：含むものは「を」で示す。"}, {"text": "町は多くの課題を内包していた明日。", "explanation": "時制・語順の誤り：「明日」と過去形が衝突。"}, {"text": "町は多くの課題を内包してある。", "explanation": "アスペクトの誤り：「てある」ではなく「ている」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd08fda9f-3577-48ad-9bcd-e11daf3b78e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
