INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35282, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "高価", "is_correct": true, "explanation": "正解。「こうか」と読む。"}, {"text": "交差", "is_correct": false, "explanation": "「こうさ」。三拍目「か」が「さ」に変わる一モーラ差。"}, {"text": "講座", "is_correct": false, "explanation": "「こうざ」。三拍目「か」が「ざ」に変わる一モーラ差。"}, {"text": "好機", "is_correct": false, "explanation": "「こうき」。三拍目「か」が「き」に変わる一モーラ差。"}, {"text": "講師", "is_correct": false, "explanation": "「こうし」。三拍目「か」が「し」に変わる一モーラ差。"}], "explanations": {"高価": "正解。「こうか」と読む。", "交差": "「こうさ」。三拍目「か」が「さ」に変わる一モーラ差。", "講座": "「こうざ」。三拍目「か」が「ざ」に変わる一モーラ差。", "好機": "「こうき」。三拍目「か」が「き」に変わる一モーラ差。", "講師": "「こうし」。三拍目「か」が「し」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "高価"}, "level_3": {"options": [{"text": "高価", "is_correct": true, "explanation": "値段が高い時計という意味で自然。"}, {"text": "上手", "is_correct": false, "explanation": "意味：時計の値段を表さず、「上手な時計」とは言わない。"}, {"text": "元気", "is_correct": false, "explanation": "意味：時計は元気にならない。"}, {"text": "親切", "is_correct": false, "explanation": "意味：人の性質で、物には使わない。"}], "explanations": {"高価": "値段が高い時計という意味で自然。", "上手": "意味：時計の値段を表さず、「上手な時計」とは言わない。", "元気": "意味：時計は元気にならない。", "親切": "意味：人の性質で、物には使わない。"}, "sentence_index": 0, "correct_answer": "高価"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この絵は高価を有名だ。", "explanation": "助詞の混同：「高価で」を「高価を」にしている。"}, {"text": "この絵は高価な有名だ。", "explanation": "活用の誤り：理由をつなぐのは「高価で」。"}, {"text": "この絵は有名だ高価で。", "explanation": "語順の誤り：理由が文末に来て不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd08fda9f-3577-48ad-9bcd-e11daf3b78e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35282, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "これは高価の時計だ。", "corrected_sentence": "これは高価な時計だ。", "error_description": "活用の誤り：形状詞が名詞を修飾するときは「な」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "高価", "is_correct": true, "explanation": "後ろの「だ」と合わせて「高価だ」となり自然。"}, {"text": "高価な", "is_correct": false, "explanation": "「高価なだ」となり、連体形は「だ」に続かない。"}, {"text": "高価に", "is_correct": false, "explanation": "「高価にだ」となり、連用形は「だ」に続かない。"}, {"text": "高価で", "is_correct": false, "explanation": "「高価でだ」となり非文。"}], "correct_form": "高価", "base_form": "高価", "form_label": "活用", "sentence_index": 1, "explanations": {"高価": "後ろの「だ」と合わせて「高価だ」となり自然。", "高価な": "「高価なだ」となり、連体形は「だ」に続かない。", "高価に": "「高価にだ」となり、連用形は「だ」に続かない。", "高価で": "「高価でだ」となり非文。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd08fda9f-3577-48ad-9bcd-e11daf3b78e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
