INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35284, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "箇月", "is_correct": true, "explanation": "正解。「かげつ」と読む。"}, {"text": "可決", "is_correct": false, "explanation": "「かけつ」。二拍目「げ」と「け」の清濁の対立。"}, {"text": "過激", "is_correct": false, "explanation": "「かげき」。三拍目「つ」が「き」に変わる一モーラ差。"}, {"text": "加減", "is_correct": false, "explanation": "「かげん」。三拍目「つ」が「ん」に変わる一モーラ差。"}], "explanations": {"箇月": "正解。「かげつ」と読む。", "可決": "「かけつ」。二拍目「げ」と「け」の清濁の対立。", "過激": "「かげき」。三拍目「つ」が「き」に変わる一モーラ差。", "加減": "「かげん」。三拍目「つ」が「ん」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "箇月"}, "level_3": {"options": [{"text": "箇月", "is_correct": true, "explanation": "月の数を数える語で、期間を表す。"}, {"text": "羽", "is_correct": false, "explanation": "意味：鳥などを数える語で、期間を表さない。"}, {"text": "匹", "is_correct": false, "explanation": "意味：動物を数える語。"}, {"text": "頭", "is_correct": false, "explanation": "意味：大きな動物を数える語。"}], "explanations": {"箇月": "月の数を数える語で、期間を表す。", "羽": "意味：鳥などを数える語で、期間を表さない。", "匹": "意味：動物を数える語。", "頭": "意味：大きな動物を数える語。"}, "sentence_index": 0, "correct_answer": "箇月"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二箇月ぶりを雨が降った。", "explanation": "助詞の混同：「ぶりに」を「ぶりを」にしている。"}, {"text": "二箇月ぶりに雨を降った。", "explanation": "助詞の混同：自動詞「降る」に「を」は使わない。"}, {"text": "二箇月ぶりに雨が降れた。", "explanation": "活用の誤り：過去形は「降った」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd08fda9f-3577-48ad-9bcd-e11daf3b78e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
