INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35285, 3, 'prompt1_core', '{"pos": "接尾辞", "semantic_class": "function", "definition": "「かげつ」と読み、月の数を数えるときに使う言葉。「三箇月」のように使う。", "primary_collocate": null, "pronunciation": "かげつ", "ipa": "kaɡetsɯ", "syllable_count": 3, "sentences": [{"text": "日本に来て三箇月がたった。", "target_word": "箇月", "complexity_tier": "T3", "furigana": "にほん き さんかげつ", "sentence_source": "generated"}, {"text": "この仕事は二箇月で終わる。", "target_word": "箇月", "complexity_tier": "T3", "furigana": "しごと にかげつ お", "sentence_source": "generated"}, {"text": "一箇月に一度、祖母に会う。", "target_word": "箇月", "complexity_tier": "T3", "furigana": "いっかげつ いちど そぼ あ", "sentence_source": "generated"}, {"text": "あと六箇月で卒業です。", "target_word": "箇月", "complexity_tier": "T3", "furigana": "ろっかげつ そつぎょう", "sentence_source": "generated"}, {"text": "ピアノを習って五箇月になる。", "target_word": "箇月", "complexity_tier": "T3", "furigana": "なら ごかげつ", "sentence_source": "generated"}, {"text": "数箇月前から犬を飼っている。", "target_word": "箇月", "complexity_tier": "T3", "furigana": "すうかげつまえ いぬ か", "sentence_source": "generated"}, {"text": "三箇月の旅行はとても楽しかった。", "target_word": "箇月", "complexity_tier": "T3", "furigana": "さんかげつ りょこう たの", "sentence_source": "generated"}, {"text": "彼は四箇月も学校を休んだ。", "target_word": "箇月", "complexity_tier": "T3", "furigana": "かれ よんかげつ がっこう やす", "sentence_source": "generated"}, {"text": "工事には八箇月かかるそうだ。", "target_word": "箇月", "complexity_tier": "T3", "furigana": "こうじ はっかげつ", "sentence_source": "generated"}, {"text": "一箇月分の食料を買った。", "target_word": "箇月", "complexity_tier": "T3", "furigana": "いっかげつぶん しょくりょう か", "sentence_source": "generated"}], "morphological_forms": [{"form": "一箇月", "label": "派生"}, {"form": "数箇月", "label": "派生"}, {"form": "箇月間", "label": "派生"}], "register": "formal", "sense_fingerprint": "接尾辞 | 月の数を数える単位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be22e797-4d71-4103-911b-be92e66202ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
