INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35289, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "図書館や博物館などが、本や作品を集めて保管していること。また、そのもの。", "primary_collocate": null, "pronunciation": "しょぞう", "ipa": "ɕoːzoː", "syllable_count": 3, "sentences": [{"text": "博物館の所蔵を見に行った。", "target_word": "所蔵", "complexity_tier": "T3", "furigana": "はくぶつかん しょぞう み い", "sentence_source": "generated"}, {"text": "この絵は美術館の所蔵だ。", "target_word": "所蔵", "complexity_tier": "T3", "furigana": "え びじゅつかん しょぞう", "sentence_source": "generated"}, {"text": "美術館が有名な絵を所蔵する。", "target_word": "所蔵", "complexity_tier": "T3", "furigana": "びじゅつかん ゆうめい え しょぞう", "sentence_source": "generated"}, {"text": "所蔵の作品を特別に公開する。", "target_word": "所蔵", "complexity_tier": "T3", "furigana": "しょぞう さくひん とくべつ こうかい", "sentence_source": "generated"}, {"text": "博物館は古い刀を所蔵している。", "target_word": "所蔵", "complexity_tier": "T3", "furigana": "はくぶつかん ふる かたな しょぞう", "sentence_source": "generated"}, {"text": "所蔵作品の数は一万点だ。", "target_word": "所蔵", "complexity_tier": "T3", "furigana": "しょぞう さくひん かず いちまんてん", "sentence_source": "generated"}, {"text": "その像は寺の所蔵になった。", "target_word": "所蔵", "complexity_tier": "T3", "furigana": "ぞう てら しょぞう", "sentence_source": "generated"}, {"text": "所蔵されている絵を調べた。", "target_word": "所蔵", "complexity_tier": "T3", "furigana": "しょぞう え しら", "sentence_source": "generated"}, {"text": "この館の所蔵はとても多い。", "target_word": "所蔵", "complexity_tier": "T3", "furigana": "かん しょぞう おお", "sentence_source": "generated"}, {"text": "所蔵の品を大切に守っている。", "target_word": "所蔵", "complexity_tier": "T3", "furigana": "しょぞう しな たいせつ まも", "sentence_source": "generated"}], "morphological_forms": [{"form": "所蔵する", "label": "派生"}, {"form": "所蔵品", "label": "派生"}, {"form": "所蔵庫", "label": "派生"}, {"form": "所蔵作品", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 作品を集めて保管すること・その品", "collocate_g