INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35285, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "箇月", "is_correct": true, "explanation": "正解。「かげつ」と読む。"}, {"text": "可決", "is_correct": false, "explanation": "「かけつ」。「げ」が清音「け」になった清濁の対立。"}, {"text": "過激", "is_correct": false, "explanation": "「かげき」。最後の「つ」が「き」に変わった一モーラ差。"}, {"text": "加減", "is_correct": false, "explanation": "「かげん」。最後の「つ」が「ん」に変わった一モーラ差。"}], "explanations": {"箇月": "正解。「かげつ」と読む。", "可決": "「かけつ」。「げ」が清音「け」になった清濁の対立。", "過激": "「かげき」。最後の「つ」が「き」に変わった一モーラ差。", "加減": "「かげん」。最後の「つ」が「ん」に変わった一モーラ差。"}, "sentence_index": null, "correct_answer": "箇月"}, "level_3": {"options": [{"text": "箇月", "is_correct": true, "explanation": "月の数を数えるので「三箇月がたった」が正しい。"}, {"text": "冊", "is_correct": false, "explanation": "意味：「冊」は本を数える言葉で、時間の経過には使えない。"}, {"text": "枚", "is_correct": false, "explanation": "意味：「枚」は紙など薄い物を数える言葉。"}, {"text": "台", "is_correct": false, "explanation": "意味：「台」は機械や車を数える言葉。"}], "explanations": {"箇月": "月の数を数えるので「三箇月がたった」が正しい。", "冊": "意味：「冊」は本を数える言葉で、時間の経過には使えない。", "枚": "意味：「枚」は紙など薄い物を数える言葉。", "台": "意味：「台」は機械や車を数える言葉。"}, "sentence_index": 0, "correct_answer": "箇月"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このりんごは三箇月です。", "explanation": "意味：りんごの数を数えるのに月の単位は使えない。"}, {"text": "私の家族は四箇月です。", "explanation": "意味：人数を「箇月」で数えることはできない。"}, {"text": "鉛筆を二箇月買った。", "explanation": "意味：物の個数を「箇月」で数えるのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db60c17f-276a-483f-b4ff-eed0fd939a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
