INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35285, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "箇月", "is_correct": true, "explanation": "正解。「かげつ」と読む。"}, {"text": "仮説", "is_correct": false, "explanation": "「かせつ」。「げ」が「せ」に変わった一モーラ差。"}, {"text": "苛烈", "is_correct": false, "explanation": "「かれつ」。「げ」が「れ」に変わった一モーラ差。"}, {"text": "観月", "is_correct": false, "explanation": "「かんげつ」。「か」の後に「ん」が一モーラ加わる。"}], "explanations": {"箇月": "正解。「かげつ」と読む。", "仮説": "「かせつ」。「げ」が「せ」に変わった一モーラ差。", "苛烈": "「かれつ」。「げ」が「れ」に変わった一モーラ差。", "観月": "「かんげつ」。「か」の後に「ん」が一モーラ加わる。"}, "sentence_index": null, "correct_answer": "箇月"}, "level_3": {"options": [{"text": "箇月", "is_correct": true, "explanation": "旅行の長さを月の数で表すので「三箇月の旅行」が正しい。"}, {"text": "冊", "is_correct": false, "explanation": "意味：「冊」は本を数える言葉で、旅行の長さには使えない。"}, {"text": "本", "is_correct": false, "explanation": "意味：「本」は細長い物を数える言葉。"}, {"text": "枚", "is_correct": false, "explanation": "連語：「三枚の旅行」とは言わない。「枚」は薄い物を数える。"}], "explanations": {"箇月": "旅行の長さを月の数で表すので「三箇月の旅行」が正しい。", "冊": "意味：「冊」は本を数える言葉で、旅行の長さには使えない。", "本": "意味：「本」は細長い物を数える言葉。", "枚": "連語：「三枚の旅行」とは言わない。「枚」は薄い物を数える。"}, "sentence_index": 6, "correct_answer": "箇月"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "卵を二箇月ください。", "explanation": "意味：卵の個数を「箇月」で数えることはできない。「二個」が正しい。"}, {"text": "教室に生徒が十箇月いる。", "explanation": "意味：人の数は「人」で数える。"}, {"text": "切手を五箇月はった。", "explanation": "意味：切手の枚数を「箇月」で数えるのは誤り。「五枚」が正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db60c17f-276a-483f-b4ff-eed0fd939a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
