INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35286, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "図書", "is_correct": true, "explanation": "正解。「としょ」と読む。"}, {"text": "投書", "is_correct": false, "explanation": "「とうしょ」。「と」が長音「とう」になった長短の対立。"}, {"text": "徒手", "is_correct": false, "explanation": "「としゅ」。「しょ」が「しゅ」に変わった一モーラ差。"}, {"text": "都市", "is_correct": false, "explanation": "「とし」。最後の「しょ」が「し」に変わった一モーラ差。"}], "explanations": {"図書": "正解。「としょ」と読む。", "投書": "「とうしょ」。「と」が長音「とう」になった長短の対立。", "徒手": "「としゅ」。「しょ」が「しゅ」に変わった一モーラ差。", "都市": "「とし」。最後の「しょ」が「し」に変わった一モーラ差。"}, "sentence_index": null, "correct_answer": "図書"}, "level_3": {"options": [{"text": "図書", "is_correct": true, "explanation": "借りられる物なので「図書」が自然。"}, {"text": "天気", "is_correct": false, "explanation": "意味：天気は借りることができない。"}, {"text": "空気", "is_correct": false, "explanation": "意味：空気を二週間借りることはない。"}, {"text": "声", "is_correct": false, "explanation": "意味：声は貸し借りする物ではない。"}], "explanations": {"図書": "借りられる物なので「図書」が自然。", "天気": "意味：天気は借りることができない。", "空気": "意味：空気を二週間借りることはない。", "声": "意味：声は貸し借りする物ではない。"}, "sentence_index": 0, "correct_answer": "図書"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "図書を飲んでのどがうるおった。", "explanation": "意味：図書は本なので飲めない。"}, {"text": "図書が空を飛んで鳴いている。", "explanation": "意味：鳥のように鳴くのは図書ではない。"}, {"text": "朝ごはんに図書を焼いて食べた。", "explanation": "意味：図書は食べ物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db60c17f-276a-483f-b4ff-eed0fd939a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
