INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35286, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。この文では「が」が自然。"}, {"text": "を", "is_correct": false, "explanation": "「届く」は自動詞なので「を」はとらない。"}, {"text": "で", "is_correct": false, "explanation": "「で」では届いた物を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、届いた物を示せない。"}], "correct_answer": "が", "explanations": {"が": "正解。この文では「が」が自然。", "を": "「届く」は自動詞なので「を」はとらない。", "で": "「で」では届いた物を示せない。", "へ": "「へ」は方向を表し、届いた物を示せない。"}, "error_tags": {"を": "case", "で": "case", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db60c17f-276a-483f-b4ff-eed0fd939a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35286, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "図書", "is_correct": true, "explanation": "正解。「としょ」と読む。"}, {"text": "部署", "is_correct": false, "explanation": "「ぶしょ」。「と」が「ぶ」に変わった一モーラ差。"}, {"text": "古書", "is_correct": false, "explanation": "「こしょ」。「と」が「こ」に変わった一モーラ差。"}, {"text": "著書", "is_correct": false, "explanation": "「ちょしょ」。「と」が「ちょ」に変わった一モーラ差。"}], "explanations": {"図書": "正解。「としょ」と読む。", "部署": "「ぶしょ」。「と」が「ぶ」に変わった一モーラ差。", "古書": "「こしょ」。「と」が「こ」に変わった一モーラ差。", "著書": "「ちょしょ」。「と」が「ちょ」に変わった一モーラ差。"}, "sentence_index": null, "correct_answer": "図書"}, "level_3": {"options": [{"text": "図書", "is_correct": true, "explanation": "先生が本を紹介するので「図書」が正しい。"}, {"text": "天気", "is_correct": false, "explanation": "意味：天気を紹介するのは先生の行為として不自然。"}, {"text": "雨", "is_correct": false, "explanation": "意味：雨を紹介することはない。"}, {"text": "空気", "is_correct": false, "explanation": "意味：空気は紹介する対象ではない。"}], "explanations": {"図書": "先生が本を紹介するので「図書」が正しい。", "天気": "意味：天気を紹介するのは先生の行為として不自然。", "雨": "意味：雨を紹介することはない。", "空気": "意味：空気は紹介する対象ではない。"}, "sentence_index": 6, "correct_answer": "図書"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "図書を着て学校へ行った。", "explanation": "意味：図書は服ではない。"}, {"text": "図書に乗って駅まで行った。", "explanation": "意味：図書は乗り物ではない。"}, {"text": "図書が大きな声でほえた。", "explanation": "意味：図書は動物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db60c17f-276a-483f-b4ff-eed0fd939a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
