INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35287, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。この文では「が」が自然。"}, {"text": "を", "is_correct": false, "explanation": "「届く」は自動詞なので「を」はとらない。"}, {"text": "で", "is_correct": false, "explanation": "「で」では届いた物を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、届いた物を示せない。"}], "correct_answer": "が", "explanations": {"が": "正解。この文では「が」が自然。", "を": "「届く」は自動詞なので「を」はとらない。", "で": "「で」では届いた物を示せない。", "へ": "「へ」は方向を表し、届いた物を示せない。"}, "error_tags": {"を": "case", "で": "case", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db60c17f-276a-483f-b4ff-eed0fd939a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35287, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "図書", "is_correct": true, "explanation": "正解。「としょ」と読む。"}, {"text": "部署", "is_correct": false, "explanation": "「ぶしょ」。「と」が「ぶ」に変わった一モーラ差。"}, {"text": "古書", "is_correct": false, "explanation": "「こしょ」。「と」が「こ」に変わった一モーラ差。"}, {"text": "著書", "is_correct": false, "explanation": "「ちょしょ」。「と」が「ちょ」に変わった一モーラ差。"}], "explanations": {"図書": "正解。「としょ」と読む。", "部署": "「ぶしょ」。「と」が「ぶ」に変わった一モーラ差。", "古書": "「こしょ」。「と」が「こ」に変わった一モーラ差。", "著書": "「ちょしょ」。「と」が「ちょ」に変わった一モーラ差。"}, "sentence_index": null, "correct_answer": "図書"}, "level_3": {"options": [{"text": "図書", "is_correct": true, "explanation": "先生が本を紹介するので「図書」が正しい。"}, {"text": "天気", "is_correct": false, "explanation": "意味：天気を紹介するのは先生の行為として不自然。"}, {"text": "雨", "is_correct": false, "explanation": "意味：雨を紹介することはない。"}, {"text": "空気", "is_correct": false, "explanation": "意味：空気は紹介する対象ではない。"}], "explanations": {"図書": "先生が本を紹介するので「図書」が正しい。", "天気": "意味：天気を紹介するのは先生の行為として不自然。", "雨": "意味：雨を紹介することはない。", "空気": "意味：空気は紹介する対象ではない。"}, "sentence_index": 6, "correct_answer": "図書"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "図書を冷蔵庫で冷やして食べた。", "explanation": "意味：図書は食べ物ではない。"}, {"text": "図書が雨の中を走っていった。", "explanation": "意味：図書は自分で走らない。"}, {"text": "図書をはいて外に出た。", "explanation": "意味：図書は靴ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db60c17f-276a-483f-b4ff-eed0fd939a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35287, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "図書を一匹借りた。", "corrected_sentence": "図書を一冊借りた。", "error_description": "図書は動物ではないので「匹」で数えない。「冊」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db60c17f-276a-483f-b4ff-eed0fd939a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35287, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。この文では「に」が自然。"}, {"text": "を", "is_correct": false, "explanation": "場所を示す所に「を」は使えない。"}, {"text": "が", "is_correct": false, "explanation": "「学校が」だと届いた物が二つになり文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「学校と新しい図書が届いた」では学校まで届いた物になり意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "正解。この文では「に」が自然。", "を": "場所を示す所に「を」は使えない。", "が": "「学校が」だと届いた物が二つになり文が成り立たない。", "と": "「学校と新しい図書が届いた」では学校まで届いた物になり意味が通らない。"}, "error_tags": {"を": "case", "が": "case", "と": "case"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db60c17f-276a-483f-b4ff-eed0fd939a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35288, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "所蔵", "is_correct": true, "explanation": "正解。「しょぞう」と読む。"}, {"text": "所存", "is_correct": false, "explanation": "「しょぞん」。最後の「ぞう」が「ぞん」になる一モーラ差。"}, {"text": "肖像", "is_correct": false, "explanation": "「しょうぞう」。「しょ」が長音「しょう」になった長短の対立。"}, {"text": "書道", "is_correct": false, "explanation": "「しょどう」。「ぞ」が「ど」に変わった一モーラ差。"}], "explanations": {"所蔵": "正解。「しょぞう」と読む。", "所存": "「しょぞん」。最後の「ぞう」が「ぞん」になる一モーラ差。", "肖像": "「しょうぞう」。「しょ」が長音「しょう」になった長短の対立。", "書道": "「しょどう」。「ぞ」が「ど」に変わった一モーラ差。"}, "sentence_index": null, "correct_answer": "所蔵"}, "level_3": {"options": [{"text": "所蔵", "is_correct": true, "explanation": "図書館が本を持っているので「所蔵している」が正しい。"}, {"text": "運転", "is_correct": false, "explanation": "意味：本を運転することはできない。"}, {"text": "料理", "is_correct": false, "explanation": "意味：本を料理することはない。"}, {"text": "散歩", "is_correct": false, "explanation": "項構造：「散歩」は「を」で本をとれない。"}], "explanations": {"所蔵": "図書館が本を持っているので「所蔵している」が正しい。", "運転": "意味：本を運転することはできない。", "料理": "意味：本を料理することはない。", "散歩": "項構造：「散歩」は「を」で本をとれない。"}, "sentence_index": 0, "correct_answer": "所蔵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私はかぜを所蔵している。", "explanation": "意味：病気は所蔵する物ではない。"}, {"text": "妹は毎朝牛乳を所蔵して飲む。", "explanation": "意味：飲むために持つことは所蔵とは言わない。"}, {"text": "彼は友だちの気持ちを所蔵した。", "explanation": "意味：気持ちは所蔵の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db60c17f-276a-483f-b4ff-eed0fd939a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35288, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この図書館は古い本に所蔵している。", "corrected_sentence": "この図書館は古い本を所蔵している。", "error_description": "所蔵する物は「を」で示す。「本に所蔵している」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db60c17f-276a-483f-b4ff-eed0fd939a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35288, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。この文では「を」が自然。"}, {"text": "が", "is_correct": false, "explanation": "「資料が」では主語が二つになり不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」では所蔵する物を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表し、物を示せない。"}], "correct_answer": "を", "explanations": {"を": "正解。この文では「を」が自然。", "が": "「資料が」では主語が二つになり不自然。", "に": "「に」では所蔵する物を示せない。", "で": "「で」は場所や手段を表し、物を示せない。"}, "error_tags": {"が": "case", "に": "case", "で": "case"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db60c17f-276a-483f-b4ff-eed0fd939a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35288, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "所蔵", "is_correct": true, "explanation": "正解。「しょぞう」と読む。"}, {"text": "所属", "is_correct": false, "explanation": "「しょぞく」。最後の「う」が「く」に変わった一モーラ差。"}, {"text": "塑像", "is_correct": false, "explanation": "「そぞう」。「しょ」が「そ」に変わった一モーラ差。"}, {"text": "諸相", "is_correct": false, "explanation": "「しょそう」。「ぞ」が清音「そ」になった清濁の対立。"}], "explanations": {"所蔵": "正解。「しょぞう」と読む。", "所属": "「しょぞく」。最後の「う」が「く」に変わった一モーラ差。", "塑像": "「そぞう」。「しょ」が「そ」に変わった一モーラ差。", "諸相": "「しょそう」。「ぞ」が清音「そ」になった清濁の対立。"}, "sentence_index": null, "correct_answer": "所蔵"}, "level_3": {"options": [{"text": "所蔵", "is_correct": true, "explanation": "県が持っている資料という意味で「県の所蔵」が正しい。"}, {"text": "天気", "is_correct": false, "explanation": "意味：資料が天気であることはない。"}, {"text": "散歩", "is_correct": false, "explanation": "意味：資料は散歩ではない。"}, {"text": "気分", "is_correct": false, "explanation": "意味：資料が気分であることはない。"}], "explanations": {"所蔵": "県が持っている資料という意味で「県の所蔵」が正しい。", "天気": "意味：資料が天気であることはない。", "散歩": "意味：資料は散歩ではない。", "気分": "意味：資料が気分であることはない。"}, "sentence_index": 6, "correct_answer": "所蔵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は自分の名前を所蔵している。", "explanation": "意味：名前は保管する本や資料ではない。"}, {"text": "私は明日の予定を所蔵している。", "explanation": "意味：予定は所蔵する物ではない。"}, {"text": "彼は笑顔を所蔵して帰った。", "explanation": "意味：笑顔は所蔵の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db60c17f-276a-483f-b4ff-eed0fd939a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
