INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35289, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "所蔵", "is_correct": true, "explanation": "正解。「しょぞう」と読む。"}, {"text": "肖像", "is_correct": false, "explanation": "「しょうぞう」。「しょ」が長音になった長短の対立。"}, {"text": "所存", "is_correct": false, "explanation": "「しょぞん」。「ぞう」と「ぞん」の一モーラ差。"}, {"text": "書道", "is_correct": false, "explanation": "「しょどう」。「ぞ」と「ど」の一モーラ差。"}], "explanations": {"所蔵": "正解。「しょぞう」と読む。", "肖像": "「しょうぞう」。「しょ」が長音になった長短の対立。", "所存": "「しょぞん」。「ぞう」と「ぞん」の一モーラ差。", "書道": "「しょどう」。「ぞ」と「ど」の一モーラ差。"}, "sentence_index": null, "correct_answer": "所蔵"}, "level_3": {"options": [{"text": "所蔵", "is_correct": true, "explanation": "博物館が集めて保管している品を見に行くので「所蔵」が正しい。"}, {"text": "天気", "is_correct": false, "explanation": "意味：博物館の天気を見に行くのは不自然。"}, {"text": "返事", "is_correct": false, "explanation": "意味：博物館の返事は見に行く物ではない。"}, {"text": "散歩", "is_correct": false, "explanation": "意味：博物館の散歩を見に行くとは言わない。"}], "explanations": {"所蔵": "博物館が集めて保管している品を見に行くので「所蔵」が正しい。", "天気": "意味：博物館の天気を見に行くのは不自然。", "返事": "意味：博物館の返事は見に行く物ではない。", "散歩": "意味：博物館の散歩を見に行くとは言わない。"}, "sentence_index": 0, "correct_answer": "所蔵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎日の食事を所蔵して食べる。", "explanation": "意味：食べるための物は所蔵とは言わない。"}, {"text": "美術館が雨を所蔵している。", "explanation": "意味：雨は集めて保管する物ではない。"}, {"text": "私は昨日のけんかを所蔵した。", "explanation": "意味：出来事は所蔵の対象ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db60c17f-276a-483f-b4ff-eed0fd939a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
