INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35289, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。この文では「の」が自然。"}, {"text": "を", "is_correct": false, "explanation": "「美術館を所蔵」では美術館が持たれる物になる。"}, {"text": "に", "is_correct": false, "explanation": "「美術館に所蔵だ」は文法的に不自然。"}, {"text": "が", "is_correct": false, "explanation": "「美術館が所蔵だ」は不自然。"}], "correct_answer": "の", "explanations": {"の": "正解。この文では「の」が自然。", "を": "「美術館を所蔵」では美術館が持たれる物になる。", "に": "「美術館に所蔵だ」は文法的に不自然。", "が": "「美術館が所蔵だ」は不自然。"}, "error_tags": {"を": "case", "に": "case", "が": "case"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db60c17f-276a-483f-b4ff-eed0fd939a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35289, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "所蔵", "is_correct": true, "explanation": "正解。「しょぞう」と読む。"}, {"text": "所属", "is_correct": false, "explanation": "「しょぞく」。最後の「う」が「く」に変わった一モーラ差。"}, {"text": "塑像", "is_correct": false, "explanation": "「そぞう」。「しょ」が「そ」に変わった一モーラ差。"}, {"text": "諸相", "is_correct": false, "explanation": "「しょそう」。「ぞ」が清音「そ」になった清濁の対立。"}], "explanations": {"所蔵": "正解。「しょぞう」と読む。", "所属": "「しょぞく」。最後の「う」が「く」に変わった一モーラ差。", "塑像": "「そぞう」。「しょ」が「そ」に変わった一モーラ差。", "諸相": "「しょそう」。「ぞ」が清音「そ」になった清濁の対立。"}, "sentence_index": null, "correct_answer": "所蔵"}, "level_3": {"options": [{"text": "所蔵", "is_correct": true, "explanation": "寺が保管する品になったという意味で「所蔵」が正しい。"}, {"text": "天気", "is_correct": false, "explanation": "意味：像が天気になることはない。"}, {"text": "散歩", "is_correct": false, "explanation": "意味：像が散歩になることはない。"}, {"text": "返事", "is_correct": false, "explanation": "意味：像は返事ではない。"}], "explanations": {"所蔵": "寺が保管する品になったという意味で「所蔵」が正しい。", "天気": "意味：像が天気になることはない。", "散歩": "意味：像が散歩になることはない。", "返事": "意味：像は返事ではない。"}, "sentence_index": 6, "correct_answer": "所蔵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "所蔵の雨を大切に守っている。", "explanation": "意味：雨は保管する品ではない。"}, {"text": "所蔵の友だちと公園で遊んだ。", "explanation": "意味：人は所蔵の対象ではない。"}, {"text": "今朝のあいさつを所蔵した。", "explanation": "意味：あいさつは集めて保管する物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db60c17f-276a-483f-b4ff-eed0fd939a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
