INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35292, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "極めて", "is_correct": true, "explanation": "正解。「きわめて」と読む。"}, {"text": "清めて", "is_correct": false, "explanation": "「きよめて」（清める）。「わ」が「よ」に変わった一モーラ差。"}, {"text": "決め手", "is_correct": false, "explanation": "「きめて」。「わ」の一モーラがない。"}, {"text": "見極めて", "is_correct": false, "explanation": "「みきわめて」（見極める）。先頭に「み」が一モーラ加わる。"}], "explanations": {"極めて": "正解。「きわめて」と読む。", "清めて": "「きよめて」（清める）。「わ」が「よ」に変わった一モーラ差。", "決め手": "「きめて」。「わ」の一モーラがない。", "見極めて": "「みきわめて」（見極める）。先頭に「み」が一モーラ加わる。"}, "sentence_index": null, "correct_answer": "極めて"}, "level_3": {"options": [{"text": "極めて", "is_correct": true, "explanation": "程度がとても高いことを表すので「極めて難しい」が正しい。"}, {"text": "ゆっくり", "is_correct": false, "explanation": "意味：速さを表す語で、難しさの程度には合わない。"}, {"text": "まっすぐ", "is_correct": false, "explanation": "意味：方向を表す語で、形容詞を強められない。"}, {"text": "早く", "is_correct": false, "explanation": "連語：「早く難しい」とは言わない。"}], "explanations": {"極めて": "程度がとても高いことを表すので「極めて難しい」が正しい。", "ゆっくり": "意味：速さを表す語で、難しさの程度には合わない。", "まっすぐ": "意味：方向を表す語で、形容詞を強められない。", "早く": "連語：「早く難しい」とは言わない。"}, "sentence_index": 0, "correct_answer": "極めて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "極めて走って駅に行った。", "explanation": "連語：「極めて」は動作を直接修飾しない。"}, {"text": "彼は極めて本を読んだ。", "explanation": "連語：程度のない動作に「極めて」は使えない。"}, {"text": "極めて三人が来た。", "explanation": "意味：数に「極めて」は付けられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db60c17f-276a-483f-b4ff-eed0fd939a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35292, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "事故の可能性は極めてだ。", "corrected_sentence": "事故の可能性は極めて低い。", "error_description": "「極めて」は副詞なので、「だ」で述語にできない。形容詞を修飾させる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db60c17f-276a-483f-b4ff-eed0fd939a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35292, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "少し", "is_correct": true, "explanation": "「極めて」は程度が非常に高い、「少し」は程度が低いので反対。"}, {"text": "必ず", "is_correct": false, "explanation": "確実さを表す語で、程度の反対ではない。"}, {"text": "再び", "is_correct": false, "explanation": "繰り返しを表す語で、程度とは関係ない。"}, {"text": "急に", "is_correct": false, "explanation": "変化の速さを表し、程度の反対ではない。"}], "correct_answer": "少し", "explanations": {"少し": "「極めて」は程度が非常に高い、「少し」は程度が低いので反対。", "必ず": "確実さを表す語で、程度の反対ではない。", "再び": "繰り返しを表す語で、程度とは関係ない。", "急に": "変化の速さを表し、程度の反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db60c17f-276a-483f-b4ff-eed0fd939a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35292, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "極めて", "is_correct": true, "explanation": "正解。「きわめて」と読む。"}, {"text": "撓めて", "is_correct": false, "explanation": "「たわめて」（撓める）。「き」が「た」に変わった一モーラ差。"}, {"text": "刻めて", "is_correct": false, "explanation": "「きざめて」（刻める）。「わ」が「ざ」に変わった一モーラ差。"}, {"text": "清めて", "is_correct": false, "explanation": "「きよめて」（清める）。「わ」が「よ」に変わった一モーラ差。"}], "explanations": {"極めて": "正解。「きわめて」と読む。", "撓めて": "「たわめて」（撓める）。「き」が「た」に変わった一モーラ差。", "刻めて": "「きざめて」（刻める）。「わ」が「ざ」に変わった一モーラ差。", "清めて": "「きよめて」（清める）。「わ」が「よ」に変わった一モーラ差。"}, "sentence_index": null, "correct_answer": "極めて"}, "level_3": {"options": [{"text": "極めて", "is_correct": true, "explanation": "程度が非常に高いことを表すので「極めて短い」が正しい。"}, {"text": "ゆっくり", "is_correct": false, "explanation": "意味：「ゆっくり短い」は矛盾していて不自然。"}, {"text": "まっすぐ", "is_correct": false, "explanation": "意味：方向を表し、長さの程度に合わない。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "連語：「ぐっすり」は眠る様子にしか使わない。"}], "explanations": {"極めて": "程度が非常に高いことを表すので「極めて短い」が正しい。", "ゆっくり": "意味：「ゆっくり短い」は矛盾していて不自然。", "まっすぐ": "意味：方向を表し、長さの程度に合わない。", "ぐっすり": "連語：「ぐっすり」は眠る様子にしか使わない。"}, "sentence_index": 6, "correct_answer": "極めて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "極めて机がある。", "explanation": "連語：「極めて」は存在を表す文を修飾しない。"}, {"text": "極めて昨日、雨が降った。", "explanation": "意味：日時に「極めて」は付かない。"}, {"text": "私は極めて手紙を書いた。", "explanation": "連語：程度のない動作には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db60c17f-276a-483f-b4ff-eed0fd939a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generatio