INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35298, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "同じであること。", "primary_collocate": null, "pronunciation": "どういつ", "ipa": "doːitsɯ", "syllable_count": 4, "sentences": [{"text": "二人は同一の学校に通っている。", "target_word": "同一", "complexity_tier": "T3", "furigana": "ふたり どういつ がっこう かよ", "sentence_source": "generated"}, {"text": "この二つの文は同一だ。", "target_word": "同一", "complexity_tier": "T3", "furigana": "ふた ぶん どういつ", "sentence_source": "generated"}, {"text": "同一人物が何度も来た。", "target_word": "同一", "complexity_tier": "T3", "furigana": "どういつじんぶつ なんど き", "sentence_source": "generated"}, {"text": "同一の問題が二回出た。", "target_word": "同一", "complexity_tier": "T3", "furigana": "どういつ もんだい にかい で", "sentence_source": "generated"}, {"text": "AとBは同一ではない。", "target_word": "同一", "complexity_tier": "T3", "furigana": "どういつ", "sentence_source": "generated"}, {"text": "同一の色の服を着ている。", "target_word": "同一", "complexity_tier": "T3", "furigana": "どういつ いろ ふく き", "sentence_source": "generated"}, {"text": "答えが同一なので、写したと思われた。", "target_word": "同一", "complexity_tier": "T3", "furigana": "こた どういつ うつ おも", "sentence_source": "generated"}, {"text": "この絵と写真は同一の場所だ。", "target_word": "同一", "complexity_tier": "T3", "furigana": "え しゃしん どういつ ばしょ", "sentence_source": "generated"}, {"text": "同一の名前の人がクラスに二人いる。", "target_word": "同一", "complexity_tier": "T3", "furigana": "どういつ なまえ ひと ふたり", "sentence_source": "generated"}, {"text": "彼と私の意見は同一だった。", "target_word": "同一", "complexity_tier": "T3", "furigana": "かれ わたし いけん どういつ", "sentence_source": "generated"}], "morphological_forms": [{"form": "同一の", "label": "活用"}, {"form": "同一だ", "label": "活用"}, {"form": "同一人物", "label": "派生"}, {"form": "同一視", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | 二つ以上のものが全く同じであること", "collocate_grounding": {"status": "no_source", "reason