INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35305, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "百の数倍ほどの、はっきりしない数。", "primary_collocate": null, "pronunciation": "すうひゃく", "ipa": "sɯːçakɯ", "syllable_count": 4, "sentences": [{"text": "正確には分からないが、数百人はいた。", "target_word": "数百", "complexity_tier": "T3", "furigana": "せいかく わ すうひゃくにん", "sentence_source": "generated"}, {"text": "数百のメールがたまっている。", "target_word": "数百", "complexity_tier": "T3", "furigana": "すうひゃく", "sentence_source": "generated"}, {"text": "彼はこの曲を数百回聞いた。", "target_word": "数百", "complexity_tier": "T3", "furigana": "かれ きょく すうひゃっかい き", "sentence_source": "generated"}, {"text": "数百ものコメントが届いた。", "target_word": "数百", "complexity_tier": "T3", "furigana": "すうひゃく とど", "sentence_source": "generated"}, {"text": "川に数百匹の魚がいた。", "target_word": "数百", "complexity_tier": "T3", "furigana": "かわ すうひゃっぴき さかな", "sentence_source": "generated"}, {"text": "その事故で数百台が止まった。", "target_word": "数百", "complexity_tier": "T3", "furigana": "じこ すうひゃくだい と", "sentence_source": "generated"}, {"text": "数百の意見が集まったそうだ。", "target_word": "数百", "complexity_tier": "T3", "furigana": "すうひゃく いけん あつ", "sentence_source": "generated"}, {"text": "数えきれないが、数百個はある。", "target_word": "数百", "complexity_tier": "T3", "furigana": "かぞ すうひゃっこ", "sentence_source": "generated"}, {"text": "毎日数百人がこの道を通る。", "target_word": "数百", "complexity_tier": "T3", "furigana": "まいにち すうひゃくにん みち とお", "sentence_source": "generated"}, {"text": "数百枚の写真をとった。", "target_word": "数百", "complexity_tier": "T3", "furigana": "すうひゃくまい しゃしん", "sentence_source": "generated"}], "morphological_forms": [{"form": "数百人", "label": "助数詞"}, {"form": "数百個", "label": "助数詞"}, {"form": "数百回", "label": "助数詞"}, {"form": "数百万", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 百の数倍ほどの正確でない数", "collocate_grounding": {"status": "no_source", "reason"