INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35296, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "導入", "is_correct": true, "explanation": "聞こえた音「どうにゅう」そのもの。"}, {"text": "購入", "is_correct": false, "explanation": "「こうにゅう」。最初のモーラ「ど」が「こ」に替わる一モーラ差。"}, {"text": "投入", "is_correct": false, "explanation": "「とうにゅう」。最初の「ど」が清音「と」になる清濁の違い。"}, {"text": "混入", "is_correct": false, "explanation": "「こんにゅう」。一拍目「ど」が「こ」、二拍目「う」が「ん」になる。"}], "explanations": {"導入": "聞こえた音「どうにゅう」そのもの。", "購入": "「こうにゅう」。最初のモーラ「ど」が「こ」に替わる一モーラ差。", "投入": "「とうにゅう」。最初の「ど」が清音「と」になる清濁の違い。", "混入": "「こんにゅう」。一拍目「ど」が「こ」、二拍目「う」が「ん」になる。"}, "sentence_index": null, "correct_answer": "導入"}, "level_3": {"options": [{"text": "導入", "is_correct": true, "explanation": "意味：新しいパソコンを初めて取り入れたので合う。"}, {"text": "出発", "is_correct": false, "explanation": "意味：パソコンが出発することはない。"}, {"text": "注意", "is_correct": false, "explanation": "連語：「パソコンが注意された」は不自然。"}, {"text": "返事", "is_correct": false, "explanation": "意味：パソコンに返事は合わない。"}], "explanations": {"導入": "意味：新しいパソコンを初めて取り入れたので合う。", "出発": "意味：パソコンが出発することはない。", "注意": "連語：「パソコンが注意された」は不自然。", "返事": "意味：パソコンに返事は合わない。"}, "sentence_index": 0, "correct_answer": "導入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "機械の導入を食べて、元気になった。", "explanation": "連語の誤り：導入は食べるものではない。"}, {"text": "一冊の導入が始まった。", "explanation": "助数詞の誤り：導入は「冊」で数えない。"}, {"text": "明日、新しい機械が導入された。", "explanation": "アスペクトの誤り：「明日」と過去形「された」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5c6c66e-fc4f-480d-8fab-8c782e9c9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
